(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("gorg-e",[{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πολέμου καὶ μάχης φασὶ χρῆναι, ὦ Σώκρατες, οὕτω μεταλαγχάνειν.","st":"447a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἦ, τὸ λεγόμενον, κατόπιν ἑορτῆς ἥκομεν καὶ ὑστεροῦμεν;","st":"447a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> καὶ μάλα γε ἀστείας ἑορτῆς: πολλὰ γὰρ καὶ καλὰ Γοργίας ἡμῖν ὀλίγον πρότερον ἐπεδείξατο.","st":"447a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων μέντοι, ὦ Καλλίκλεις, αἴτιος Χαιρεφῶν ὅδε, ἐν ἀγορᾷ ἀναγκάσας ἡμᾶς διατρῖψαι.","st":"447a"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> οὐδὲν πρᾶγμα, ὦ Σώκρατες: ἐγὼ γὰρ καὶ ἰάσομαι. φίλος γάρ μοι Γοργίας, ὥστ’ ἐπιδείξεται ἡμῖν, εἰ μὲν δοκεῖ, νῦν, ἐὰν δὲ βούλῃ, εἰς αὖθις.","st":"447b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί δέ, ὦ Χαιρεφῶν; ἐπιθυμεῖ Σωκράτης ἀκοῦσαι Γοργίου;","st":"447b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> ἐπ’ αὐτό γέ τοι τοῦτο πάρεσμεν.","st":"447b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκοῦν ὅταν βούλησθε παρ’ ἐμὲ ἥκειν οἴκαδε: παρ’ ἐμοὶ γὰρ Γοργίας καταλύει καὶ ἐπιδείξεται ὑμῖν.","st":"447b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὖ λέγεις, ὦ Καλλίκλεις. ἀλλ’ ἆρα ἐθελήσειεν ἂν","st":"447b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμῖν διαλεχθῆναι; βούλομαι γὰρ πυθέσθαι παρ’ αὐτοῦ τίς ἡ δύναμις τῆς τέχνης τοῦ ἀνδρός, καὶ τί ἐστιν ὃ ἐπαγγέλλεταί τε καὶ διδάσκει: τὴν δὲ ἄλλην ἐπίδειξιν εἰς αὖθις, ὥσπερ σὺ λέγεις, ποιησάσθω.","st":"447c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐδὲν οἷον τὸ αὐτὸν ἐρωτᾶν, ὦ Σώκρατες. καὶ γὰρ αὐτῷ ἓν τοῦτ’ ἦν τῆς ἐπιδείξεως: ἐκέλευε γοῦν νυνδὴ ἐρωτᾶν ὅτι τις βούλοιτο τῶν ἔνδον ὄντων, καὶ πρὸς ἅπαντα ἔφη ἀποκρινεῖσθαι.","st":"447c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ καλῶς λέγεις. ὦ Χαιρεφῶν, ἐροῦ αὐτόν.","st":"447c"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> τί ἔρωμαι;","st":"447c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅστις ἐστίν.","st":"447d"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> πῶς λέγεις;","st":"447d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὥσπερ ἂν εἰ ἐτύγχανεν ὢν ὑποδημάτων δημιουργός, ἀπεκρίνατο ἂν δήπου σοι ὅτι σκυτοτόμος: ἢ οὐ μανθάνεις ὡς λέγω;","st":"447d"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> μανθάνω καὶ ἐρήσομαι. εἰπέ μοι, ὦ Γοργία, ἀληθῆ λέγει Καλλικλῆς ὅδε ὅτι ἐπαγγέλλῃ ἀποκρίνεσθαι ὅτι ἄν τίς σε ἐρωτᾷ;","st":"447d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ, ὦ Χαιρεφῶν: καὶ γὰρ νυνδὴ αὐτὰ ταῦτα ἐπηγγελλόμην, καὶ λέγω ὅτι οὐδείς μέ πω ἠρώτηκε καινὸν οὐδὲν πολλῶν ἐτῶν.","st":"448a"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> ἦ που ἄρα ῥᾳδίως ἀποκρινῇ, ὦ Γοργία.","st":"448a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάρεστι τούτου πεῖραν, ὦ Χαιρεφῶν, λαμβάνειν.","st":"448a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> νὴ Δία: ἂν δέ γε βούλῃ, ὦ Χαιρεφῶν, ἐμοῦ. Γοργίας μὲν γὰρ καὶ ἀπειρηκέναι μοι δοκεῖ: πολλὰ γὰρ ἄρτι διελήλυθεν.","st":"448a"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> τί δέ, ὦ Πῶλε; οἴει σὺ κάλλιον ἂν Γοργίου ἀποκρίνασθαι;","st":"448a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δὲ τοῦτο, ἐὰν σοί γε ἱκανῶς;","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> οὐδέν: ἀλλ’ ἐπειδὴ σὺ βούλει, ἀποκρίνου.","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> Ἐρώτα.","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> ἐρωτῶ δή. εἰ ἐτύγχανε Γοργίας ἐπιστήμων ὢν τῆς τέχνης ἧσπερ ὁ ἀδελφὸς αὐτοῦ Ἡρόδικος, τί ἂν αὐτὸν ὠνομάζομεν δικαίως; οὐχ ὅπερ ἐκεῖνον;","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> ἰατρὸν ἄρα φάσκοντες αὐτὸν εἶναι καλῶς ἂν ἐλέγομεν.","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> εἰ δέ γε ἧσπερ Ἀριστοφῶν ὁ Ἀγλαοφῶντος ἢ ὁ ἀδελφὸς αὐτοῦ ἔμπειρος ἦν τέχνης, τίνα ἂν αὐτὸν ὀρθῶς ἐκαλοῦμεν;","st":"448b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον ὅτι ζωγράφον.","st":"448c"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> νῦν δ’ ἐπειδὴ τίνος τέχνης ἐπιστήμων ἐστίν, τίνα ἂν καλοῦντες αὐτὸν ὀρθῶς καλοῖμεν;","st":"448c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὦ Χαιρεφῶν, πολλαὶ τέχναι ἐν ἀνθρώποις εἰσὶν ἐκ τῶν ἐμπειριῶν ἐμπείρως ηὑρημέναι: ἐμπειρία μὲν γὰρ ποιεῖ τὸν αἰῶνα ἡμῶν πορεύεσθαι κατὰ τέχνην, ἀπειρία δὲ κατὰ τύχην. ἑκάστων δὲ τούτων μεταλαμβάνουσιν ἄλλοι ἄλλων ἄλλως, τῶν δὲ ἀρίστων οἱ ἄριστοι: ὧν καὶ Γοργίας ἐστὶν ὅδε, καὶ μετέχει τῆς καλλίστης τῶν τεχνῶν.","st":"448c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς γε, ὦ Γοργία, φαίνεται Πῶλος παρεσκευάσθαι εἰς λόγους: ἀλλὰ γὰρ ὃ ὑπέσχετο Χαιρεφῶντι οὐ ποιεῖ.","st":"448d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τί μάλιστα, ὦ Σώκρατες;","st":"448d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ ἐρωτώμενον οὐ πάνυ μοι φαίνεται ἀποκρίνεσθαι.","st":"448d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλὰ σύ, εἰ βούλει, ἐροῦ αὐτόν.","st":"448d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκ, εἰ αὐτῷ γε σοὶ βουλομένῳ ἐστὶν ἀποκρίνεσθαι, ἀλλὰ πολὺ ἂν ἥδιον σέ. δῆλος γάρ μοι Πῶλος καὶ ἐξ ὧν εἴρηκεν ὅτι τὴν καλουμένην ῥητορικὴν μᾶλλον μεμελέτηκεν ἢ διαλέγεσθαι.","st":"448d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δή, ὦ Σώκρατες;","st":"448e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι, ὦ Πῶλε, ἐρομένου Χαιρεφῶντος τίνος Γοργίας ἐπιστήμων τέχνης, ἐγκωμιάζεις μὲν αὐτοῦ τὴν τέχνην ὥσπερ τινὸς ψέγοντος, ἥτις δέ ἐστιν οὐκ ἀπεκρίνω.","st":"448e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ γὰρ ἀπεκρινάμην ὅτι εἴη ἡ καλλίστη;","st":"448e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μάλα. ἀλλ’ οὐδεὶς ἐρωτᾷ ποία τις ἡ Γοργίου τέχνη, ἀλλὰ τίς, καὶ ὅντινα δέοι καλεῖν τὸν Γοργίαν: ὥσπερ τὰ ἔμπροσθέν σοι ὑπετείνατο Χαιρεφῶν: καὶ αὐτῷ καλῶς","st":"448e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ διὰ βραχέων ἀπεκρίνω, καὶ νῦν οὕτως εἰπὲ τίς ἡ τέχνη καὶ τίνα Γοργίαν καλεῖν χρὴ ἡμᾶς. μᾶλλον δέ, ὦ Γοργία, αὐτὸς ἡμῖν εἰπὲ τίνα σε χρὴ καλεῖν ὡς τίνος ἐπιστήμονα τέχνης.","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τῆς ῥητορικῆς, ὦ Σώκρατες.","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ῥήτορα ἄρα χρή σε καλεῖν;","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀγαθόν γε, ὦ Σώκρατες, εἰ δὴ ὅ γε εὔχομαι εἶναι, ὡς ἔφη Ὅμηρος, βούλει με καλεῖν.","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ βούλομαι.","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> κάλει δή.","st":"449a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἄλλους σε φῶμεν δυνατὸν εἶναι ποιεῖν;","st":"449b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἐπαγγέλλομαί γε δὴ ταῦτα οὐ μόνον ἐνθάδε ἀλλὰ καὶ ἄλλοθι.","st":"449b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν ἐθελήσαις ἄν, ὦ Γοργία, ὥσπερ νῦν διαλεγόμεθα, διατελέσαι τὸ μὲν ἐρωτῶν, τὸ δ’ ἀποκρινόμενος, τὸ δὲ μῆκος τῶν λόγων τοῦτο, οἷον καὶ Πῶλος ἤρξατο, εἰς αὖθις ἀποθέσθαι; ἀλλ’ ὅπερ ὑπισχνῇ, μὴ ψεύσῃ, ἀλλὰ ἐθέλησον κατὰ βραχὺ τὸ ἐρωτώμενον ἀποκρίνεσθαι.","st":"449b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> εἰσὶ μέν, ὦ Σώκρατες, ἔνιαι τῶν ἀποκρίσεων ἀναγκαῖαι διὰ μακρῶν τοὺς λόγους ποιεῖσθαι: οὐ μὴν ἀλλὰ","st":"449b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πειράσομαί γε ὡς διὰ βραχυτάτων. καὶ γὰρ αὖ καὶ τοῦτο ἕν ἐστιν ὧν φημι, μηδένα ἂν ἐν βραχυτέροις ἐμοῦ τὰ αὐτὰ εἰπεῖν.","st":"449c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτου μὴν δεῖ, ὦ Γοργία: καί μοι ἐπίδειξιν αὐτοῦ τούτου ποίησαι, τῆς βραχυλογίας, μακρολογίας δὲ εἰς αὖθις.","st":"449c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλὰ ποιήσω, καὶ οὐδενὸς φήσεις βραχυλογωτέρου ἀκοῦσαι.","st":"449c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή: ῥητορικῆς γὰρ φῂς ἐπιστήμων τέχνης","st":"449c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι καὶ ποιῆσαι ἂν καὶ ἄλλον ῥήτορα: ἡ ῥητορικὴ περὶ τί τῶν ὄντων τυγχάνει οὖσα; ὥσπερ ἡ ὑφαντικὴ περὶ τὴν τῶν ἱματίων ἐργασίαν: ἦ γάρ;","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἡ μουσικὴ περὶ τὴν τῶν μελῶν ποίησιν;","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νὴ τὴν Ἥραν, ὦ Γοργία, ἄγαμαί γε τὰς ἀποκρίσεις, ὅτι ἀποκρίνῃ ὡς οἷόν τε διὰ βραχυτάτων.","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γὰρ οἶμαι, ὦ Σώκρατες, ἐπιεικῶς τοῦτο ποιεῖν.","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὖ λέγεις. ἴθι δή μοι ἀπόκριναι οὕτως καὶ περὶ τῆς ῥητορικῆς, περὶ τί τῶν ὄντων ἐστὶν ἐπιστήμη;","st":"449d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> περὶ λόγους.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποίους τούτους, ὦ Γοργία; ἆρα οἳ δηλοῦσι τοὺς κάμνοντας, ὡς ἂν διαιτώμενοι ὑγιαίνοιεν;","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὔ.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα περὶ πάντας γε τοὺς λόγους ἡ ῥητορική ἐστιν.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐ δῆτα.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν λέγειν γε ποιεῖ δυνατούς.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν περὶ ὧνπερ λέγειν, καὶ φρονεῖν;","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πῶς γὰρ οὔ;","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν,","st":"449e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἣν νυνδὴ ἐλέγομεν, ἡ ἰατρικὴ περὶ τῶν καμνόντων ποιεῖ δυνατοὺς εἶναι φρονεῖν καὶ λέγειν;","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀνάγκη.","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἡ ἰατρικὴ ἄρα, ὡς ἔοικεν, περὶ λόγους ἐστίν.","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούς γε περὶ τὰ νοσήματα;","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> μάλιστα.","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἡ γυμναστικὴ περὶ λόγους ἐστὶν τοὺς περὶ εὐεξίαν τε τῶν σωμάτων καὶ καχεξίαν;","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ αἱ ἄλλαι τέχναι, ὦ Γοργία, οὕτως","st":"450a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχουσιν: ἑκάστη αὐτῶν περὶ λόγους ἐστὶν τούτους, οἳ τυγχάνουσιν ὄντες περὶ τὸ πρᾶγμα οὗ ἑκάστη ἐστὶν ἡ τέχνη.","st":"450b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> φαίνεται.","st":"450b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν δή ποτε τὰς ἄλλας τέχνας οὐ ῥητορικὰς καλεῖς, οὔσας περὶ λόγους, εἴπερ ταύτην ῥητορικὴν καλεῖς, ἣ ἂν ᾖ περὶ λόγους;","st":"450b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ὅτι, ὦ Σώκρατες, τῶν μὲν ἄλλων τεχνῶν περὶ χειρουργίας τε καὶ τοιαύτας πράξεις ὡς ἔπος εἰπεῖν πᾶσά ἐστιν ἡ ἐπιστήμη, τῆς δὲ ῥητορικῆς οὐδέν ἐστιν τοιοῦτον χειρούργημα, ἀλλὰ πᾶσα ἡ πρᾶξις καὶ ἡ κύρωσις διὰ λόγων","st":"450b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἐστίν. διὰ ταῦτ’ ἐγὼ τὴν ῥητορικὴν τέχνην ἀξιῶ εἶναι περὶ λόγους, ὀρθῶς λέγων, ὡς ἐγώ φημι.","st":"450c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν μανθάνω οἵαν αὐτὴν βούλει καλεῖν; τάχα δὲ εἴσομαι σαφέστερον. ἀλλ’ ἀπόκριναι: εἰσὶν ἡμῖν τέχναι. ἦ γάρ;","st":"450c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"450c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πασῶν δὴ οἶμαι τῶν τεχνῶν τῶν μὲν ἐργασία τὸ πολύ ἐστιν καὶ λόγου βραχέος δέονται, ἔνιαι δὲ οὐδενὸς ἀλλὰ τὸ τῆς τέχνης περαίνοιτο ἂν καὶ διὰ σιγῆς, οἷον γραφικὴ καὶ ἀνδριαντοποιία καὶ ἄλλαι πολλαί. τὰς τοιαύτας","st":"450c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μοι δοκεῖς λέγειν, περὶ ἃς οὐ φῂς τὴν ῥητορικὴν εἶναι: ἢ οὔ;","st":"450d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ μὲν οὖν καλῶς ὑπολαμβάνεις, ὦ Σώκρατες.","st":"450d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕτεραι δέ γέ εἰσι τῶν τεχνῶν αἳ διὰ λόγου πᾶν περαίνουσι, καὶ ἔργου ὡς ἔπος εἰπεῖν ἢ οὐδενὸς προσδέονται ἢ βραχέος πάνυ, οἷον ἡ ἀριθμητικὴ καὶ λογιστικὴ καὶ γεωμετρικὴ καὶ πεττευτική γε καὶ ἄλλαι πολλαὶ τέχναι, ὧν ἔνιαι σχεδόν τι ἴσους τοὺς λόγους ἔχουσι ταῖς πράξεσιν, αἱ δὲ πολλαὶ πλείους, καὶ τὸ παράπαν πᾶσα ἡ πρᾶξις καὶ τὸ","st":"450d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κῦρος αὐταῖς διὰ λόγων ἐστίν. τῶν τοιούτων τινά μοι δοκεῖς λέγειν τὴν ῥητορικήν.","st":"450e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ λέγεις.","st":"450e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὔτοι τούτων γε οὐδεμίαν οἶμαί σε βούλεσθαι ῥητορικὴν καλεῖν, οὐχ ὅτι τῷ ῥήματι οὕτως εἶπες, ὅτι ἡ διὰ λόγου τὸ κῦρος ἔχουσα ῥητορική ἐστιν, καὶ ὑπολάβοι ἄν τις, εἰ βούλοιτο δυσχεραίνειν ἐν τοῖς λόγοις, “τὴν ἀριθμητικὴν ἄρα ῥητορικήν, ὦ Γοργία, λέγεις;” ἀλλ’ οὐκ οἶμαί σε οὔτε τὴν ἀριθμητικὴν οὔτε τὴν γεωμετρίαν ῥητορικὴν λέγειν.","st":"450e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ὀρθῶς γὰρ οἴει, ὦ Σώκρατες, καὶ δικαίως ὑπολαμβάνεις.","st":"451a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι νυν καὶ σὺ τὴν ἀπόκρισιν ἣν ἠρόμην διαπέρανον. ἐπεὶ γὰρ ῥητορικὴ τυγχάνει μὲν οὖσα τούτων τις τῶν τεχνῶν τῶν τὸ πολὺ λόγῳ χρωμένων, τυγχάνουσιν δὲ καὶ ἄλλαι τοιαῦται οὖσαι, πειρῶ εἰπεῖν ἡ περὶ τί ἐν λόγοις τὸ κῦρος ἔχουσα ῥητορική ἐστιν. ὥσπερ ἂν εἴ τίς με ἔροιτο ὧν νυνδὴ ἔλεγον περὶ ἡστινοσοῦν τῶν τεχνῶν: “ὦ Σώκρατες, τίς","st":"451a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐστιν ἡ ἀριθμητικὴ τέχνη;” εἴποιμ’ ἂν αὐτῷ, ὥσπερ σὺ ἄρτι, ὅτι τῶν διὰ λόγου τις τὸ κῦρος ἐχουσῶν. καὶ εἴ με ἐπανέροιτο: “τῶν περὶ τί;” εἴποιμ’ ἂν ὅτι τῶν περὶ τὸ ἄρτιόν τε καὶ περιττὸν [γνῶσις], ὅσα ἂν ἑκάτερα τυγχάνῃ ὄντα. εἰ δ’ αὖ ἔροιτο: “τὴν δὲ λογιστικὴν τίνα καλεῖς τέχνην;” εἴποιμ’ ἂν ὅτι καὶ αὕτη ἐστὶν τῶν λόγῳ τὸ πᾶν κυρουμένων: καὶ εἰ ἐπανέροιτο: “ἡ περὶ τί;” εἴποιμ’ ἂν ὥσπερ οἱ ἐν τῷ δήμῳ","st":"451b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> συγγραφόμενοι, ὅτι τὰ μὲν ἄλλα καθάπερ ἡ ἀριθμητικὴ ἡ λογιστικὴ ἔχει — περὶ τὸ αὐτὸ γάρ ἐστιν, τό τε ἄρτιον καὶ τὸ περιττόν — διαφέρει δὲ τοσοῦτον, ὅτι καὶ πρὸς αὑτὰ καὶ πρὸς ἄλληλα πῶς ἔχει πλήθους ἐπισκοπεῖ τὸ περιττὸν καὶ τὸ ἄρτιον ἡ λογιστική. καὶ εἴ τις τὴν ἀστρονομίαν ἀνέροιτο, ἐμοῦ λέγοντος ὅτι καὶ αὕτη λόγῳ κυροῦται τὰ πάντα, “οἱ δὲ λόγοι οἱ τῆς ἀστρονομίας,” εἰ φαίη, “περὶ τί εἰσιν, ὦ Σώκρατες;” εἴποιμ’ ἂν ὅτι περὶ τὴν τῶν ἄστρων φορὰν καὶ ἡλίου καὶ σελήνης, πῶς πρὸς ἄλληλα τάχους ἔχει.","st":"451c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ὀρθῶς γε λέγων σύ, ὦ Σώκρατες.","st":"451c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δὴ καὶ σύ, ὦ Γοργία. τυγχάνει μὲν γὰρ δὴ ἡ ῥητορικὴ οὖσα τῶν λόγῳ τὰ πάντα διαπραττομένων τε καὶ κυρουμένων: ἦ γάρ;","st":"451d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔστι ταῦτα.","st":"451d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγε δὴ τῶν περὶ τί; ⟨τί⟩ ἐστι τοῦτο τῶν ὄντων, περὶ οὗ οὗτοι οἱ λόγοι εἰσὶν οἷς ἡ ῥητορικὴ χρῆται;","st":"451d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τὰ μέγιστα τῶν ἀνθρωπείων πραγμάτων, ὦ Σώκρατες, καὶ ἄριστα.","st":"451d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’, ὦ Γοργία, ἀμφισβητήσιμον καὶ τοῦτο λέγεις","st":"451d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οὐδέν πω σαφές. οἴομαι γάρ σε ἀκηκοέναι ἐν τοῖς συμποσίοις ᾀδόντων ἀνθρώπων τοῦτο τὸ σκολιόν, ἐν ᾧ καταριθμοῦνται ᾄδοντες ὅτι ὑγιαίνειν μὲν ἄριστόν ἐστιν, τὸ δὲ δεύτερον καλὸν γενέσθαι, τρίτον δέ, ὥς φησιν ὁ ποιητὴς τοῦ σκολιοῦ, τὸ πλουτεῖν ἀδόλως.","st":"451e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀκήκοα γάρ: ἀλλὰ πρὸς τί τοῦτο λέγεις;","st":"451e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι εἴ σοι αὐτίκα παρασταῖεν οἱ δημιουργοὶ τούτων ὧν ἐπῄνεσεν ὁ τὸ σκολιὸν ποιήσας, ἰατρός τε καὶ παιδοτρίβης καὶ χρηματιστής, καὶ εἴποι πρῶτον μὲν ὁ ἰατρὸς ὅτι “ὦ Σώκρατες, ἐξαπατᾷ σε Γοργίας οὐ γάρ ἐστιν ἡ τούτου τέχνη περὶ τὸ μέγιστον ἀγαθὸν τοῖς ἀνθρώποις, ἀλλ’ ἡ ἐμή” — εἰ οὖν αὐτὸν ἐγὼ ἐροίμην: σὺ δὲ τίς ὢν ταῦτα λέγεις; εἴποι ἂν ἴσως ὅτι ἰατρός. τί οὖν λέγεις; ἦ τὸ τῆς σῆς τέχνης ἔργον μέγιστόν ἐστιν ἀγαθόν; “πῶς γὰρ οὔ,” φαίη ἂν ἴσως, “ὦ Σώκρατες, ὑγίεια; τί δ’ ἐστὶν μεῖζον ἀγαθὸν","st":"452a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνθρώποις ὑγιείας;” εἰ δ’ αὖ μετὰ τοῦτον ὁ παιδοτρίβης εἴποι ὅτι “θαυμάζοιμί τἄν, ὦ Σώκρατες, καὶ αὐτὸς εἴ σοι ἔχοι Γοργίας μεῖζον ἀγαθὸν ἐπιδεῖξαι τῆς αὑτοῦ τέχνης ἢ ἐγὼ τῆς ἐμῆς:” εἴποιμ’ ἂν αὖ καὶ πρὸς τοῦτον: σὺ δὲ δὴ τίς εἶ, ὦ ἄνθρωπε, καὶ τί τὸ σὸν ἔργον; “παιδοτρίβης,” φαίη ἄν, “τὸ δὲ ἔργον μού ἐστιν καλούς τε καὶ ἰσχυροὺς ποιεῖν τοὺς ἀνθρώπους τὰ σώματα.” μετὰ δὲ τὸν παιδοτρίβην εἴποι ἂν ὁ χρηματιστής, ὡς ἐγᾦμαι πάνυ καταφρονῶν ἁπάντων:","st":"452b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> “σκόπει δῆτα, ὦ Σώκρατες, ἐάν σοι πλούτου φανῇ τι μεῖζον ἀγαθὸν ὂν ἢ παρὰ Γοργίᾳ ἢ παρ’ ἄλλῳ ὁτῳοῦν.” φαῖμεν ἂν οὖν πρὸς αὐτόν: τί δὲ δή; ἦ σὺ τούτου δημιουργός; φαίη ἄν. τίς ὤν; “χρηματιστής.” τί οὖν; κρίνεις σὺ μέγιστον ἀνθρώποις ἀγαθὸν εἶναι πλοῦτον; φήσομεν. “πῶς γὰρ οὔκ;” ἐρεῖ. καὶ μὴν ἀμφισβητεῖ γε Γοργίας ὅδε τὴν παρ’ αὑτῷ τέχνην μείζονος ἀγαθοῦ αἰτίαν εἶναι ἢ τὴν σήν, φαῖμεν ἂν ἡμεῖς. δῆλον οὖν ὅτι τὸ μετὰ τοῦτο ἔροιτ’ ἄν: “καὶ τί ἐστιν","st":"452c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο τὸ ἀγαθόν; ἀποκρινάσθω Γοργίας.” ἴθι οὖν νομίσας, ὦ Γοργία, ἐρωτᾶσθαι καὶ ὑπ’ ἐκείνων καὶ ὑπ’ ἐμοῦ, ἀπόκριναι τί ἐστιν τοῦτο ὃ φῂς σὺ μέγιστον ἀγαθὸν εἶναι τοῖς ἀνθρώποις καὶ σὲ δημιουργὸν εἶναι αὐτοῦ.","st":"452d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ὅπερ ἐστίν, ὦ Σώκρατες, τῇ ἀληθείᾳ μέγιστον ἀγαθὸν καὶ αἴτιον ἅμα μὲν ἐλευθερίας αὐτοῖς τοῖς ἀνθρώποις, ἅμα δὲ τοῦ ἄλλων ἄρχειν ἐν τῇ αὑτοῦ πόλει ἑκάστῳ.","st":"452d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν δὴ τοῦτο λέγεις;","st":"452d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τὸ πείθειν ἔγωγ’ οἷόν τ’ εἶναι τοῖς λόγοις καὶ ἐν δικαστηρίῳ δικαστὰς καὶ ἐν βουλευτηρίῳ βουλευτὰς καὶ ἐν ἐκκλησίᾳ ἐκκλησιαστὰς καὶ ἐν ἄλλῳ συλλόγῳ παντί, ὅστις ἂν πολιτικὸς σύλλογος γίγνηται. καίτοι ἐν ταύτῃ τῇ δυνάμει δοῦλον μὲν ἕξεις τὸν ἰατρόν, δοῦλον δὲ τὸν παιδοτρίβην: ὁ δὲ χρηματιστὴς οὗτος ἄλλῳ ἀναφανήσεται χρηματιζόμενος καὶ οὐχ αὑτῷ, ἀλλὰ σοὶ τῷ δυναμένῳ λέγειν καὶ πείθειν τὰ πλήθη.","st":"452e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν μοι δοκεῖς δηλῶσαι, ὦ Γοργία, ἐγγύτατα τὴν","st":"452e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ῥητορικὴν ἥντινα τέχνην ἡγῇ εἶναι, καὶ εἴ τι ἐγὼ συνίημι, λέγεις ὅτι πειθοῦς δημιουργός ἐστιν ἡ ῥητορική, καὶ ἡ πραγματεία αὐτῆς ἅπασα καὶ τὸ κεφάλαιον εἰς τοῦτο τελευτᾷ: ἢ ἔχεις τι λέγειν ἐπὶ πλέον τὴν ῥητορικὴν δύνασθαι ἢ πειθὼ τοῖς ἀκούουσιν ἐν τῇ ψυχῇ ποιεῖν;","st":"453a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐδαμῶς, ὦ Σώκρατες, ἀλλά μοι δοκεῖς ἱκανῶς ὁρίζεσθαι: ἔστιν γὰρ τοῦτο τὸ κεφάλαιον αὐτῆς.","st":"453a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄκουσον δή, ὦ Γοργία. ἐγὼ γὰρ εὖ ἴσθ’ ὅτι, ὡς","st":"453a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμαυτὸν πείθω, εἴπερ τις ἄλλος ἄλλῳ διαλέγεται βουλόμενος εἰδέναι αὐτὸ τοῦτο περὶ ὅτου ὁ λόγος ἐστίν, καὶ ἐμὲ εἶναι τούτων ἕνα: ἀξιῶ δὲ καὶ σέ.","st":"453b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τί οὖν δή, ὦ Σώκρατες;","st":"453b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ ἐρῶ νῦν. ἐγὼ τὴν ἀπὸ τῆς ῥητορικῆς πειθώ, ἥτις ποτ’ ἐστὶν ἣν σὺ λέγεις καὶ περὶ ὧντινων πραγμάτων ἐστὶν πειθώ, σαφῶς μὲν εὖ ἴσθ’ ὅτι οὐκ οἶδα, οὐ μὴν ἀλλ’ ὑποπτεύω γε ἣν οἶμαί σε λέγειν καὶ περὶ ὧν: οὐδὲν μέντοι ἧττον ἐρήσομαί σε τίνα ποτὲ λέγεις τὴν πειθὼ τὴν ἀπὸ τῆς","st":"453b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ῥητορικῆς καὶ περὶ τίνων αὐτὴν εἶναι. τοῦ ἕνεκα δὴ αὐτὸς ὑποπτεύων σὲ ἐρήσομαι, ἀλλ’ οὐκ αὐτὸς λέγω; οὐ σοῦ ἕνεκα ἀλλὰ τοῦ λόγου, ἵνα οὕτω προΐῃ ὡς μάλιστ’ ἂν ἡμῖν καταφανὲς ποιοῖ περὶ ὅτου λέγεται. σκόπει γὰρ εἴ σοι δοκῶ δικαίως ἀνερωτᾶν σε: ὥσπερ ἂν εἰ ἐτύγχανόν σε ἐρωτῶν τίς ἐστιν τῶν ζωγράφων Ζεῦξις, εἴ μοι εἶπες ὅτι ὁ τὰ ζῷα γράφων, ἆρ’ οὐκ ἂν δικαίως σε ἠρόμην ὁ τὰ ποῖα τῶν ζῴων γράφων καὶ ποῦ;","st":"453c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"453c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα διὰ τοῦτο, ὅτι καὶ ἄλλοι εἰσὶ ζωγράφοι γράφοντες ἄλλα πολλὰ ζῷα;","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δέ γε μηδεὶς ἄλλος ἢ Ζεῦξις ἔγραφε, καλῶς ἄν σοι ἀπεκέκριτο;","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πῶς γὰρ οὔ;","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δὴ καὶ περὶ τῆς ῥητορικῆς εἰπέ: πότερόν σοι δοκεῖ πειθὼ ποιεῖν ἡ ῥητορικὴ μόνη ἢ καὶ ἄλλαι τέχναι; λέγω δὲ τὸ τοιόνδε: ὅστις διδάσκει ὁτιοῦν πρᾶγμα, πότερον ὃ διδάσκει πείθει ἢ οὔ;","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐ δῆτα, ὦ Σώκρατες, ἀλλὰ πάντων μάλιστα πείθει.","st":"453d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάλιν δὴ ἐπὶ τῶν αὐτῶν τεχνῶν λέγωμεν ὧνπερ νυνδή: ἡ ἀριθμητικὴ οὐ διδάσκει ἡμᾶς ὅσα ἐστὶν τὰ τοῦ ἀριθμοῦ, καὶ ὁ ἀριθμητικὸς ἄνθρωπος;","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ πείθει;","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πειθοῦς ἄρα δημιουργός ἐστιν καὶ ἡ ἀριθμητική;","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> φαίνεται.","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐάν τις ἐρωτᾷ ἡμᾶς ποίας πειθοῦς καὶ περὶ τί, ἀποκρινούμεθά που αὐτῷ ὅτι τῆς διδασκαλικῆς τῆς περὶ τὸ","st":"453e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄρτιόν τε καὶ τὸ περιττὸν ὅσον ἐστίν: καὶ τὰς ἄλλας ἃς νυνδὴ ἐλέγομεν τέχνας ἁπάσας ἕξομεν ἀποδεῖξαι πειθοῦς δημιουργοὺς οὔσας καὶ ἧστινος καὶ περὶ ὅτι: ἢ οὔ;","st":"454a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"454a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα ῥητορικὴ μόνη πειθοῦς ἐστιν δημιουργός.","st":"454a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ λέγεις.","st":"454a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπειδὴ τοίνυν οὐ μόνη ἀπεργάζεται τοῦτο τὸ ἔργον, ἀλλὰ καὶ ἄλλαι, δικαίως ὥσπερ περὶ τοῦ ζωγράφου μετὰ τοῦτο ἐπανεροίμεθ’ ἂν τὸν λέγοντα: ποίας δὴ πειθοῦς καὶ τῆς περὶ τί πειθοῦς ἡ ῥητορική ἐστιν τέχνη; ἢ οὐ δοκεῖ σοι","st":"454a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δίκαιον εἶναι ἐπανερέσθαι;","st":"454b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔμοιγε.","st":"454b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀπόκριναι δή, ὦ Γοργία, ἐπειδή γε καὶ σοὶ δοκεῖ οὕτως.","st":"454b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ταύτης τοίνυν τῆς πειθοῦς λέγω, ὦ Σώκρατες, τῆς ἐν τοῖς δικαστηρίοις καὶ ἐν τοῖς ἄλλοις ὄχλοις, ὥσπερ καὶ ἄρτι ἔλεγον, καὶ περὶ τούτων ἅ ἐστι δίκαιά τε καὶ ἄδικα.","st":"454b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐγώ τοι ὑπώπτευον ταύτην σε λέγειν τὴν πειθὼ καὶ περὶ τούτων, ὦ Γοργία: ἀλλ’ ἵνα μὴ θαυμάζῃς ἐὰν καὶ ὀλίγον ὕστερον τοιοῦτόν τί σε ἀνέρωμαι, ὃ δοκεῖ μὲν δῆλον","st":"454b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι, ἐγὼ δ’ ἐπανερωτῶ — ὅπερ γὰρ λέγω, τοῦ ἑξῆς ἕνεκα περαίνεσθαι τὸν λόγον ἐρωτῶ, οὐ σοῦ ἕνεκα ἀλλ’ ἵνα μὴ ἐθιζώμεθα ὑπονοοῦντες προαρπάζειν ἀλλήλων τὰ λεγόμενα, ἀλλὰ σὺ τὰ σαυτοῦ κατὰ τὴν ὑπόθεσιν ὅπως ἂν βούλῃ περαίνῃς.","st":"454c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> καὶ ὀρθῶς γέ μοι δοκεῖς ποιεῖν, ὦ Σώκρατες.","st":"454c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δὴ καὶ τόδε ἐπισκεψώμεθα. καλεῖς τι μεμαθηκέναι;","st":"454c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> καλῶ.","st":"454c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; πεπιστευκέναι;","st":"454c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔγωγε.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν ταὐτὸν δοκεῖ σοι εἶναι μεμαθηκέναι καὶ πεπιστευκέναι, καὶ μάθησις καὶ πίστις, ἢ ἄλλο τι;","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οἴομαι μὲν ἔγωγε, ὦ Σώκρατες, ἄλλο.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς γὰρ οἴει: γνώσῃ δὲ ἐνθένδε. εἰ γάρ τίς σε ἔροιτο: “ἆρ’ ἔστιν τις, ὦ Γοργία, πίστις ψευδὴς καὶ ἀληθής;” φαίης ἄν, ὡς ἐγὼ οἶμαι.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἐπιστήμη ἐστὶν ψευδὴς καὶ ἀληθής;","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐδαμῶς.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δῆλον ἄρ’ αὖ ὅτι οὐ ταὐτόν ἐστιν.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ λέγεις.","st":"454d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν οἵ τέ γε μεμαθηκότες πεπεισμένοι εἰσὶν καὶ οἱ πεπιστευκότες.","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔστι ταῦτα.","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει οὖν δύο εἴδη θῶμεν πειθοῦς, τὸ μὲν πίστιν παρεχόμενον ἄνευ τοῦ εἰδέναι, τὸ δ’ ἐπιστήμην;","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποτέραν οὖν ἡ ῥητορικὴ πειθὼ ποιεῖ ἐν δικαστηρίοις τε καὶ τοῖς ἄλλοις ὄχλοις περὶ τῶν δικαίων τε καὶ ἀδίκων; ἐξ ἧς πιστεύειν γίγνεται ἄνευ τοῦ εἰδέναι ἢ ἐξ ἧς τὸ εἰδέναι;","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> δῆλον δήπου, ὦ Σώκρατες, ὅτι ἐξ ἧς τὸ πιστεύειν.","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ ῥητορικὴ ἄρα, ὡς ἔοικεν, πειθοῦς","st":"454e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δημιουργός ἐστιν πιστευτικῆς ἀλλ’ οὐ διδασκαλικῆς περὶ τὸ δίκαιόν τε καὶ ἄδικον.","st":"455a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"455a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ’ ἄρα διδασκαλικὸς ὁ ῥήτωρ ἐστὶν δικαστηρίων τε καὶ τῶν ἄλλων ὄχλων δικαίων τε πέρι καὶ ἀδίκων, ἀλλὰ πιστικὸς μόνον: οὐ γὰρ δήπου ὄχλον γ’ ἂν δύναιτο τοσοῦτον ἐν ὀλίγῳ χρόνῳ διδάξαι οὕτω μεγάλα πράγματα.","st":"455a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐ δῆτα.","st":"455a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, ἴδωμεν τί ποτε καὶ λέγομεν περὶ τῆς","st":"455a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ῥητορικῆς: ἐγὼ μὲν γάρ τοι οὐδ’ αὐτός πω δύναμαι κατανοῆσαι ὅτι λέγω. ὅταν περὶ ἰατρῶν αἱρέσεως ᾖ τῇ πόλει σύλλογος ἢ περὶ ναυπηγῶν ἢ περὶ ἄλλου τινὸς δημιουργικοῦ ἔθνους, ἄλλο τι ἢ τότε ὁ ῥητορικὸς οὐ συμβουλεύσει; δῆλον γὰρ ὅτι ἐν ἑκάστῃ αἱρέσει τὸν τεχνικώτατον δεῖ αἱρεῖσθαι. οὐδ’ ὅταν τειχῶν περὶ οἰκοδομήσεως ἢ λιμένων κατασκευῆς ἢ νεωρίων, ἀλλ’ οἱ ἀρχιτέκτονες: οὐδ’ αὖ ὅταν στρατηγῶν αἱρέσεως πέρι ἢ τάξεώς τινος πρὸς πολεμίους ἢ χωρίων","st":"455b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καταλήψεως συμβουλὴ ᾖ, ἀλλ’ οἱ στρατηγικοὶ τότε συμβουλεύσουσιν, οἱ ῥητορικοὶ δὲ οὔ: ἢ πῶς λέγεις, ὦ Γοργία, τὰ τοιαῦτα; ἐπειδὴ γὰρ αὐτός τε φῂς ῥήτωρ εἶναι καὶ ἄλλους ποιεῖν ῥητορικούς, εὖ ἔχει τὰ τῆς σῆς τέχνης παρὰ σοῦ πυνθάνεσθαι. καὶ ἐμὲ νῦν νόμισον καὶ τὸ σὸν σπεύδειν: ἴσως γὰρ καὶ τυγχάνει τις τῶν ἔνδον ὄντων μαθητής σου βουλόμενος γενέσθαι, ὡς ἐγώ τινας σχεδὸν καὶ συχνοὺς αἰσθάνομαι, οἳ ἴσως αἰσχύνοιντ’ ἄν σε ἀνερέσθαι. ὑπ’","st":"455c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμοῦ οὖν ἀνερωτώμενος νόμισον καὶ ὑπ’ ἐκείνων ἀνερωτᾶσθαι: “τί ἡμῖν, ὦ Γοργία, ἔσται, ἐάν σοι συνῶμεν; περὶ τίνων τῇ πόλει συμβουλεύειν οἷοί τε ἐσόμεθα; πότερον περὶ δικαίου μόνον καὶ ἀδίκου ἢ καὶ περὶ ὧν νυνδὴ Σωκράτης ἔλεγεν;” πειρῶ οὖν αὐτοῖς ἀποκρίνεσθαι.","st":"455d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλ’ ἐγώ σοι πειράσομαι, ὦ Σώκρατες, σαφῶς ἀποκαλύψαι τὴν τῆς ῥητορικῆς δύναμιν ἅπασαν: αὐτὸς γὰρ καλῶς ὑφηγήσω. οἶσθα γὰρ δήπου ὅτι τὰ νεώρια ταῦτα","st":"455d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> καὶ τὰ τείχη τὰ Ἀθηναίων καὶ ἡ τῶν λιμένων κατασκευὴ ἐκ τῆς Θεμιστοκλέους συμβουλῆς γέγονεν, τὰ δ’ ἐκ τῆς Περικλέους ἀλλ’ οὐκ ἐκ τῶν δημιουργῶν.","st":"455e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγεται ταῦτα, ὦ Γοργία, περὶ Θεμιστοκλέους: Περικλέους δὲ καὶ αὐτὸς ἤκουον ὅτε συνεβούλευεν ἡμῖν περὶ τοῦ διὰ μέσου τείχους.","st":"455e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> καὶ ὅταν γέ τις αἵρεσις ᾖ ὧν νυνδὴ σὺ ἔλεγες, ὦ Σώκρατες, ὁρᾷς ὅτι οἱ ῥήτορές εἰσιν οἱ συμβουλεύοντες καὶ οἱ νικῶντες τὰς γνώμας περὶ τούτων.","st":"456a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα καὶ θαυμάζων, ὦ Γοργία, πάλαι ἐρωτῶ τίς ποτε ἡ δύναμίς ἐστιν τῆς ῥητορικῆς. δαιμονία γάρ τις ἔμοιγε καταφαίνεται τὸ μέγεθος οὕτω σκοποῦντι.","st":"456a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> εἰ πάντα γε εἰδείης, ὦ Σώκρατες, ὅτι ὡς ἔπος εἰπεῖν ἁπάσας τὰς δυνάμεις συλλαβοῦσα ὑφ’ αὑτῇ ἔχει.","st":"456a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> μέγα δέ σοι τεκμήριον ἐρῶ: πολλάκις γὰρ ἤδη ἔγωγε μετὰ τοῦ ἀδελφοῦ καὶ μετὰ τῶν ἄλλων ἰατρῶν εἰσελθὼν παρά τινα τῶν καμνόντων οὐχὶ ἐθέλοντα ἢ φάρμακον πιεῖν ἢ τεμεῖν ἢ καῦσαι παρασχεῖν τῷ ἰατρῷ, οὐ δυναμένου τοῦ ἰατροῦ πεῖσαι, ἐγὼ ἔπεισα, οὐκ ἄλλῃ τέχνῃ ἢ τῇ ῥητορικῇ. φημὶ δὲ καὶ εἰς πόλιν ὅπῃ βούλει ἐλθόντα ῥητορικὸν ἄνδρα καὶ ἰατρόν, εἰ δέοι λόγῳ διαγωνίζεσθαι ἐν ἐκκλησίᾳ ἢ ἐν ἄλλῳ τινὶ συλλόγῳ ὁπότερον δεῖ αἱρεθῆναι ἰατρόν, οὐδαμοῦ","st":"456b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἂν φανῆναι τὸν ἰατρόν, ἀλλ’ αἱρεθῆναι ἂν τὸν εἰπεῖν δυνατόν, εἰ βούλοιτο. καὶ εἰ πρὸς ἄλλον γε δημιουργὸν ὁντιναοῦν ἀγωνίζοιτο, πείσειεν ἂν αὑτὸν ἑλέσθαι ὁ ῥητορικὸς μᾶλλον ἢ ἄλλος ὁστισοῦν: οὐ γὰρ ἔστιν περὶ ὅτου οὐκ ἂν πιθανώτερον εἴποι ὁ ῥητορικὸς ἢ ἄλλος ὁστισοῦν τῶν δημιουργῶν ἐν πλήθει. ἡ μὲν οὖν δύναμις τοσαύτη ἐστὶν καὶ τοιαύτη τῆς τέχνης: δεῖ μέντοι, ὦ Σώκρατες, τῇ ῥητορικῇ χρῆσθαι ὥσπερ τῇ ἄλλῃ πάσῃ ἀγωνίᾳ. καὶ γὰρ","st":"456c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τῇ ἄλλῃ ἀγωνίᾳ οὐ τούτου ἕνεκα δεῖ πρὸς ἅπαντας χρῆσθαι ἀνθρώπους, ὅτι ἔμαθεν πυκτεύειν τε καὶ παγκρατιάζειν καὶ ἐν ὅπλοις μάχεσθαι, ὥστε κρείττων εἶναι καὶ φίλων καὶ ἐχθρῶν, οὐ τούτου ἕνεκα τοὺς φίλους δεῖ τύπτειν οὐδὲ κεντεῖν τε καὶ ἀποκτεινύναι. οὐδέ γε μὰ Δία ἐάν τις εἰς παλαίστραν φοιτήσας εὖ ἔχων τὸ σῶμα καὶ πυκτικὸς γενόμενος, ἔπειτα τὸν πατέρα τύπτῃ καὶ τὴν μητέρα ἢ ἄλλον τινὰ τῶν οἰκείων ἢ τῶν φίλων, οὐ τούτου ἕνεκα δεῖ τοὺς","st":"456d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> παιδοτρίβας καὶ τοὺς ἐν τοῖς ὅπλοις διδάσκοντας μάχεσθαι μισεῖν τε καὶ ἐκβάλλειν ἐκ τῶν πόλεων. ἐκεῖνοι μὲν γὰρ παρέδοσαν ἐπὶ τῷ δικαίως χρῆσθαι τούτοις πρὸς τοὺς πολεμίους καὶ τοὺς ἀδικοῦντας, ἀμυνομένους, μὴ ὑπάρχοντας:","st":"456e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οἱ δὲ μεταστρέψαντες χρῶνται τῇ ἰσχύϊ καὶ τῇ τέχνῃ οὐκ ὀρθῶς. οὔκουν οἱ διδάξαντες πονηροί, οὐδὲ ἡ τέχνη οὔτε αἰτία οὔτε πονηρὰ τούτου ἕνεκά ἐστιν, ἀλλ’ οἱ μὴ χρώμενοι οἶμαι ὀρθῶς. ὁ αὐτὸς δὴ λόγος καὶ περὶ τῆς ῥητορικῆς. δυνατὸς μὲν γὰρ πρὸς ἅπαντάς ἐστιν ὁ ῥήτωρ καὶ περὶ παντὸς λέγειν, ὥστε πιθανώτερος εἶναι ἐν τοῖς πλήθεσιν","st":"457a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔμβραχυ περὶ ὅτου ἂν βούληται: ἀλλ’ οὐδέν τι μᾶλλον τούτου ἕνεκα δεῖ οὔτε τοὺς ἰατροὺς τὴν δόξαν ἀφαιρεῖσθαι — ὅτι δύναιτο ἂν τοῦτο ποιῆσαι — οὔτε τοὺς ἄλλους δημιουργούς, ἀλλὰ δικαίως καὶ τῇ ῥητορικῇ χρῆσθαι, ὥσπερ καὶ τῇ ἀγωνίᾳ. ἐὰν δὲ οἶμαι ῥητορικὸς γενόμενός τις κᾆτα ταύτῃ τῇ δυνάμει καὶ τῇ τέχνῃ ἀδικῇ, οὐ τὸν διδάξαντα δεῖ μισεῖν τε καὶ ἐκβάλλειν ἐκ τῶν πόλεων. ἐκεῖνος μὲν γὰρ ἐπὶ","st":"457b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> δικαίου χρείᾳ παρέδωκεν, ὁ δ’ ἐναντίως χρῆται. τὸν οὖν οὐκ ὀρθῶς χρώμενον μισεῖν δίκαιον καὶ ἐκβάλλειν καὶ ἀποκτεινύναι ἀλλ’ οὐ τὸν διδάξαντα.","st":"457c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶμαι, ὦ Γοργία, καὶ σὲ ἔμπειρον εἶναι πολλῶν λόγων καὶ καθεωρακέναι ἐν αὐτοῖς τὸ τοιόνδε, ὅτι οὐ ῥᾳδίως δύνανται περὶ ὧν ἂν ἐπιχειρήσωσιν διαλέγεσθαι διορισάμενοι πρὸς ἀλλήλους καὶ μαθόντες καὶ διδάξαντες ἑαυτούς,","st":"457c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὕτω διαλύεσθαι τὰς συνουσίας, ἀλλ’ ἐὰν περί του ἀμφισβητήσωσιν καὶ μὴ φῇ ὁ ἕτερος τὸν ἕτερον ὀρθῶς λέγειν ἢ μὴ σαφῶς, χαλεπαίνουσί τε καὶ κατὰ φθόνον οἴονται τὸν ἑαυτῶν λέγειν, φιλονικοῦντας ἀλλ’ οὐ ζητοῦντας τὸ προκείμενον ἐν τῷ λόγῳ: καὶ ἔνιοί γε τελευτῶντες αἴσχιστα ἀπαλλάττονται, λοιδορηθέντες τε καὶ εἰπόντες καὶ ἀκούσαντες περὶ σφῶν αὐτῶν τοιαῦτα οἷα καὶ τοὺς παρόντας ἄχθεσθαι ὑπὲρ σφῶν αὐτῶν, ὅτι τοιούτων ἀνθρώπων ἠξίωσαν","st":"457d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀκροαταὶ γενέσθαι. τοῦ δὴ ἕνεκα λέγω ταῦτα; ὅτι νῦν ἐμοὶ δοκεῖς σὺ οὐ πάνυ ἀκόλουθα λέγειν οὐδὲ σύμφωνα οἷς τὸ πρῶτον ἔλεγες περὶ τῆς ῥητορικῆς: φοβοῦμαι οὖν διελέγχειν σε, μή με ὑπολάβῃς οὐ πρὸς τὸ πρᾶγμα φιλονικοῦντα λέγειν τοῦ καταφανὲς γενέσθαι, ἀλλὰ πρὸς σέ.","st":"457e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ οὖν, εἰ μὲν καὶ σὺ εἶ τῶν ἀνθρώπων ὧνπερ καὶ ἐγώ, ἡδέως ἄν σε διερωτῴην: εἰ δὲ μή, ἐῴην ἄν. ἐγὼ δὲ τίνων εἰμί; τῶν ἡδέως μὲν ἂν ἐλεγχθέντων εἴ τι μὴ ἀληθὲς λέγω, ἡδέως δ’ ἂν ἐλεγξάντων εἴ τίς τι μὴ ἀληθὲς λέγοι, οὐκ ἀηδέστερον μεντἂν ἐλεγχθέντων ἢ ἐλεγξάντων: μεῖζον γὰρ αὐτὸ ἀγαθὸν ἡγοῦμαι, ὅσῳπερ μεῖζον ἀγαθόν ἐστιν αὐτὸν ἀπαλλαγῆναι κακοῦ τοῦ μεγίστου ἢ ἄλλον ἀπαλλάξαι. οὐδὲν γὰρ οἶμαι τοσοῦτον κακὸν εἶναι ἀνθρώπῳ, ὅσον δόξα","st":"458a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ψευδὴς περὶ ὧν τυγχάνει νῦν ἡμῖν ὁ λόγος ὤν. εἰ μὲν οὖν καὶ σὺ φῂς τοιοῦτος εἶναι, διαλεγώμεθα: εἰ δὲ καὶ δοκεῖ χρῆναι ἐᾶν, ἐῶμεν ἤδη χαίρειν καὶ διαλύωμεν τὸν λόγον.","st":"458b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλὰ φημὶ μὲν ἔγωγε, ὦ Σώκρατες, καὶ αὐτὸς τοιοῦτος εἶναι οἷον σὺ ὑφηγῇ: ἴσως μέντοι χρῆν ἐννοεῖν καὶ τὸ τῶν παρόντων. πάλαι γάρ τοι, πρὶν καὶ ὑμᾶς ἐλθεῖν, ἐγὼ τοῖς παροῦσι πολλὰ ἐπεδειξάμην, καὶ νῦν ἴσως πόρρω ἀποτενοῦμεν,","st":"458b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἢν διαλεγώμεθα. σκοπεῖν οὖν χρὴ καὶ τὸ τούτων, μή τινας αὐτῶν κατέχομεν βουλομένους τι καὶ ἄλλο πράττειν.","st":"458c"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> τοῦ μὲν θορύβου, ὦ Γοργία τε καὶ Σώκρατες, αὐτοὶ ἀκούετε τούτων τῶν ἀνδρῶν βουλομένων ἀκούειν ἐάν τι λέγητε: ἐμοὶ δ’ οὖν καὶ αὐτῷ μὴ γένοιτο τοσαύτη ἀσχολία, ὥστε τοιούτων λόγων καὶ οὕτω λεγομένων ἀφεμένῳ προὐργιαίτερόν τι γενέσθαι ἄλλο πράττειν.","st":"458c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> νὴ τοὺς θεούς, ὦ Χαιρεφῶν, καὶ μὲν δὴ καὶ αὐτὸς πολλοῖς ἤδη λόγοις παραγενόμενος οὐκ οἶδ’ εἰ πώποτε ἥσθην οὕτως ὥσπερ νυνί: ὥστ’ ἔμοιγε, κἂν τὴν ἡμέραν ὅλην ἐθέλητε διαλέγεσθαι, χαριεῖσθε.","st":"458d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μήν, ὦ Καλλίκλεις, τό γ’ ἐμὸν οὐδὲν κωλύει, εἴπερ ἐθέλει Γοργίας.","st":"458d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> αἰσχρὸν δὴ τὸ λοιπόν, ὦ Σώκρατες, γίγνεται ἐμέ γε μὴ ἐθέλειν, αὐτὸν ἐπαγγειλάμενον ἐρωτᾶν ὅτι τις βούλεται.","st":"458d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλ’ εἰ δοκεῖ τουτοισί, διαλέγου τε καὶ ἐρώτα ὅτι βούλει.","st":"458e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄκουε δή, ὦ Γοργία, ἃ θαυμάζω ἐν τοῖς λεγομένοις ὑπὸ σοῦ: ἴσως γάρ τοι σοῦ ὀρθῶς λέγοντος ἐγὼ οὐκ ὀρθῶς ὑπολαμβάνω. ῥητορικὸν φῂς ποιεῖν οἷός τ’ εἶναι, ἐάν τις βούληται παρὰ σοῦ μανθάνειν;","st":"458e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"458e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν περὶ πάντων ὥστ’ ἐν ὄχλῳ πιθανὸν εἶναι, οὐ διδάσκοντα ἀλλὰ","st":"458e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πείθοντα;","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ μὲν οὖν.","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔλεγές τοι νυνδὴ ὅτι καὶ περὶ τοῦ ὑγιεινοῦ τοῦ ἰατροῦ πιθανώτερος ἔσται ὁ ῥήτωρ.","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> καὶ γὰρ ἔλεγον, ἔν γε ὄχλῳ.","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ ἐν ὄχλῳ τοῦτό ἐστιν, ἐν τοῖς μὴ εἰδόσιν; οὐ γὰρ δήπου ἔν γε τοῖς εἰδόσι τοῦ ἰατροῦ πιθανώτερος ἔσται.","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ λέγεις.","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ τοῦ ἰατροῦ πιθανώτερος ἔσται, τοῦ εἰδότος πιθανώτερος γίγνεται;","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ","st":"459a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> γε.","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἰατρός γε ὤν: ἦ γάρ;","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δὲ μὴ ἰατρός γε δήπου ἀνεπιστήμων ὧν ὁ ἰατρὸς ἐπιστήμων.","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> δῆλον ὅτι.","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ οὐκ εἰδὼς ἄρα τοῦ εἰδότος ἐν οὐκ εἰδόσι πιθανώτερος ἔσται, ὅταν ὁ ῥήτωρ τοῦ ἰατροῦ πιθανώτερος ᾖ. τοῦτο συμβαίνει ἢ ἄλλο τι;","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τοῦτο ἐνταῦθά γε συμβαίνει.","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ περὶ τὰς ἄλλας ἁπάσας τέχνας ὡσαύτως ἔχει ὁ ῥήτωρ καὶ ἡ ῥητορική: αὐτὰ μὲν τὰ πράγματα οὐδὲν δεῖ αὐτὴν εἰδέναι ὅπως ἔχει, μηχανὴν","st":"459b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δέ τινα πειθοῦς ηὑρηκέναι ὥστε φαίνεσθαι τοῖς οὐκ εἰδόσι μᾶλλον εἰδέναι τῶν εἰδότων.","st":"459c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐκοῦν πολλὴ ῥᾳστώνη, ὦ Σώκρατες, γίγνεται, μὴ μαθόντα τὰς ἄλλας τέχνας ἀλλὰ μίαν ταύτην, μηδὲν ἐλαττοῦσθαι τῶν δημιουργῶν;","st":"459c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ μὲν ἐλαττοῦται ἢ μὴ ἐλαττοῦται ὁ ῥήτωρ τῶν ἄλλων διὰ τὸ οὕτως ἔχειν, αὐτίκα ἐπισκεψόμεθα, ἐάν τι ἡμῖν πρὸς λόγου ᾖ: νῦν δὲ τόδε πρότερον σκεψώμεθα, ἆρα","st":"459c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τυγχάνει περὶ τὸ δίκαιον καὶ τὸ ἄδικον καὶ τὸ αἰσχρὸν καὶ τὸ καλὸν καὶ ἀγαθὸν καὶ κακὸν οὕτως ἔχων ὁ ῥητορικὸς ὡς περὶ τὸ ὑγιεινὸν καὶ περὶ τὰ ἄλλα ὧν αἱ ἄλλαι τέχναι, αὐτὰ μὲν οὐκ εἰδώς, τί ἀγαθὸν ἢ τί κακόν ἐστιν ἢ τί καλὸν ἢ τί αἰσχρὸν ἢ δίκαιον ἢ ἄδικον, πειθὼ δὲ περὶ αὐτῶν μεμηχανημένος ὥστε δοκεῖν εἰδέναι οὐκ εἰδὼς ἐν οὐκ εἰδόσιν","st":"459d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μᾶλλον τοῦ εἰδότος; ἢ ἀνάγκη εἰδέναι, καὶ δεῖ προεπιστάμενον ταῦτα ἀφικέσθαι παρὰ σὲ τὸν μέλλοντα μαθήσεσθαι τὴν ῥητορικήν; εἰ δὲ μή, σὺ ὁ τῆς ῥητορικῆς διδάσκαλος τούτων μὲν οὐδὲν διδάξεις τὸν ἀφικνούμενον — οὐ γὰρ σὸν ἔργον — ποιήσεις δ’ ἐν τοῖς πολλοῖς δοκεῖν εἰδέναι αὐτὸν τὰ τοιαῦτα οὐκ εἰδότα καὶ δοκεῖν ἀγαθὸν εἶναι οὐκ ὄντα; ἢ τὸ παράπαν οὐχ οἷός τε ἔσῃ αὐτὸν διδάξαι τὴν ῥητορικήν, ἐὰν μὴ προειδῇ περὶ τούτων τὴν ἀλήθειαν; ἢ πῶς τὰ τοιαῦτα ἔχει, ὦ Γοργία;","st":"459e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ πρὸς Διός, ὥσπερ ἄρτι εἶπες, ἀποκαλύψας τῆς ῥητορικῆς εἰπὲ τίς ποθ’ ἡ δύναμίς ἐστιν.","st":"460a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλ’ ἐγὼ μὲν οἶμαι, ὦ Σώκρατες, ἐὰν τύχῃ μὴ εἰδώς, καὶ ταῦτα παρ’ ἐμοῦ μαθήσεται.","st":"460a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχε δή: καλῶς γὰρ λέγεις. ἐάνπερ ῥητορικὸν σύ τινα ποιήσῃς, ἀνάγκη αὐτὸν εἰδέναι τὰ δίκαια καὶ τὰ ἄδικα ἤτοι πρότερόν γε ἢ ὕστερον μαθόντα παρὰ σοῦ.","st":"460a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ὁ τὰ τεκτονικὰ μεμαθηκὼς τεκτονικός, ἢ οὔ;","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ὁ τὰ μουσικὰ μουσικός;","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ὁ τὰ ἰατρικὰ ἰατρικός; καὶ τἆλλα οὕτω κατὰ τὸν αὐτὸν λόγον, ὁ μεμαθηκὼς ἕκαστα τοιοῦτός ἐστιν οἷον ἡ ἐπιστήμη ἕκαστον ἀπεργάζεται;","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάνυ γε.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν κατὰ τοῦτον τὸν λόγον καὶ ὁ τὰ δίκαια μεμαθηκὼς δίκαιος;","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πάντως δήπου.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δὲ δίκαιος δίκαιά που πράττει.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"460b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀνάγκη τὸν ῥητορικὸν δίκαιον εἶναι, τὸν δὲ δίκαιον βούλεσθαι δίκαια πράττειν;","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> φαίνεταί γε.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέποτε ἄρα βουλήσεται ὅ γε δίκαιος ἀδικεῖν.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀνάγκη.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν δὲ ῥητορικὸν ἀνάγκη ἐκ τοῦ λόγου δίκαιον εἶναι.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέποτε ἄρα βουλήσεται ὁ ῥητορικὸς ἀδικεῖν.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> οὐ φαίνεταί γε.","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μέμνησαι οὖν λέγων ὀλίγῳ πρότερον ὅτι οὐ δεῖ τοῖς","st":"460c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παιδοτρίβαις ἐγκαλεῖν οὐδ’ ἐκβάλλειν ἐκ τῶν πόλεων, ἐὰν ὁ πύκτης τῇ πυκτικῇ χρῆταί τε καὶ ἀδίκως χρῆται καὶ ἀδικῇ, ὡσαύτως δὲ οὕτως καὶ ἐὰν ὁ ῥήτωρ τῇ ῥητορικῇ ἀδίκως χρῆται, μὴ τῷ διδάξαντι ἐγκαλεῖν μηδ’ ἐξελαύνειν ἐκ τῆς πόλεως, ἀλλὰ τῷ ἀδικοῦντι καὶ οὐκ ὀρθῶς χρωμένῳ τῇ ῥητορικῇ; ἐρρήθη ταῦτα ἢ οὔ;","st":"460d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἐρρήθη.","st":"460d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν","st":"460d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δέ γε ὁ αὐτὸς οὗτος φαίνεται, ὁ ῥητορικός, οὐκ ἄν ποτε ἀδικήσας. ἢ οὔ;","st":"460e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> φαίνεται.","st":"460e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐν τοῖς πρώτοις γε, ὦ Γοργία, λόγοις ἐλέγετο ὅτι ἡ ῥητορικὴ περὶ λόγους εἴη οὐ τοὺς τοῦ ἀρτίου καὶ περιττοῦ, ἀλλὰ τοὺς τοῦ δικαίου καὶ ἀδίκου: ἦ γάρ;","st":"460e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ναί.","st":"460e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ τοίνυν σου τότε ταῦτα λέγοντος ὑπέλαβον ὡς οὐδέποτ’ ἂν εἴη ἡ ῥητορικὴ ἄδικον πρᾶγμα, ὅ γ’ ἀεὶ περὶ δικαιοσύνης τοὺς λόγους ποιεῖται: ἐπειδὴ δὲ ὀλίγον ὕστερον ἔλεγες ὅτι ὁ ῥήτωρ","st":"460e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ ῥητορικῇ κἂν ἀδίκως χρῷτο, οὕτω θαυμάσας καὶ ἡγησάμενος οὐ συνᾴδειν τὰ λεγόμενα ἐκείνους εἶπον τοὺς λόγους, ὅτι εἰ μὲν κέρδος ἡγοῖο εἶναι τὸ ἐλέγχεσθαι ὥσπερ ἐγώ, ἄξιον εἴη διαλέγεσθαι, εἰ δὲ μή, ἐᾶν χαίρειν. ὕστερον δὲ ἡμῶν ἐπισκοπουμένων ὁρᾷς δὴ καὶ αὐτὸς ὅτι αὖ ὁμολογεῖται τὸν ῥητορικὸν ἀδύνατον εἶναι ἀδίκως χρῆσθαι τῇ ῥητορικῇ καὶ ἐθέλειν ἀδικεῖν. ταῦτα οὖν ὅπῃ ποτὲ ἔχει, μὰ τὸν","st":"461a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κύνα, ὦ Γοργία, οὐκ ὀλίγης συνουσίας ἐστὶν ὥστε ἱκανῶς διασκέψασθαι.","st":"461b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ, ὦ Σώκρατες; οὕτω καὶ σὺ περὶ τῆς ῥητορικῆς δοξάζεις ὥσπερ νῦν λέγεις; ἢ οἴει — ὅτι Γοργίας ᾐσχύνθη σοι μὴ προσομολογῆσαι τὸν ῥητορικὸν ἄνδρα μὴ οὐχὶ καὶ τὰ δίκαια εἰδέναι καὶ τὰ καλὰ καὶ τὰ ἀγαθά, καὶ ἐὰν μὴ ἔλθῃ ταῦτα εἰδὼς παρ’ αὐτόν, αὐτὸς διδάξειν, ἔπειτα ἐκ ταύτης ἴσως τῆς ὁμολογίας ἐναντίον τι συνέβη ἐν τοῖς","st":"461b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> λόγοις — τοῦτο ⟨ὃ⟩ δὴ ἀγαπᾷς, αὐτὸς ἀγαγὼν ἐπὶ τοιαῦτα ἐρωτήματα — ἐπεὶ τίνα οἴει ἀπαρνήσεσθαι μὴ οὐχὶ καὶ αὐτὸν ἐπίστασθαι τὰ δίκαια καὶ ἄλλους διδάξειν; — ἀλλ’ εἰς τὰ τοιαῦτα ἄγειν πολλὴ ἀγροικία ἐστὶν τοὺς λόγους.","st":"461c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ κάλλιστε Πῶλε, ἀλλά τοι ἐξεπίτηδες κτώμεθα ἑταίρους καὶ ὑεῖς, ἵνα ἐπειδὰν αὐτοὶ πρεσβύτεροι γενόμενοι σφαλλώμεθα, παρόντες ὑμεῖς οἱ νεώτεροι ἐπανορθῶτε ἡμῶν τὸν βίον καὶ ἐν ἔργοις καὶ ἐν λόγοις. καὶ νῦν εἴ τι ἐγὼ καὶ","st":"461c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Γοργίας ἐν τοῖς λόγοις σφαλλόμεθα, σὺ παρὼν ἐπανόρθου — δίκαιος δ’ εἶ — καὶ ἐγὼ ἐθέλω τῶν ὡμολογημένων εἴ τί σοι δοκεῖ μὴ καλῶς ὡμολογῆσθαι, ἀναθέσθαι ὅτι ἂν σὺ βούλῃ, ἐάν μοι ἓν μόνον φυλάττῃς.","st":"461d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί τοῦτο λέγεις;","st":"461d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν μακρολογίαν, ὦ Πῶλε, ἢν καθέρξῃς, ᾗ τὸ πρῶτον ἐπεχείρησας χρῆσθαι.","st":"461d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ; οὐκ ἐξέσται μοι λέγειν ὁπόσα ἂν βούλωμαι;","st":"461d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεινὰ μεντἂν πάθοις, ὦ βέλτιστε, εἰ Ἀθήναζε ἀφικόμενος, οὗ τῆς Ἑλλάδος πλείστη ἐστὶν ἐξουσία τοῦ λέγειν, ἔπειτα σὺ ἐνταῦθα τούτου μόνος ἀτυχήσαις. ἀλλὰ ἀντίθες τοι: σοῦ μακρὰ λέγοντος καὶ μὴ ἐθέλοντος τὸ ἐρωτώμενον ἀποκρίνεσθαι, οὐ δεινὰ ἂν αὖ ἐγὼ πάθοιμι, εἰ μὴ ἐξέσται","st":"461e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μοι ἀπιέναι καὶ μὴ ἀκούειν σου; ἀλλ’ εἴ τι κήδῃ τοῦ λόγου τοῦ εἰρημένου καὶ ἐπανορθώσασθαι αὐτὸν βούλει, ὥσπερ νυνδὴ ἔλεγον, ἀναθέμενος ὅτι σοι δοκεῖ, ἐν τῷ μέρει ἐρωτῶν τε καὶ ἐρωτώμενος, ὥσπερ ἐγώ τε καὶ Γοργίας, ἔλεγχέ τε καὶ ἐλέγχου. φῂς γὰρ δήπου καὶ σὺ ἐπίστασθαι ἅπερ Γοργίας ἢ οὔ;","st":"462a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"462a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ σὺ κελεύεις σαυτὸν ἐρωτᾶν ἑκάστοτε ὅτι ἄν τις βούληται, ὡς ἐπιστάμενος ἀποκρίνεσθαι;","st":"462a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ μὲν οὖν.","st":"462a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ νῦν δὴ τούτων ὁπότερον βούλει ποίει, ἐρώτα ἢ ἀποκρίνου.","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ ποιήσω ταῦτα. καί μοι ἀπόκριναι, ὦ Σώκρατες: ἐπειδὴ Γοργίας ἀπορεῖν σοι δοκεῖ περὶ τῆς ῥητορικῆς, σὺ αὐτὴν τίνα φῂς εἶναι;","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα ἐρωτᾷς ἥντινα τέχνην φημὶ εἶναι;","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδεμία ἔμοιγε δοκεῖ, ὦ Πῶλε, ὥς γε πρὸς σὲ τἀληθῆ εἰρῆσθαι.","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ τί σοι δοκεῖ ἡ ῥητορικὴ εἶναι;","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρᾶγμα ὃ φῂς σὺ ποιῆσαι τέχνην ἐν τῷ συγγράμματι","st":"462b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὃ ἐγὼ ἔναγχος ἀνέγνων.","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί τοῦτο λέγεις;","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμπειρίαν ἔγωγέ τινα.","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐμπειρία ἄρα σοι δοκεῖ ἡ ῥητορικὴ εἶναι;","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔμοιγε, εἰ μή τι σὺ ἄλλο λέγεις.","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τίνος ἐμπειρία;","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χάριτός τινος καὶ ἡδονῆς ἀπεργασίας.","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκοῦν καλόν σοι δοκεῖ ἡ ῥητορικὴ εἶναι, χαρίζεσθαι οἷόν τε εἶναι ἀνθρώποις;","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ, ὦ Πῶλε; ἤδη πέπυσαι παρ’ ἐμοῦ ὅτι φημὶ","st":"462c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτὴν εἶναι, ὥστε τὸ μετὰ τοῦτο ἐρωτᾷς εἰ οὐ καλή μοι δοκεῖ εἶναι;","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ γὰρ πέπυσμαι ὅτι ἐμπειρίαν τινὰ αὐτὴν φῂς εἶναι;","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει οὖν, ἐπειδὴ τιμᾷς τὸ χαρίζεσθαι, σμικρόν τί μοι χαρίσασθαι;","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐροῦ νῦν με, ὀψοποιία ἥτις μοι δοκεῖ τέχνη εἶναι.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐρωτῶ δή, τίς τέχνη ὀψοποιία;","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδεμία, ὦ Πῶλε.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ τί; φάθι.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φημὶ δή, ἐμπειρία τις.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τίς; φάθι.","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φημὶ δή, χάριτος καὶ ἡδονῆς","st":"462d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀπεργασίας, ὦ Πῶλε.","st":"462e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ταὐτὸν ἄρ’ ἐστὶν ὀψοποιία καὶ ῥητορική;","st":"462e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδαμῶς γε, ἀλλὰ τῆς αὐτῆς μὲν ἐπιτηδεύσεως μόριον.","st":"462e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τίνος λέγεις ταύτης;","st":"462e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὴ ἀγροικότερον ᾖ τὸ ἀληθὲς εἰπεῖν: ὀκνῶ γὰρ Γοργίου ἕνεκα λέγειν, μὴ οἴηταί με διακωμῳδεῖν τὸ ἑαυτοῦ ἐπιτήδευμα. ἐγὼ δέ, εἰ μὲν τοῦτό ἐστιν ἡ ῥητορικὴ ἣν Γοργίας:","st":"462e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπιτηδεύει, οὐκ οἶδα — καὶ γὰρ ἄρτι ἐκ τοῦ λόγου οὐδὲν ἡμῖν καταφανὲς ἐγένετο τί ποτε οὗτος ἡγεῖται — ὃ δ’ ἐγὼ καλῶ τὴν ῥητορικήν, πράγματός τινός ἐστι μόριον οὐδενὸς τῶν καλῶν.","st":"463a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> τίνος, ὦ Σώκρατες; εἰπέ: μηδὲν ἐμὲ αἰσχυνθῇς.","st":"463a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δοκεῖ τοίνυν μοι, ὦ Γοργία, εἶναί τι ἐπιτήδευμα τεχνικὸν μὲν οὔ, ψυχῆς δὲ στοχαστικῆς καὶ ἀνδρείας καὶ φύσει δεινῆς προσομιλεῖν τοῖς ἀνθρώποις: καλῶ δὲ αὐτοῦ","st":"463a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ τὸ κεφάλαιον κολακείαν. ταύτης μοι δοκεῖ τῆς ἐπιτηδεύσεως πολλὰ μὲν καὶ ἄλλα μόρια εἶναι, ἓν δὲ καὶ ἡ ὀψοποιική: ὃ δοκεῖ μὲν εἶναι τέχνη, ὡς δὲ ὁ ἐμὸς λόγος, οὐκ ἔστιν τέχνη ἀλλ’ ἐμπειρία καὶ τριβή. ταύτης μόριον καὶ τὴν ῥητορικὴν ἐγὼ καλῶ καὶ τήν γε κομμωτικὴν καὶ τὴν σοφιστικήν, τέτταρα ταῦτα μόρια ἐπὶ τέτταρσιν πράγμασιν. εἰ οὖν βούλεται Πῶλος πυνθάνεσθαι, πυνθανέσθω: οὐ γάρ","st":"463b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πω πέπυσται ὁποῖόν φημι ἐγὼ τῆς κολακείας μόριον εἶναι τὴν ῥητορικήν, ἀλλ’ αὐτὸν λέληθα οὔπω ἀποκεκριμένος, ὁ δὲ ἐπανερωτᾷ εἰ οὐ καλὸν ἡγοῦμαι εἶναι. ἐγὼ δὲ αὐτῷ οὐκ ἀποκρινοῦμαι πρότερον εἴτε καλὸν εἴτε αἰσχρὸν ἡγοῦμαι εἶναι τὴν ῥητορικὴν πρὶν ἂν πρῶτον ἀποκρίνωμαι ὅτι ἐστίν. οὐ γὰρ δίκαιον, ὦ Πῶλε: ἀλλ’ εἴπερ βούλει πυθέσθαι, ἐρώτα ὁποῖον μόριον τῆς κολακείας φημὶ εἶναι τὴν ῥητορικήν.","st":"463c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐρωτῶ δή, καὶ ἀπόκριναι ὁποῖον μόριον.","st":"463c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν ἂν μάθοις ἀποκριναμένου; ἔστιν γὰρ ἡ ῥητορικὴ κατὰ τὸν ἐμὸν λόγον πολιτικῆς μορίου εἴδωλον.","st":"463d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί οὖν; καλὸν ἢ αἰσχρὸν λέγεις αὐτὴν εἶναι;","st":"463d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αἰσχρὸν ἔγωγε — τὰ γὰρ κακὰ αἰσχρὰ καλῶ — ἐπειδὴ δεῖ σοι ἀποκρίνασθαι ὡς ἤδη εἰδότι ἃ ἐγὼ λέγω.","st":"463d"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> μὰ τὸν Δία, ὦ Σώκρατες, ἀλλ’ ἐγὼ οὐδὲ αὐτὸς συνίημι ὅτι λέγεις.","st":"463d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰκότως γε, ὦ Γοργία: οὐδὲν γάρ πω σαφὲς λέγω, Πῶλος δὲ ὅδε νέος ἐστὶ καὶ ὀξύς.","st":"463e"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλὰ τοῦτον μὲν ἔα, ἐμοὶ δ’ εἰπὲ πῶς λέγεις πολιτικῆς μορίου εἴδωλον εἶναι τὴν ῥητορικήν.","st":"463e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐγὼ πειράσομαι φράσαι ὅ γέ μοι φαίνεται εἶναι ἡ ῥητορική: εἰ δὲ μὴ τυγχάνει ὂν τοῦτο, Πῶλος ὅδε","st":"463e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐλέγξει. σῶμά που καλεῖς τι καὶ ψυχήν;","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> πῶς γὰρ οὔ;","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τούτων οἴει τινὰ εἶναι ἑκατέρου εὐεξίαν;","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔγωγε.","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; δοκοῦσαν μὲν εὐεξίαν, οὖσαν δ’ οὔ; οἷον τοιόνδε λέγω: πολλοὶ δοκοῦσιν εὖ ἔχειν τὰ σώματα, οὓς οὐκ ἂν ῥᾳδίως αἴσθοιτό τις ὅτι οὐκ εὖ ἔχουσιν, ἀλλ’ ἢ ἰατρός τε καὶ τῶν γυμναστικῶν τις.","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀληθῆ λέγεις.","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ τοιοῦτον λέγω καὶ ἐν σώματι εἶναι καὶ ἐν ψυχῇ, ὃ ποιεῖ μὲν δοκεῖν εὖ ἔχειν τὸ σῶμα καὶ τὴν ψυχήν,","st":"464a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχει δὲ οὐδὲν μᾶλλον.","st":"464b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἔστι ταῦτα.","st":"464b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή σοι, ἐὰν δύνωμαι, σαφέστερον ἐπιδείξω ὃ λέγω. δυοῖν ὄντοιν τοῖν πραγμάτοιν δύο λέγω τέχνας: τὴν μὲν ἐπὶ τῇ ψυχῇ πολιτικὴν καλῶ, τὴν δὲ ἐπὶ σώματι μίαν μὲν οὕτως ὀνομάσαι οὐκ ἔχω σοι, μιᾶς δὲ οὔσης τῆς τοῦ σώματος θεραπείας δύο μόρια λέγω, τὴν μὲν γυμναστικήν, τὴν δὲ ἰατρικήν: τῆς δὲ πολιτικῆς ἀντὶ μὲν τῆς γυμναστικῆς τὴν νομοθετικήν, ἀντίστροφον δὲ τῇ ἰατρικῇ τὴν δικαιοσύνην.","st":"464b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπικοινωνοῦσι μὲν δὴ ἀλλήλαις, ἅτε περὶ τὸ αὐτὸ οὖσαι, ἑκάτεραι τούτων, ἥ τε ἰατρικὴ τῇ γυμναστικῇ καὶ ἡ δικαιοσύνη τῇ νομοθετικῇ: ὅμως δὲ διαφέρουσίν τι ἀλλήλων. τεττάρων δὴ τούτων οὐσῶν, καὶ ἀεὶ πρὸς τὸ βέλτιστον θεραπευουσῶν τῶν μὲν τὸ σῶμα, τῶν δὲ τὴν ψυχήν, ἡ κολακευτικὴ αἰσθομένη — οὐ γνοῦσα λέγω ἀλλὰ στοχασαμένη — τέτραχα ἑαυτὴν διανείμασα, ὑποδῦσα ὑπὸ ἕκαστον τῶν μορίων, προσποιεῖται","st":"464c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι τοῦτο ὅπερ ὑπέδυ, καὶ τοῦ μὲν βελτίστου οὐδὲν φροντίζει, τῷ δὲ ἀεὶ ἡδίστῳ θηρεύεται τὴν ἄνοιαν καὶ ἐξαπατᾷ, ὥστε δοκεῖ πλείστου ἀξία εἶναι. ὑπὸ μὲν οὖν τὴν ἰατρικὴν ἡ ὀψοποιικὴ ὑποδέδυκεν, καὶ προσποιεῖται τὰ βέλτιστα σιτία τῷ σώματι εἰδέναι, ὥστ’ εἰ δέοι ἐν παισὶ διαγωνίζεσθαι ὀψοποιόν τε καὶ ἰατρόν, ἢ ἐν ἀνδράσιν οὕτως ἀνοήτοις ὥσπερ οἱ παῖδες, πότερος ἐπαΐει περὶ τῶν χρηστῶν σιτίων καὶ","st":"464d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πονηρῶν, ὁ ἰατρὸς ἢ ὁ ὀψοποιός, λιμῷ ἂν ἀποθανεῖν τὸν ἰατρόν. κολακείαν μὲν οὖν αὐτὸ καλῶ, καὶ αἰσχρόν φημι","st":"464e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι τὸ τοιοῦτον, ὦ Πῶλε — τοῦτο γὰρ πρὸς σὲ λέγω — ὅτι τοῦ ἡδέος στοχάζεται ἄνευ τοῦ βελτίστου: τέχνην δὲ αὐτὴν οὔ φημι εἶναι ἀλλ’ ἐμπειρίαν, ὅτι οὐκ ἔχει λόγον οὐδένα ᾧ προσφέρει ἃ προσφέρει ὁποῖ’ ἄττα τὴν φύσιν ἐστίν, ὥστε τὴν αἰτίαν ἑκάστου μὴ ἔχειν εἰπεῖν. ἐγὼ δὲ τέχνην οὐ καλῶ ὃ ἂν ᾖ ἄλογον πρᾶγμα: τούτων δὲ πέρι εἰ ἀμφισβητεῖς, ἐθέλω ὑποσχεῖν λόγον.","st":"465a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ μὲν οὖν ἰατρικῇ, ὥσπερ λέγω, ἡ ὀψοποιικὴ κολακεία ὑπόκειται: τῇ δὲ γυμναστικῇ κατὰ τὸν αὐτὸν τρόπον τοῦτον ἡ κομμωτική, κακοῦργός τε καὶ ἀπατηλὴ καὶ ἀγεννὴς καὶ ἀνελεύθερος, σχήμασιν καὶ χρώμασιν καὶ λειότητι καὶ ἐσθῆσιν ἀπατῶσα, ὥστε ποιεῖν ἀλλότριον κάλλος ἐφελκομένους τοῦ οἰκείου τοῦ διὰ τῆς γυμναστικῆς ἀμελεῖν. ἵν’ οὖν μὴ μακρολογῶ, ἐθέλω σοι εἰπεῖν ὥσπερ οἱ γεωμέτραι — ἤδη γὰρ","st":"465b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν ἴσως ἀκολουθήσαις — ὅτι ὃ κομμωτικὴ πρὸς γυμναστικήν, τοῦτο σοφιστικὴ πρὸς νομοθετικήν, καὶ ὅτι ὃ ὀψοποιικὴ πρὸς ἰατρικήν, τοῦτο ῥητορικὴ πρὸς δικαιοσύνην. ὅπερ μέντοι λέγω, διέστηκε μὲν οὕτω φύσει, ἅτε δ’ ἐγγὺς ὄντων φύρονται ἐν τῷ αὐτῷ καὶ περὶ ταὐτὰ σοφισταὶ καὶ ῥήτορες, καὶ οὐκ ἔχουσιν ὅτι χρήσονται οὔτε αὐτοὶ ἑαυτοῖς οὔτε οἱ ἄλλοι ἄνθρωποι τούτοις. καὶ γὰρ ἄν, εἰ μὴ ἡ ψυχὴ τῷ σώματι","st":"465c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπεστάτει, ἀλλ’ αὐτὸ αὑτῷ, καὶ μὴ ὑπὸ ταύτης κατεθεωρεῖτο καὶ διεκρίνετο ἥ τε ὀψοποιικὴ καὶ ἡ ἰατρική, ἀλλ’ αὐτὸ τὸ σῶμα ἔκρινε σταθμώμενον ταῖς χάρισι ταῖς πρὸς αὑτό, τὸ τοῦ Ἀναξαγόρου ἂν πολὺ ἦν, ὦ φίλε Πῶλε — σὺ γὰρ τούτων ἔμπειρος — ὁμοῦ ἂν πάντα χρήματα ἐφύρετο ἐν τῷ αὐτῷ, ἀκρίτων ὄντων τῶν τε ἰατρικῶν καὶ ὑγιεινῶν καὶ ὀψοποιικῶν. ὃ μὲν οὖν ἐγώ φημι τὴν ῥητορικὴν εἶναι, ἀκήκοας: ἀντίστροφον","st":"465d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὀψοποιίας ἐν ψυχῇ, ὡς ἐκεῖνο ἐν σώματι. ἴσως μὲν οὖν ἄτοπον πεποίηκα, ὅτι σε οὐκ ἐῶν μακροὺς λόγους λέγειν αὐτὸς συχνὸν λόγον ἀποτέτακα. ἄξιον μὲν οὖν ἐμοὶ συγγνώμην ἔχειν ἐστίν: λέγοντος γάρ μου βραχέα οὐκ ἐμάνθανες, οὐδὲ χρῆσθαι τῇ ἀποκρίσει ἥν σοι ἀπεκρινάμην οὐδὲν οἷός τ’ ἦσθα, ἀλλ’ ἐδέου διηγήσεως. ἐὰν μὲν οὖν καὶ","st":"465e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ σοῦ ἀποκρινομένου μὴ ἔχω ὅτι χρήσωμαι, ἀπότεινε καὶ σὺ λόγον, ἐὰν δὲ ἔχω, ἔα με χρῆσθαι: δίκαιον γάρ. καὶ νῦν ταύτῃ τῇ ἀποκρίσει εἴ τι ἔχεις χρῆσθαι, χρῶ.","st":"466a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί οὖν φῄς; κολακεία δοκεῖ σοι εἶναι ἡ ῥητορική;","st":"466a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κολακείας μὲν οὖν ἔγωγε εἶπον μόριον. ἀλλ’ οὐ μνημονεύεις τηλικοῦτος ὤν, ὦ Πῶλε; τί τάχα δράσεις;","st":"466a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἆρ’ οὖν δοκοῦσί σοι ὡς κόλακες ἐν ταῖς πόλεσι φαῦλοι νομίζεσθαι οἱ ἀγαθοὶ ῥήτορες;","st":"466a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐρώτημα τοῦτ’ ἐρωτᾷς ἢ λόγου τινὸς ἀρχὴν λέγεις;","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐρωτῶ ἔγωγε.","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲ νομίζεσθαι ἔμοιγε δοκοῦσιν.","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς οὐ νομίζεσθαι; οὐ μέγιστον δύνανται ἐν ταῖς πόλεσιν;","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκ, εἰ τὸ δύνασθαί γε λέγεις ἀγαθόν τι εἶναι τῷ δυναμένῳ.","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ μὴν λέγω γε.","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐλάχιστον τοίνυν μοι δοκοῦσι τῶν ἐν τῇ πόλει δύνασθαι οἱ ῥήτορες.","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ; οὐχ, ὥσπερ οἱ τύραννοι, ἀποκτεινύασίν τε","st":"466b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὃν ἂν βούλωνται, καὶ ἀφαιροῦνται χρήματα καὶ ἐκβάλλουσιν ἐκ τῶν πόλεων ὃν ἂν δοκῇ αὐτοῖς;","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νὴ τὸν κύνα, ἀμφιγνοῶ μέντοι, ὦ Πῶλε, ἐφ’ ἑκάστου ὧν λέγεις πότερον αὐτὸς ταῦτα λέγεις καὶ γνώμην σαυτοῦ ἀποφαίνῃ, ἢ ἐμὲ ἐρωτᾷς.","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ ἔγωγε σὲ ἐρωτῶ.","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν, ὦ φίλε: ἔπειτα δύο ἅμα με ἐρωτᾷς;","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς δύο;","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρτι οὕτω πως ἔλεγες: “ἦ οὐχὶ ἀποκτεινύασιν","st":"466c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἱ ῥήτορες οὓς ἂν βούλωνται, ὥσπερ οἱ τύραννοι, καὶ χρήματα ἀφαιροῦνται καὶ ἐξελαύνουσιν ἐκ τῶν πόλεων ὃν ἂν δοκῇ αὐτοῖς;”","st":"466d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"466d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω τοίνυν σοι ὅτι δύο ταῦτ’ ἐστιν τὰ ἐρωτήματα, καὶ ἀποκρινοῦμαί γέ σοι πρὸς ἀμφότερα. φημὶ γάρ, ὦ Πῶλε, ἐγὼ καὶ τοὺς ῥήτορας καὶ τοὺς τυράννους δύνασθαι μὲν ἐν ταῖς πόλεσιν σμικρότατον, ὥσπερ νυνδὴ ἔλεγον: οὐδὲν","st":"466d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γὰρ ποιεῖν ὧν βούλονται ὡς ἔπος εἰπεῖν, ποιεῖν μέντοι ὅτι ἂν αὐτοῖς δόξῃ βέλτιστον εἶναι.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκοῦν τοῦτο ἔστιν τὸ μέγα δύνασθαι;","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔχ, ὥς γέ φησιν Πῶλος.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐγὼ οὔ φημι; φημὶ μὲν οὖν ἔγωγε.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὰ τὸν — οὐ σύ γε, ἐπεὶ τὸ μέγα δύνασθαι ἔφης ἀγαθὸν εἶναι τῷ δυναμένῳ.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φημὶ γὰρ οὖν.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγαθὸν οὖν οἴει εἶναι, ἐάν τις ποιῇ ταῦτα ἃ ἂν δοκῇ αὐτῷ βέλτιστα εἶναι, νοῦν μὴ ἔχων; καὶ τοῦτο καλεῖς σὺ μέγα δύνασθαι;","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔγωγε.","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀποδείξεις τοὺς ῥήτορας νοῦν ἔχοντας καὶ","st":"466e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τέχνην τὴν ῥητορικὴν ἀλλὰ μὴ κολακείαν, ἐμὲ ἐξελέγξας; εἰ δέ με ἐάσεις ἀνέλεγκτον, οἱ ῥήτορες οἱ ποιοῦντες ἐν ταῖς πόλεσιν ἃ δοκεῖ αὐτοῖς καὶ οἱ τύραννοι οὐδὲν ἀγαθὸν τοῦτο κεκτήσονται, ἡ δὲ δύναμίς ἐστιν, ὡς σὺ φῄς, ἀγαθόν, τὸ δὲ ποιεῖν ἄνευ νοῦ ἃ δοκεῖ καὶ σὺ ὁμολογεῖς κακὸν εἶναι: ἢ οὔ;","st":"467a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"467a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς ἂν οὖν οἱ ῥήτορες μέγα δύναιντο ἢ οἱ τύραννοι ἐν ταῖς πόλεσιν, ἐὰν μὴ Σωκράτης ἐξελεγχθῇ ὑπὸ Πώλου ὅτι ποιοῦσιν ἃ βούλονται;","st":"467a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὗτος ἀνήρ —","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔ φημι ποιεῖν αὐτοὺς ἃ βούλονται: ἀλλά μ’ ἔλεγχε.","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἄρτι ὡμολόγεις ποιεῖν ἃ δοκεῖ αὐτοῖς βέλτιστα εἶναι, [τούτου πρόσθεν];","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ γὰρ νῦν ὁμολογῶ.","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ οὖν ποιοῦσιν ἃ βούλονται;","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔ φημι.","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ποιοῦντες ἃ δοκεῖ αὐτοῖς;","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φημί.","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> σχέτλιά γε λέγεις καὶ ὑπερφυῆ, ὦ Σώκρατες.","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὴ κακηγόρει, ὦ λῷστε Πῶλε, ἵνα προσείπω σε","st":"467b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κατὰ σέ: ἀλλ’ εἰ μὲν ἔχεις ἐμὲ ἐρωτᾶν, ἐπίδειξον ὅτι ψεύδομαι, εἰ δὲ μή, αὐτὸς ἀποκρίνου.","st":"467c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ ἐθέλω ἀποκρίνεσθαι, ἵνα καὶ εἰδῶ ὅτι λέγεις.","st":"467c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν σοι δοκοῦσιν οἱ ἄνθρωποι τοῦτο βούλεσθαι ὃ ἂν πράττωσιν ἑκάστοτε, ἢ ἐκεῖνο οὗ ἕνεκα πράττουσιν τοῦθ’ ὃ πράττουσιν; οἷον οἱ τὰ φάρμακα πίνοντες παρὰ τῶν ἰατρῶν πότερόν σοι δοκοῦσιν τοῦτο βούλεσθαι ὅπερ ποιοῦσιν, πίνειν τὸ φάρμακον καὶ ἀλγεῖν, ἢ ἐκεῖνο, τὸ ὑγιαίνειν, οὗ ἕνεκα πίνουσιν;","st":"467c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον ὅτι τὸ","st":"467c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὑγιαίνειν.","st":"467d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ οἱ πλέοντές τε καὶ τὸν ἄλλον χρηματισμὸν χρηματιζόμενοι οὐ τοῦτό ἐστιν ὃ βούλονται, ὃ ποιοῦσιν ἑκάστοτε (τίς γὰρ βούλεται πλεῖν τε καὶ κινδυνεύειν καὶ πράγματ’ ἔχειν;) ἀλλ’ ἐκεῖνο οἶμαι οὗ ἕνεκα πλέουσιν, πλουτεῖν: πλούτου γὰρ ἕνεκα πλέουσιν.","st":"467d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"467d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλο τι οὖν οὕτω καὶ περὶ πάντων; ἐάν τίς τι πράττῃ ἕνεκά του, οὐ τοῦτο βούλεται ὃ πράττει, ἀλλ’ ἐκεῖνο","st":"467d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὗ ἕνεκα πράττει;","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν ἔστιν τι τῶν ὄντων ὃ οὐχὶ ἤτοι ἀγαθόν γ’ ἐστὶν ἢ κακὸν ἢ μεταξὺ τούτων, οὔτε ἀγαθὸν οὔτε κακόν;","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πολλὴ ἀνάγκη, ὦ Σώκρατες.","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν λέγεις εἶναι ἀγαθὸν μὲν σοφίαν τε καὶ ὑγίειαν καὶ πλοῦτον καὶ τἆλλα τὰ τοιαῦτα, κακὰ δὲ τἀναντία τούτων;","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δὲ μήτε ἀγαθὰ μήτε κακὰ ἆρα τοιάδε λέγεις, ἃ ἐνίοτε μὲν μετέχει τοῦ ἀγαθοῦ,","st":"467e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐνίοτε δὲ τοῦ κακοῦ, ἐνίοτε δὲ οὐδετέρου, οἷον καθῆσθαι καὶ βαδίζειν καὶ τρέχειν καὶ πλεῖν, καὶ οἷον αὖ λίθους καὶ ξύλα καὶ τἆλλα τὰ τοιαῦτα; οὐ ταῦτα λέγεις; ἢ ἄλλ’ ἄττα καλεῖς τὰ μήτε ἀγαθὰ μήτε κακά;","st":"468a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὔκ, ἀλλὰ ταῦτα.","st":"468a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν τὰ μεταξὺ ταῦτα ἕνεκα τῶν ἀγαθῶν πράττουσιν ὅταν πράττωσιν, ἢ τἀγαθὰ τῶν μεταξύ;","st":"468a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τὰ","st":"468a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> μεταξὺ δήπου τῶν ἀγαθῶν.","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ ἀγαθὸν ἄρα διώκοντες καὶ βαδίζομεν ὅταν βαδίζωμεν, οἰόμενοι βέλτιον εἶναι, καὶ τὸ ἐναντίον ἕσταμεν ὅταν ἑστῶμεν, τοῦ αὐτοῦ ἕνεκα, τοῦ ἀγαθοῦ: ἢ οὔ;","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἀποκτείνυμεν, εἴ τιν’ ἀποκτείνυμεν, καὶ ἐκβάλλομεν καὶ ἀφαιρούμεθα χρήματα, οἰόμενοι ἄμεινον εἶναι ἡμῖν ταῦτα ποιεῖν ἢ μή;","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕνεκ’ ἄρα τοῦ ἀγαθοῦ ἅπαντα ταῦτα ποιοῦσιν οἱ ποιοῦντες.","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φημί.","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὡμολογήσαμεν, ἃ ἕνεκά του ποιοῦμεν, μὴ ἐκεῖνα βούλεσθαι,","st":"468b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐκεῖνο οὗ ἕνεκα ταῦτα ποιοῦμεν;","st":"468c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> μάλιστα.","st":"468c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα σφάττειν βουλόμεθα οὐδ’ ἐκβάλλειν ἐκ τῶν πόλεων οὐδὲ χρήματα ἀφαιρεῖσθαι ἁπλῶς οὕτως, ἀλλ’ ἐὰν μὲν ὠφέλιμα ᾖ ταῦτα, βουλόμεθα πράττειν αὐτά, βλαβερὰ δὲ ὄντα οὐ βουλόμεθα. τὰ γὰρ ἀγαθὰ βουλόμεθα, ὡς φῂς σύ, τὰ δὲ μήτε ἀγαθὰ μήτε κακὰ οὐ βουλόμεθα, οὐδὲ τὰ κακά. ἦ γάρ; ἀληθῆ σοι δοκῶ λέγειν, ὦ Πῶλε, ἢ οὔ; τί οὐκ ἀποκρίνῃ;","st":"468c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀληθῆ.","st":"468c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ ταῦτα ὁμολογοῦμεν, εἴ τις ἀποκτείνει τινὰ ἢ ἐκβάλλει ἐκ πόλεως ἢ ἀφαιρεῖται χρήματα, εἴτε τύραννος ὢν εἴτε ῥήτωρ, οἰόμενος ἄμεινον εἶναι αὐτῷ, τυγχάνει δὲ ὂν κάκιον, οὗτος δήπου ποιεῖ ἃ δοκεῖ αὐτῷ: ἦ γάρ;","st":"468d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"468d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν καὶ ἃ βούλεται, εἴπερ τυγχάνει ταῦτα κακὰ ὄντα; τί οὐκ ἀποκρίνῃ;","st":"468d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ οὔ μοι δοκεῖ ποιεῖν ἃ βούλεται.","st":"468d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστιν οὖν ὅπως ὁ τοιοῦτος","st":"468d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μέγα δύναται ἐν τῇ πόλει ταύτῃ, εἴπερ ἐστὶ τὸ μέγα δύνασθαι ἀγαθόν τι κατὰ τὴν σὴν ὁμολογίαν;","st":"468e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔστιν.","st":"468e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθῆ ἄρα ἐγὼ ἔλεγον, λέγων ὅτι ἔστιν ἄνθρωπον ποιοῦντα ἐν πόλει ἃ δοκεῖ αὐτῷ μὴ μέγα δύνασθαι μηδὲ ποιεῖν ἃ βούλεται.","st":"468e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὡς δὴ σύ, ὦ Σώκρατες, οὐκ ἂν δέξαιο ἐξεῖναί σοι ποιεῖν ὅτι δοκεῖ σοι ἐν τῇ πόλει μᾶλλον ἢ μή, οὐδὲ ζηλοῖς ὅταν ἴδῃς τινὰ ἢ ἀποκτείναντα ὃν ἔδοξεν αὐτῷ ἢ ἀφελόμενον χρήματα ἢ δήσαντα.","st":"468e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δικαίως λέγεις ἢ ἀδίκως;","st":"468e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὁπότερ’ ἂν ποιῇ, οὐκ ἀμφοτέρως ζηλωτόν ἐστιν;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐφήμει, ὦ Πῶλε.","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δή;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι οὐ χρὴ οὔτε τοὺς ἀζηλώτους ζηλοῦν οὔτε τοὺς ἀθλίους, ἀλλ’ ἐλεεῖν.","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ; οὕτω σοι δοκεῖ ἔχειν περὶ ὧν ἐγὼ λέγω τῶν ἀνθρώπων;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς γὰρ οὔ;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὅστις οὖν ἀποκτείνυσιν ὃν ἂν δόξῃ αὐτῷ, δικαίως ἀποκτεινύς, ἄθλιος δοκεῖ σοι εἶναι καὶ ἐλεινός;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἔμοιγε, οὐδὲ μέντοι ζηλωτός.","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἄρτι ἄθλιον ἔφησθα εἶναι;","st":"469a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν ἀδίκως γε, ὦ ἑταῖρε, ἀποκτείναντα, καὶ ἐλεινόν γε πρός: τὸν δὲ δικαίως ἀζήλωτον.","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἦ που ὅ γε ἀποθνῄσκων ἀδίκως ἐλεινός τε καὶ ἄθλιός ἐστιν.","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἧττον ἢ ὁ ἀποκτεινύς, ὦ Πῶλε, καὶ ἧττον ἢ ὁ δικαίως ἀποθνῄσκων.","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς δῆτα, ὦ Σώκρατες;","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὕτως, ὡς μέγιστον τῶν κακῶν τυγχάνει ὂν τὸ ἀδικεῖν.","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἦ γὰρ τοῦτο μέγιστον; οὐ τὸ ἀδικεῖσθαι μεῖζον;","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἥκιστά γε.","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> σὺ ἄρα βούλοιο ἂν ἀδικεῖσθαι μᾶλλον ἢ ἀδικεῖν;","st":"469b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βουλοίμην μὲν ἂν ἔγωγε οὐδέτερα: εἰ δ’ ἀναγκαῖον εἴη ἀδικεῖν ἢ ἀδικεῖσθαι, ἑλοίμην ἂν μᾶλλον ἀδικεῖσθαι ἢ ἀδικεῖν.","st":"469c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> σὺ ἄρα τυραννεῖν οὐκ ἂν δέξαιο;","st":"469c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκ, εἰ τὸ τυραννεῖν γε λέγεις ὅπερ ἐγώ.","st":"469c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ ἔγωγε τοῦτο λέγω ὅπερ ἄρτι, ἐξεῖναι ἐν τῇ πόλει, ὃ ἂν δοκῇ αὐτῷ, ποιεῖν τοῦτο, καὶ ἀποκτεινύντι καὶ ἐκβάλλοντι καὶ πάντα πράττοντι κατὰ τὴν αὐτοῦ δόξαν.","st":"469c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ μακάριε, ἐμοῦ δὴ λέγοντος τῷ λόγῳ ἐπιλαβοῦ.","st":"469c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ γὰρ ἐγὼ ἐν ἀγορᾷ πληθούσῃ λαβὼν ὑπὸ μάλης ἐγχειρίδιον λέγοιμι πρὸς σὲ ὅτι “ὦ Πῶλε, ἐμοὶ δύναμίς τις καὶ τυραννὶς θαυμασία ἄρτι προσγέγονεν: ἐὰν γὰρ ἄρα ἐμοὶ δόξῃ τινὰ τουτωνὶ τῶν ἀνθρώπων ὧν σὺ ὁρᾷς αὐτίκα μάλα δεῖν τεθνάναι, τεθνήξει οὗτος ὃν ἂν δόξῃ: κἄν τινα δόξῃ μοι τῆς κεφαλῆς αὐτῶν καταγῆναι δεῖν, κατεαγὼς ἔσται αὐτίκα μάλα, κἂν θοἰμάτιον διεσχίσθαι, διεσχισμένον ἔσται — οὕτω","st":"469d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μέγα ἐγὼ δύναμαι ἐν τῇδε τῇ πόλει,” εἰ οὖν ἀπιστοῦντί σοι δείξαιμι τὸ ἐγχειρίδιον, ἴσως ἂν εἴποις ἰδὼν ὅτι “ὦ Σώκρατες, οὕτω μὲν πάντες ἂν μέγα δύναιντο, ἐπεὶ κἂν ἐμπρησθείη οἰκία τούτῳ τῷ τρόπῳ ἥντινά σοι δοκοῖ, καὶ τά γε Ἀθηναίων νεώρια καὶ αἱ τριήρεις καὶ τὰ πλοῖα πάντα καὶ τὰ δημόσια καὶ τὰ ἴδια:” ἀλλ’ οὐκ ἄρα τοῦτ’ ἔστιν τὸ μέγα δύνασθαι, τὸ ποιεῖν ἃ δοκεῖ αὐτῷ: ἢ δοκεῖ σοι;","st":"469e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ δῆτα οὕτω γε.","st":"469e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχεις οὖν εἰπεῖν δι’ ὅτι μέμφῃ τὴν τοιαύτην δύναμιν;","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δή; λέγε.","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὅτι ἀναγκαῖον τὸν οὕτω πράττοντα ζημιοῦσθαί ἐστιν.","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὲ ζημιοῦσθαι οὐ κακόν;","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν, ὦ θαυμάσιε, [τὸ μέγα δύνασθαι] πάλιν αὖ σοι φαίνεται, ἐὰν μὲν πράττοντι ἃ δοκεῖ ἕπηται τὸ ὠφελίμως πράττειν, ἀγαθόν τε εἶναι, καὶ τοῦτο, ὡς ἔοικεν, ἐστὶν τὸ μέγα δύνασθαι: εἰ δὲ μή, κακὸν καὶ σμικρὸν δύνασθαι.","st":"470a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκεψώμεθα δὲ καὶ τόδε: ἄλλο τι ὁμολογοῦμεν ἐνίοτε μὲν ἄμεινον εἶναι ταῦτα ποιεῖν ἃ νυνδὴ ἐλέγομεν, ἀποκτεινύναι τε καὶ ἐξελαύνειν ἀνθρώπους καὶ ἀφαιρεῖσθαι χρήματα, ἐνίοτε δὲ οὔ;","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο μὲν δή, ὡς ἔοικε, καὶ παρὰ σοῦ καὶ παρ’ ἐμοῦ ὁμολογεῖται.","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότε οὖν σὺ φῂς ἄμεινον εἶναι ταῦτα ποιεῖν; εἰπὲ τίνα ὅρον ὁρίζῃ.","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> σὺ μὲν οὖν, ὦ Σώκρατες, ἀπόκριναι [ταὐτὸ] τοῦτο.","st":"470b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ μὲν τοίνυν φημί, ὦ Πῶλε, εἴ σοι παρ’ ἐμοῦ ἥδιόν ἐστιν ἀκούειν, ὅταν μὲν δικαίως τις ταῦτα ποιῇ, ἄμεινον εἶναι, ὅταν δὲ ἀδίκως, κάκιον.","st":"470c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> χαλεπόν γέ σε ἐλέγξαι, ὦ Σώκρατες: ἀλλ’ οὐχὶ κἂν παῖς σε ἐλέγξειεν ὅτι οὐκ ἀληθῆ λέγεις;","st":"470c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πολλὴν ἄρα ἐγὼ τῷ παιδὶ χάριν ἕξω, ἴσην δὲ καὶ σοί, ἐάν με ἐλέγξῃς καὶ ἀπαλλάξῃς φλυαρίας. ἀλλὰ μὴ κάμῃς φίλον ἄνδρα εὐεργετῶν, ἀλλ’ ἔλεγχε.","st":"470c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ μήν, ὦ Σώκρατες, οὐδέν γέ σε δεῖ παλαιοῖς","st":"470c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πράγμασιν ἐλέγχειν: τὰ γὰρ ἐχθὲς καὶ πρώην γεγονότα ταῦτα ἱκανά σε ἐξελέγξαι ἐστὶν καὶ ἀποδεῖξαι ὡς πολλοὶ ἀδικοῦντες ἄνθρωποι εὐδαίμονές εἰσιν.","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ ποῖα ταῦτα;","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> Ἀρχέλαον δήπου τοῦτον τὸν Περδίκκου ὁρᾷς ἄρχοντα Μακεδονίας;","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δὲ μή, ἀλλ’ ἀκούω γε.","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> εὐδαίμων οὖν σοι δοκεῖ εἶναι ἢ ἄθλιος;","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ οἶδα, ὦ Πῶλε: οὐ γάρ πω συγγέγονα τῷ ἀνδρί.","st":"470d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ; συγγενόμενος ἂν γνοίης, ἄλλως δὲ αὐτόθεν οὐ γιγνώσκεις ὅτι εὐδαιμονεῖ;","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὰ Δί’ οὐ δῆτα.","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον δή, ὦ Σώκρατες, ὅτι οὐδὲ τὸν μέγαν βασιλέα γιγνώσκειν φήσεις εὐδαίμονα ὄντα.","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἀληθῆ γε ἐρῶ: οὐ γὰρ οἶδα παιδείας ὅπως ἔχει καὶ δικαιοσύνης.","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί δέ; ἐν τούτῳ ἡ πᾶσα εὐδαιμονία ἐστίν;","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὥς γε ἐγὼ λέγω, ὦ Πῶλε: τὸν μὲν γὰρ καλὸν καὶ ἀγαθὸν ἄνδρα καὶ γυναῖκα εὐδαίμονα εἶναί φημι, τὸν δὲ ἄδικον καὶ πονηρὸν ἄθλιον.","st":"470e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἄθλιος ἄρα οὗτός ἐστιν ὁ Ἀρχέλαος κατὰ τὸν σὸν λόγον;","st":"471a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἴπερ γε, ὦ φίλε, ἄδικος.","st":"471a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλὰ μὲν δὴ πῶς οὐκ ἄδικος; ᾧ γε προσῆκε μὲν τῆς ἀρχῆς οὐδὲν ἣν νῦν ἔχει, ὄντι ἐκ γυναικὸς ἣ ἦν δούλη Ἀλκέτου τοῦ Περδίκκου ἀδελφοῦ, καὶ κατὰ μὲν τὸ δίκαιον δοῦλος ἦν Ἀλκέτου, καὶ εἰ ἐβούλετο τὰ δίκαια ποιεῖν, ἐδούλευεν ἂν Ἀλκέτῃ καὶ ἦν εὐδαίμων κατὰ τὸν σὸν λόγον. νῦν δὲ θαυμασίως ὡς ἄθλιος γέγονεν, ἐπεὶ τὰ μέγιστα ἠδίκηκεν:","st":"471a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὅς γε πρῶτον μὲν τοῦτον αὐτὸν τὸν δεσπότην καὶ θεῖον μεταπεμψάμενος ὡς ἀποδώσων τὴν ἀρχὴν ἣν Περδίκκας αὐτὸν ἀφείλετο, ξενίσας καὶ καταμεθύσας αὐτόν τε καὶ τὸν ὑὸν αὐτοῦ Ἀλέξανδρον, ἀνεψιὸν αὑτοῦ, σχεδὸν ἡλικιώτην, ἐμβαλὼν εἰς ἅμαξαν, νύκτωρ ἐξαγαγὼν ἀπέσφαξέν τε καὶ ἠφάνισεν ἀμφοτέρους. καὶ ταῦτα ἀδικήσας ἔλαθεν ἑαυτὸν ἀθλιώτατος γενόμενος καὶ οὐ μετεμέλησεν αὐτῷ, ἀλλ’ ὀλίγον","st":"471b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὕστερον τὸν ἀδελφόν, τὸν γνήσιον τοῦ Περδίκκου ὑόν, παῖδα ὡς ἑπτέτη, οὗ ἡ ἀρχὴ ἐγίγνετο κατὰ τὸ δίκαιον, οὐκ ἐβουλήθη εὐδαίμων γενέσθαι δικαίως ἐκθρέψας καὶ ἀποδοὺς τὴν ἀρχὴν ἐκείνῳ, ἀλλ’ εἰς φρέαρ ἐμβαλὼν καὶ ἀποπνίξας πρὸς τὴν μητέρα αὐτοῦ Κλεοπάτραν χῆνα ἔφη διώκοντα ἐμπεσεῖν καὶ ἀποθανεῖν. τοιγάρτοι νῦν, ἅτε μέγιστα ἠδικηκὼς τῶν ἐν Μακεδονίᾳ, ἀθλιώτατός ἐστιν πάντων Μακεδόνων, ἀλλ’ οὐκ εὐδαιμονέστατος, καὶ ἴσως ἔστιν ὅστις Ἀθηναίων ἀπὸ σοῦ","st":"471c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀρξάμενος δέξαιτ’ ἂν ἄλλος ὁστισοῦν Μακεδόνων γενέσθαι μᾶλλον ἢ Ἀρχέλαος.","st":"471d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ κατ’ ἀρχὰς τῶν λόγων, ὦ Πῶλε, ἔγωγέ σε ἐπῄνεσα ὅτι μοι δοκεῖς εὖ πρὸς τὴν ῥητορικὴν πεπαιδεῦσθαι, τοῦ δὲ διαλέγεσθαι ἠμεληκέναι: καὶ νῦν ἄλλο τι οὗτός ἐστιν ὁ λόγος, ᾧ με καὶ ἂν παῖς ἐξελέγξειε, καὶ ἐγὼ ὑπὸ σοῦ νῦν, ὡς σὺ οἴει, ἐξελήλεγμαι τούτῳ τῷ λόγῳ, φάσκων τὸν ἀδικοῦντα οὐκ εὐδαίμονα εἶναι; πόθεν, ὠγαθέ; καὶ μὴν οὐδέν γέ σοι τούτων ὁμολογῶ ὧν σὺ φῄς.","st":"471d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ γὰρ ἐθέλεις, ἐπεὶ δοκεῖ γέ σοι ὡς ἐγὼ λέγω.","st":"471e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ μακάριε, ῥητορικῶς γάρ με ἐπιχειρεῖς ἐλέγχειν, ὥσπερ οἱ ἐν τοῖς δικαστηρίοις ἡγούμενοι ἐλέγχειν. καὶ γὰρ ἐκεῖ οἱ ἕτεροι τοὺς ἑτέρους δοκοῦσιν ἐλέγχειν, ἐπειδὰν τῶν λόγων ὧν ἂν λέγωσι μάρτυρας πολλοὺς παρέχωνται καὶ εὐδοκίμους, ὁ δὲ τἀναντία λέγων ἕνα τινὰ παρέχηται ἢ μηδένα. οὗτος δὲ ὁ ἔλεγχος οὐδενὸς ἄξιός ἐστιν πρὸς τὴν","st":"471e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλήθειαν: ἐνίοτε γὰρ ἂν καὶ καταψευδομαρτυρηθείη τις ὑπὸ πολλῶν καὶ δοκούντων εἶναί τι. καὶ νῦν περὶ ὧν σὺ λέγεις ὀλίγου σοι πάντες συμφήσουσιν ταὐτὰ Ἀθηναῖοι καὶ οἱ ξένοι, ἐὰν βούλῃ κατ’ ἐμοῦ μάρτυρας παρασχέσθαι ὡς οὐκ ἀληθῆ λέγω: μαρτυρήσουσί σοι, ἐὰν μὲν βούλῃ, Νικίας ὁ Νικηράτου καὶ οἱ ἀδελφοὶ μετ’ αὐτοῦ, ὧν οἱ τρίποδες οἱ ἐφεξῆς ἑστῶτές εἰσιν ἐν τῷ Διονυσίῳ, ἐὰν δὲ βούλῃ, Ἀριστοκράτης","st":"472a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ Σκελλίου, οὗ αὖ ἐστιν ἐν Πυθίου τοῦτο τὸ καλὸν ἀνάθημα, ἐὰν δὲ βούλῃ, ἡ Περικλέους ὅλη οἰκία ἢ ἄλλη συγγένεια ἥντινα ἂν βούλῃ τῶν ἐνθάδε ἐκλέξασθαι. ἀλλ’ ἐγώ σοι εἷς ὢν οὐχ ὁμολογῶ: οὐ γάρ με σὺ ἀναγκάζεις, ἀλλὰ ψευδομάρτυρας πολλοὺς κατ’ ἐμοῦ παρασχόμενος ἐπιχειρεῖς ἐκβάλλειν με ἐκ τῆς οὐσίας καὶ τοῦ ἀληθοῦς. ἐγὼ δὲ ἂν μὴ σὲ αὐτὸν ἕνα ὄντα μάρτυρα παράσχωμαι ὁμολογοῦντα περὶ ὧν λέγω, οὐδὲν οἶμαι ἄξιον λόγου μοι πεπεράνθαι περὶ ὧν ἂν","st":"472b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμῖν ὁ λόγος ᾖ: οἶμαι δὲ οὐδὲ σοί, ἐὰν μὴ ἐγώ σοι μαρτυρῶ εἷς ὢν μόνος, τοὺς δ’ ἄλλους πάντας τούτους χαίρειν ἐᾷς. ἔστιν μὲν οὖν οὗτός τις τρόπος ἐλέγχου, ὡς σύ τε οἴει καὶ ἄλλοι πολλοί: ἔστιν δὲ καὶ ἄλλος, ὃν ἐγὼ αὖ οἶμαι. παραβαλόντες οὖν παρ’ ἀλλήλους σκεψώμεθα εἴ τι διοίσουσιν ἀλλήλων. καὶ γὰρ καὶ τυγχάνει περὶ ὧν ἀμφισβητοῦμεν οὐ πάνυ σμικρὰ ὄντα, ἀλλὰ σχεδόν τι ταῦτα περὶ ὧν εἰδέναι τε κάλλιστον μὴ εἰδέναι τε αἴσχιστον: τὸ γὰρ κεφάλαιον αὐτῶν ἐστιν ἢ γιγνώσκειν ἢ ἀγνοεῖν ὅστις τε εὐδαίμων ἐστὶν καὶ","st":"472c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅστις μή. αὐτίκα πρῶτον, περὶ οὗ νῦν ὁ λόγος ἐστίν, σὺ ἡγῇ οἷόν τε εἶναι μακάριον ἄνδρα ἀδικοῦντά τε καὶ ἄδικον ὄντα, εἴπερ Ἀρχέλαον ἄδικον μὲν ἡγῇ εἶναι, εὐδαίμονα δέ. ἄλλο τι ὡς οὕτω σου νομίζοντος διανοώμεθα;","st":"472d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"472d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ δέ φημι ἀδύνατον. ἓν μὲν τουτὶ ἀμφισβητοῦμεν. εἶεν: ἀδικῶν δὲ δὴ εὐδαίμων ἔσται ἆρ’, ἂν τυγχάνῃ δίκης τε καὶ τιμωρίας;","st":"472d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἥκιστά γε, ἐπεὶ οὕτω γ’ ἂν ἀθλιώτατος εἴη.","st":"472d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐὰν ἄρα μὴ τυγχάνῃ δίκης ὁ ἀδικῶν, κατὰ τὸν σὸν λόγον εὐδαίμων ἔσται;","st":"472e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φημί.","st":"472e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κατὰ δέ γε τὴν ἐμὴν δόξαν, ὦ Πῶλε, ὁ ἀδικῶν τε καὶ ὁ ἄδικος πάντως μὲν ἄθλιος, ἀθλιώτερος μέντοι ἐὰν μὴ διδῷ δίκην μηδὲ τυγχάνῃ τιμωρίας ἀδικῶν, ἧττον δὲ ἄθλιος ἐὰν διδῷ δίκην καὶ τυγχάνῃ δίκης ὑπὸ θεῶν τε καὶ ἀνθρώπων.","st":"472e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἄτοπά γε, ὦ Σώκρατες, ἐπιχειρεῖς λέγειν.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πειράσομαι δέ γε καὶ σὲ ποιῆσαι, ὦ ἑταῖρε, ταὐτὰ ἐμοὶ λέγειν: φίλον γάρ σε ἡγοῦμαι. νῦν μὲν οὖν ἃ διαφερόμεθα ταῦτ’ ἐστιν: σκόπει δὲ καὶ σύ. εἶπον ἐγώ που ἐν τοῖς ἔμπροσθεν τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι κάκιον εἶναι.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σὺ δὲ τὸ ἀδικεῖσθαι.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τοὺς ἀδικοῦντας ἀθλίους ἔφην εἶναι ἐγώ, καὶ ἐξηλέγχθην ὑπὸ σοῦ.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναὶ μὰ Δία.","st":"473a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς σύ γε οἴει, ὦ Πῶλε.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀληθῆ γε οἰόμενος.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴσως. σὺ δέ γε εὐδαίμονας αὖ τοὺς ἀδικοῦντας, ἐὰν μὴ διδῶσι δίκην.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ μὲν οὖν.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ δέ γε αὐτοὺς ἀθλιωτάτους φημί, τοὺς δὲ διδόντας δίκην ἧττον. βούλει καὶ τοῦτο ἐλέγχειν;","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ ἔτι τοῦτ’ ἐκείνου χαλεπώτερόν ἐστιν, ὦ Σώκρατες, ἐξελέγξαι.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ δῆτα, ὦ Πῶλε, ἀλλ’ ἀδύνατον: τὸ γὰρ ἀληθὲς οὐδέποτε ἐλέγχεται.","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς λέγεις; ἐὰν ἀδικῶν ἄνθρωπος ληφθῇ τυραννίδι","st":"473b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐπιβουλεύων, καὶ ληφθεὶς στρεβλῶται καὶ ἐκτέμνηται καὶ τοὺς ὀφθαλμοὺς ἐκκάηται, καὶ ἄλλας πολλὰς καὶ μεγάλας καὶ παντοδαπὰς λώβας αὐτός τε λωβηθεὶς καὶ τοὺς αὑτοῦ ἐπιδὼν παῖδάς τε καὶ γυναῖκα τὸ ἔσχατον ἀνασταυρωθῇ ἢ καταπιττωθῇ, οὗτος εὐδαιμονέστερος ἔσται ἢ ἐὰν διαφυγὼν τύραννος καταστῇ καὶ ἄρχων ἐν τῇ πόλει διαβιῷ ποιῶν ὅτι ἂν βούληται, ζηλωτὸς ὢν καὶ εὐδαιμονιζόμενος ὑπὸ τῶν","st":"473c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πολιτῶν καὶ τῶν ἄλλων ξένων; ταῦτα λέγεις ἀδύνατον εἶναι ἐξελέγχειν;","st":"473d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μορμολύττῃ αὖ, ὦ γενναῖε Πῶλε, καὶ οὐκ ἐλέγχεις: ἄρτι δὲ ἐμαρτύρου. ὅμως δὲ ὑπόμνησόν με σμικρόν. ἐὰν ἀδίκως ἐπιβουλεύων τυραννίδι, εἶπες;","st":"473d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"473d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐδαιμονέστερος μὲν τοίνυν οὐδέποτε ἔσται οὐδέτερος αὐτῶν, οὔτε ὁ κατειργασμένος τὴν τυραννίδα ἀδίκως οὔτε ὁ διδοὺς δίκην — δυοῖν γὰρ ἀθλίοιν εὐδαιμονέστερος μὲν","st":"473d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἂν εἴη — ἀθλιώτερος μέντοι ὁ διαφεύγων καὶ τυραννεύσας. τί τοῦτο, ὦ Πῶλε; γελᾷς; ἄλλο αὖ τοῦτο εἶδος ἐλέγχου ἐστίν, ἐπειδάν τίς τι εἴπῃ, καταγελᾶν, ἐλέγχειν δὲ μή;","st":"473e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ οἴει ἐξεληλέγχθαι, ὦ Σώκρατες, ὅταν τοιαῦτα λέγῃς ἃ οὐδεὶς ἂν φήσειεν ἀνθρώπων; ἐπεὶ ἐροῦ τινα τουτωνί.","st":"473e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ Πῶλε, οὐκ εἰμὶ τῶν πολιτικῶν, καὶ πέρυσι βουλεύειν λαχών, ἐπειδὴ ἡ φυλὴ ἐπρυτάνευε καὶ ἔδει με ἐπιψηφίζειν,","st":"473e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γέλωτα παρεῖχον καὶ οὐκ ἠπιστάμην ἐπιψηφίζειν. μὴ οὖν μηδὲ νῦν με κέλευε ἐπιψηφίζειν τοὺς παρόντας, ἀλλ’ εἰ μὴ ἔχεις τούτων βελτίω ἔλεγχον, ὅπερ νυνδὴ ἐγὼ ἔλεγον, ἐμοὶ ἐν τῷ μέρει παράδος, καὶ πείρασαι τοῦ ἐλέγχου οἷον ἐγὼ οἶμαι δεῖν εἶναι. ἐγὼ γὰρ ὧν ἂν λέγω ἕνα μὲν παρασχέσθαι μάρτυρα ἐπίσταμαι, αὐτὸν πρὸς ὃν ἄν μοι ὁ λόγος ᾖ, τοὺς δὲ πολλοὺς ἐῶ χαίρειν, καὶ ἕνα ἐπιψηφίζειν ἐπίσταμαι, τοῖς δὲ","st":"474a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πολλοῖς οὐδὲ διαλέγομαι. ὅρα οὖν εἰ ἐθελήσεις ἐν τῷ μέρει διδόναι ἔλεγχον ἀποκρινόμενος τὰ ἐρωτώμενα. ἐγὼ γὰρ δὴ οἶμαι καὶ ἐμὲ καὶ σὲ καὶ τοὺς ἄλλους ἀνθρώπους τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι κάκιον ἡγεῖσθαι καὶ τὸ μὴ διδόναι δίκην τοῦ διδόναι.","st":"474b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἐγὼ δέ γε οὔτ’ ἐμὲ οὔτ’ ἄλλον ἀνθρώπων οὐδένα. ἐπεὶ σὺ δέξαι’ ἂν μᾶλλον ἀδικεῖσθαι ἢ ἀδικεῖν;","st":"474b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ σύ γ’ ἂν καὶ οἱ ἄλλοι πάντες.","st":"474b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πολλοῦ γε δεῖ, ἀλλ’ οὔτ’ ἐγὼ οὔτε σὺ οὔτ’ ἄλλος οὐδείς.","st":"474b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκουν ἀποκρινῇ;","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ μὲν οὖν: καὶ γὰρ ἐπιθυμῶ εἰδέναι ὅτι ποτ’ ἐρεῖς.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγε δή μοι, ἵν’ εἰδῇς, ὥσπερ ἂν εἰ ἐξ ἀρχῆς σε ἠρώτων: πότερον δοκεῖ σοι, ὦ Πῶλε, κάκιον εἶναι, τὸ ἀδικεῖν ἢ τὸ ἀδικεῖσθαι;","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τὸ ἀδικεῖσθαι ἔμοιγε.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ δή; αἴσχιον πότερον τὸ ἀδικεῖν ἢ τὸ ἀδικεῖσθαι; ἀποκρίνου.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τὸ ἀδικεῖν.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ κάκιον, εἴπερ αἴσχιον.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἥκιστά γε.","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνω: οὐ","st":"474c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταὐτὸν ἡγῇ σύ, ὡς ἔοικας, καλόν τε καὶ ἀγαθὸν καὶ κακὸν καὶ αἰσχρόν.","st":"474d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ δῆτα.","st":"474d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ τόδε; τὰ καλὰ πάντα, οἷον καὶ σώματα καὶ χρώματα καὶ σχήματα καὶ φωνὰς καὶ ἐπιτηδεύματα, εἰς οὐδὲν ἀποβλέπων καλεῖς ἑκάστοτε καλά; οἷον πρῶτον τὰ σώματα τὰ καλὰ οὐχὶ ἤτοι κατὰ τὴν χρείαν λέγεις καλὰ εἶναι, πρὸς ὃ ἂν ἕκαστον χρήσιμον ᾖ, πρὸς τοῦτο, ἢ κατὰ ἡδονήν τινα, ἐὰν ἐν τῷ θεωρεῖσθαι χαίρειν ποιῇ τοὺς θεωροῦντας; ἔχεις τι ἐκτὸς τούτων λέγειν περὶ σώματος κάλλους;","st":"474d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔχω.","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τἆλλα πάντα οὕτω καὶ σχήματα καὶ χρώματα ἢ διὰ ἡδονήν τινα ἢ διὰ ὠφελίαν ἢ δι’ ἀμφότερα καλὰ προσαγορεύεις;","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ καὶ τὰς φωνὰς καὶ τὰ κατὰ τὴν μουσικὴν πάντα ὡσαύτως;","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν τά γε κατὰ τοὺς νόμους καὶ τὰ ἐπιτηδεύματα οὐ δήπου ἐκτὸς τούτων ἐστίν, τὰ καλά, τοῦ ἢ ὠφέλιμα εἶναι ἢ ἡδέα ἢ ἀμφότερα.","st":"474e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔμοιγε δοκεῖ.","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τὸ τῶν μαθημάτων κάλλος ὡσαύτως;","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε: καὶ καλῶς γε νῦν ὁρίζῃ, ὦ Σώκρατες, ἡδονῇ τε καὶ ἀγαθῷ ὁριζόμενος τὸ καλόν.","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ αἰσχρὸν τῷ ἐναντίῳ, λύπῃ τε καὶ κακῷ;","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη.","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν ἄρα δυοῖν καλοῖν θάτερον κάλλιον ᾖ, ἢ τῷ ἑτέρῳ τούτοιν ἢ ἀμφοτέροις ὑπερβάλλον κάλλιόν ἐστιν, ἤτοι ἡδονῇ ἢ ὠφελίᾳ ἢ ἀμφοτέροις.","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ὅταν δὲ δὴ δυοῖν αἰσχροῖν τὸ","st":"475a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕτερον αἴσχιον ᾖ, ἤτοι λύπῃ ἢ κακῷ ὑπερβάλλον αἴσχιον ἔσται: ἢ οὐκ ἀνάγκη;","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, πῶς ἐλέγετο νυνδὴ περὶ τοῦ ἀδικεῖν καὶ ἀδικεῖσθαι; οὐκ ἔλεγες τὸ μὲν ἀδικεῖσθαι κάκιον εἶναι, τὸ δὲ ἀδικεῖν αἴσχιον;","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔλεγον.","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ αἴσχιον τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι, ἤτοι λυπηρότερόν ἐστιν καὶ λύπῃ ὑπερβάλλον αἴσχιον ἂν εἴη ἢ κακῷ ἢ ἀμφοτέροις; οὐ καὶ τοῦτο ἀνάγκη;","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς γὰρ οὔ;","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον","st":"475b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὲν δὴ σκεψώμεθα, ἆρα λύπῃ ὑπερβάλλει τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι, καὶ ἀλγοῦσι μᾶλλον οἱ ἀδικοῦντες ἢ οἱ ἀδικούμενοι;","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐδαμῶς, ὦ Σώκρατες, τοῦτό γε.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα λύπῃ γε ὑπερέχει.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ δῆτα.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ μὴ λύπῃ, ἀμφοτέροις μὲν οὐκ ἂν ἔτι ὑπερβάλλοι.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐ φαίνεται.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τῷ ἑτέρῳ λείπεται.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῷ κακῷ.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικεν.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν κακῷ ὑπερβάλλον τὸ ἀδικεῖν κάκιον ἂν εἴη τοῦ ἀδικεῖσθαι.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον δὴ ὅτι.","st":"475c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλο τι οὖν ὑπὸ μὲν τῶν πολλῶν ἀνθρώπων καὶ ὑπὸ σοῦ ὡμολογεῖτο ἡμῖν ἐν τῷ ἔμπροσθεν χρόνῳ αἴσχιον εἶναι τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι;","st":"475d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"475d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δέ γε κάκιον ἐφάνη.","st":"475d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικε.","st":"475d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δέξαιο ἂν οὖν σὺ μᾶλλον τὸ κάκιον καὶ τὸ αἴσχιον ἀντὶ τοῦ ἧττον; μὴ ὄκνει ἀποκρίνασθαι, ὦ Πῶλε: οὐδὲν γὰρ βλαβήσῃ: ἀλλὰ γενναίως τῷ λόγῳ ὥσπερ ἰατρῷ παρέχων ἀποκρίνου, καὶ ἢ","st":"475d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φάθι ἢ μὴ ἃ ἐρωτῶ.","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ οὐκ ἂν δεξαίμην, ὦ Σώκρατες.","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλος δέ τις ἀνθρώπων;","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὔ μοι δοκεῖ κατά γε τοῦτον τὸν λόγον.","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθῆ ἄρα ἐγὼ ἔλεγον, ὅτι οὔτ’ ἂν ἐγὼ οὔτ’ ἂν σὺ οὔτ’ ἄλλος οὐδεὶς ἀνθρώπων δέξαιτ’ ἂν μᾶλλον ἀδικεῖν ἢ ἀδικεῖσθαι: κάκιον γὰρ τυγχάνει ὄν.","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁρᾷς οὖν, ὦ Πῶλε, ὁ ἔλεγχος παρὰ τὸν ἔλεγχον παραβαλλόμενος ὅτι οὐδὲν ἔοικεν, ἀλλὰ σοὶ μὲν οἱ ἄλλοι πάντες ὁμολογοῦσιν πλὴν ἐμοῦ, ἐμοὶ δὲ σὺ ἐξαρκεῖς εἷς ὢν","st":"475e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μόνος καὶ ὁμολογῶν καὶ μαρτυρῶν, καὶ ἐγὼ σὲ μόνον ἐπιψηφίζων τοὺς ἄλλους ἐῶ χαίρειν. καὶ τοῦτο μὲν ἡμῖν οὕτως ἐχέτω: μετὰ τοῦτο δὲ περὶ οὗ τὸ δεύτερον ἠμφεσβητήσαμεν σκεψώμεθα, τὸ ἀδικοῦντα διδόναι δίκην ἆρα μέγιστον τῶν κακῶν ἐστιν, ὡς σὺ ᾤου, ἢ μεῖζον τὸ μὴ διδόναι, ὡς αὖ ἐγὼ ᾤμην.","st":"476a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκοπώμεθα δὲ τῇδε: τὸ διδόναι δίκην καὶ τὸ κολάζεσθαι δικαίως ἀδικοῦντα ἆρα τὸ αὐτὸ καλεῖς;","st":"476a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"476a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχεις οὖν λέγειν ὡς οὐχὶ τά γε δίκαια πάντα καλά ἐστιν, καθ’ ὅσον δίκαια; καὶ διασκεψάμενος εἰπέ.","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλά μοι δοκεῖ, ὦ Σώκρατες.","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκόπει δὴ καὶ τόδε: ἆρα εἴ τίς τι ποιεῖ, ἀνάγκη τι εἶναι καὶ πάσχον ὑπὸ τούτου τοῦ ποιοῦντος;","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔμοιγε δοκεῖ.","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα τοῦτο πάσχον ὃ τὸ ποιοῦν ποιεῖ, καὶ τοιοῦτον οἷον ποιεῖ τὸ ποιοῦν; λέγω δὲ τὸ τοιόνδε: εἴ τις τύπτει, ἀνάγκη τι τύπτεσθαι;","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη.","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ εἰ σφόδρα τύπτει ἢ ταχὺ ὁ","st":"476b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τύπτων, οὕτω καὶ τὸ τυπτόμενον τύπτεσθαι;","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοιοῦτον ἄρα πάθος τῷ τυπτομένῳ ἐστὶν οἷον ἂν τὸ τύπτον ποιῇ;","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ εἰ κάει τις, ἀνάγκη τι κάεσθαι;","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς γὰρ οὔ;","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ εἰ σφόδρα γε κάει ἢ ἀλγεινῶς, οὕτω κάεσθαι τὸ καόμενον ὡς ἂν τὸ κᾶον κάῃ;","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ εἰ τέμνει τι, ὁ αὐτὸς λόγος; τέμνεται γάρ τι.","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ εἰ μέγα γε ἢ βαθὺ τὸ τμῆμα ἢ ἀλγεινόν, τοιοῦτον","st":"476c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τμῆμα τέμνεται τὸ τεμνόμενον οἷον τὸ τέμνον τέμνει;","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> συλλήβδην δὴ ὅρα εἰ ὁμολογεῖς, ὃ ἄρτι ἔλεγον, περὶ πάντων, οἷον ἂν ποιῇ τὸ ποιοῦν, τοιοῦτον τὸ πάσχον πάσχειν.","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀλλ’ ὁμολογῶ.","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων δὴ ὁμολογουμένων, τὸ δίκην διδόναι πότερον πάσχειν τί ἐστιν ἢ ποιεῖν;","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη, ὦ Σώκρατες, πάσχειν.","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὑπό τινος ποιοῦντος;","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς γὰρ οὔ; ὑπό γε τοῦ κολάζοντος.","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δὲ ὀρθῶς κολάζων","st":"476d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δικαίως κολάζει;","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δίκαια ποιῶν ἢ οὔ;","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δίκαια.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁ κολαζόμενος δίκην διδοὺς δίκαια πάσχει;","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δὲ δίκαιά που καλὰ ὡμολόγηται;","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων ἄρα ὁ μὲν ποιεῖ καλά, ὁ δὲ πάσχει, ὁ κολαζόμενος.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"476e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ καλά, ἀγαθά; ἢ γὰρ ἡδέα ἢ ὠφέλιμα.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγαθὰ ἄρα πάσχει ὁ δίκην διδούς;","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικεν.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὠφελεῖται ἄρα;","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα ἥνπερ ἐγὼ ὑπολαμβάνω τὴν ὠφελίαν; βελτίων τὴν ψυχὴν γίγνεται, εἴπερ δικαίως κολάζεται;","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> εἰκός γε.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακίας ἄρα ψυχῆς ἀπαλλάττεται ὁ δίκην διδούς;","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα οὖν τοῦ μεγίστου ἀπαλλάττεται","st":"477a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακοῦ; ὧδε δὲ σκόπει: ἐν χρημάτων κατασκευῇ ἀνθρώπου κακίαν ἄλλην τινὰ ἐνορᾷς ἢ πενίαν;","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὔκ, ἀλλὰ πενίαν.","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ’ ἐν σώματος κατασκευῇ; κακίαν ἂν φήσαις ἀσθένειαν εἶναι καὶ νόσον καὶ αἶσχος καὶ τὰ τοιαῦτα;","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔγωγε.","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἐν ψυχῇ πονηρίαν ἡγῇ τινα εἶναι;","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς γὰρ οὔ;","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτην οὖν οὐκ ἀδικίαν καλεῖς καὶ ἀμαθίαν καὶ δειλίαν καὶ τὰ τοιαῦτα;","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ μὲν οὖν.","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν χρημάτων","st":"477b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ σώματος καὶ ψυχῆς, τριῶν ὄντων, τριττὰς εἴρηκας πονηρίας, πενίαν, νόσον, ἀδικίαν;","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν τούτων τῶν πονηριῶν αἰσχίστη; οὐχ ἡ ἀδικία καὶ συλλήβδην ἡ τῆς ψυχῆς πονηρία;","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πολύ γε.","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δὴ αἰσχίστη, καὶ κακίστη;","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς, ὦ Σώκρατες, λέγεις;","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡδί: ἀεὶ τὸ αἴσχιστον ἤτοι λύπην μεγίστην παρέχον ἢ βλάβην ἢ ἀμφότερα αἴσχιστόν ἐστιν ἐκ τῶν ὡμολογημένων ἐν τῷ ἔμπροσθεν.","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> μάλιστα.","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αἴσχιστον δὲ ἀδικία καὶ σύμπασα ψυχῆς πονηρία νυνδὴ","st":"477c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡμολόγηται ἡμῖν;","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ὡμολόγηται γάρ.","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἢ ἀνιαρότατόν ἐστι καὶ ἀνίᾳ ὑπερβάλλον αἴσχιστον τούτων ἐστὶν ἢ βλάβῃ ἢ ἀμφότερα;","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη.","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν ἀλγεινότερόν ἐστιν τοῦ πένεσθαι καὶ κάμνειν τὸ ἄδικον εἶναι καὶ ἀκόλαστον καὶ δειλὸν καὶ ἀμαθῆ;","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔμοιγε δοκεῖ, ὦ Σώκρατες, ἀπὸ τούτων γε.","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὑπερφυεῖ τινι ἄρα ὡς μεγάλῃ βλάβῃ καὶ κακῷ θαυμασίῳ ὑπερβάλλουσα","st":"477d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τἆλλα ἡ τῆς ψυχῆς πονηρία αἴσχιστόν ἐστι πάντων, ἐπειδὴ οὐκ ἀλγηδόνι γε, ὡς ὁ σὸς λόγος.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μήν που τό γε μεγίστῃ βλάβῃ ὑπερβάλλον μέγιστον ἂν κακὸν εἴη τῶν ὄντων.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ ἀδικία ἄρα καὶ ἡ ἀκολασία καὶ ἡ ἄλλη ψυχῆς πονηρία μέγιστον τῶν ὄντων κακόν ἐστιν;","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν τέχνη πενίας ἀπαλλάττει; οὐ χρηματιστική;","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς δὲ νόσου; οὐκ ἰατρική;","st":"477e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἀνάγκη.","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς δὲ πονηρίας καὶ ἀδικίας; εἰ μὴ οὕτως εὐπορεῖς, ὧδε σκόπει: ποῖ ἄγομεν καὶ παρὰ τίνας τοὺς κάμνοντας τὰ σώματα;","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> παρὰ τοὺς ἰατρούς, ὦ Σώκρατες.","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποῖ δὲ τοὺς ἀδικοῦντας καὶ τοὺς ἀκολασταίνοντας;","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> παρὰ τοὺς δικαστὰς λέγεις;","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν δίκην δώσοντας;","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φημί.","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν οὐ δικαιοσύνῃ τινὶ χρώμενοι κολάζουσιν οἱ ὀρθῶς κολάζοντες;","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον δή.","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χρηματιστικὴ μὲν ἄρα πενίας ἀπαλλάττει,","st":"478a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἰατρικὴ δὲ νόσου, δίκη δὲ ἀκολασίας καὶ ἀδικίας.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν τούτων κάλλιστόν ἐστιν [ὧν λέγεις];","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τίνων λέγεις;","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χρηματιστικῆς, ἰατρικῆς, δίκης.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πολὺ διαφέρει, ὦ Σώκρατες, ἡ δίκη.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αὖ ἤτοι ἡδονὴν πλείστην ποιεῖ ἢ ὠφελίαν ἢ ἀμφότερα, εἴπερ κάλλιστόν ἐστιν;","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν τὸ ἰατρεύεσθαι ἡδύ ἐστιν, καὶ χαίρουσιν οἱ ἰατρευόμενοι;","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> οὐκ ἔμοιγε δοκεῖ.","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ὠφέλιμόν γε. ἦ γάρ;","st":"478b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μεγάλου γὰρ κακοῦ ἀπαλλάττεται, ὥστε λυσιτελεῖ ὑπομεῖναι τὴν ἀλγηδόνα καὶ ὑγιῆ εἶναι.","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πῶς γὰρ οὔ;","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν οὕτως ἂν περὶ σῶμα εὐδαιμονέστατος ἄνθρωπος εἴη, ἰατρευόμενος, ἢ μηδὲ κάμνων ἀρχήν;","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον ὅτι μηδὲ κάμνων.","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ τοῦτ’ ἦν εὐδαιμονία, ὡς ἔοικε, κακοῦ ἀπαλλαγή, ἀλλὰ τὴν ἀρχὴν μηδὲ κτῆσις.","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔστι ταῦτα.","st":"478c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἀθλιώτερος πότερος δυοῖν ἐχόντοιν κακὸν εἴτ’ ἐν σώματι εἴτ’ ἐν ψυχῇ, ὁ ἰατρευόμενος καὶ ἀπαλλαττόμενος τοῦ κακοῦ, ἢ ὁ μὴ ἰατρευόμενος, ἔχων δέ;","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεταί μοι ὁ μὴ ἰατρευόμενος.","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ δίκην διδόναι μεγίστου κακοῦ ἀπαλλαγὴ ἦν, πονηρίας;","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἦν γάρ.","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σωφρονίζει γάρ που καὶ δικαιοτέρους ποιεῖ καὶ ἰατρικὴ γίγνεται πονηρίας ἡ δίκη.","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐδαιμονέστατος μὲν ἄρα ὁ μὴ ἔχων κακίαν ἐν ψυχῇ, ἐπειδὴ τοῦτο","st":"478d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μέγιστον τῶν κακῶν ἐφάνη.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> δῆλον δή.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεύτερος δέ που ὁ ἀπαλλαττόμενος.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικεν.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὗτος δ’ ἦν ὁ νουθετούμενός τε καὶ ἐπιπληττόμενος καὶ δίκην διδούς.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κάκιστα ἄρα ζῇ ὁ ἔχων [ἀδικίαν] καὶ μὴ ἀπαλλαττόμενος.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὗτος τυγχάνει ὢν ὃς ἂν τὰ μέγιστα ἀδικῶν καὶ χρώμενος μεγίστῃ ἀδικίᾳ διαπράξηται ὥστε μήτε νουθετεῖσθαι","st":"478e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μήτε κολάζεσθαι μήτε δίκην διδόναι, ὥσπερ σὺ φῂς Ἀρχέλαον παρεσκευάσθαι καὶ τοὺς ἄλλους τυράννους καὶ ῥήτορας καὶ δυνάστας;","st":"479a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικε.","st":"479a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σχεδὸν γάρ που οὗτοι, ὦ ἄριστε, τὸ αὐτὸ διαπεπραγμένοι εἰσὶν ὥσπερ ἂν εἴ τις τοῖς μεγίστοις νοσήμασιν συνισχόμενος διαπράξαιτο μὴ διδόναι δίκην τῶν περὶ τὸ σῶμα ἁμαρτημάτων τοῖς ἰατροῖς μηδὲ ἰατρεύεσθαι, φοβούμενος ὡσπερανεὶ παῖς τὸ κάεσθαι καὶ τὸ τέμνεσθαι, ὅτι","st":"479a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλγεινόν. ἢ οὐ δοκεῖ καὶ σοὶ οὕτω;","st":"479b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔμοιγε.","st":"479b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγνοῶν γε, ὡς ἔοικεν, οἷόν ἐστιν ἡ ὑγίεια καὶ ἀρετὴ σώματος. κινδυνεύουσι γὰρ ἐκ τῶν νῦν ἡμῖν ὡμολογημένων τοιοῦτόν τι ποιεῖν καὶ οἱ τὴν δίκην φεύγοντες, ὦ Πῶλε, τὸ ἀλγεινὸν αὐτοῦ καθορᾶν, πρὸς δὲ τὸ ὠφέλιμον τυφλῶς ἔχειν καὶ ἀγνοεῖν ὅσῳ ἀθλιώτερόν ἐστι μὴ ὑγιοῦς σώματος μὴ ὑγιεῖ ψυχῇ συνοικεῖν, ἀλλὰ σαθρᾷ καὶ ἀδίκῳ","st":"479b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἀνοσίῳ, ὅθεν καὶ πᾶν ποιοῦσιν ὥστε δίκην μὴ διδόναι μηδ’ ἀπαλλάττεσθαι τοῦ μεγίστου κακοῦ, καὶ χρήματα παρασκευαζόμενοι καὶ φίλους καὶ ὅπως ἂν ὦσιν ὡς πιθανώτατοι λέγειν: εἰ δὲ ἡμεῖς ἀληθῆ ὡμολογήκαμεν, ὦ Πῶλε, ἆρ’ αἰσθάνῃ τὰ συμβαίνοντα ἐκ τοῦ λόγου; ἢ βούλει συλλογισώμεθα αὐτά;","st":"479c"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> εἰ σοί γε δοκεῖ.","st":"479c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν συμβαίνει μέγιστον κακὸν ἡ ἀδικία καὶ τὸ","st":"479c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀδικεῖν;","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεταί γε.","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἀπαλλαγή γε ἐφάνη τούτου τοῦ κακοῦ τὸ δίκην διδόναι;","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> κινδυνεύει.","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δέ γε μὴ διδόναι ἐμμονὴ τοῦ κακοῦ;","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεύτερον ἄρα ἐστὶν τῶν κακῶν μεγέθει τὸ ἀδικεῖν: τὸ δὲ ἀδικοῦντα μὴ διδόναι δίκην πάντων μέγιστόν τε καὶ πρῶτον κακῶν πέφυκεν.","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἔοικεν.","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν οὐ περὶ τούτου, ὦ φίλε, ἠμφεσβητήσαμεν, σὺ μὲν τὸν Ἀρχέλαον εὐδαιμονίζων τὸν τὰ μέγιστα ἀδικοῦντα","st":"479d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δίκην οὐδεμίαν διδόντα, ἐγὼ δὲ τοὐναντίον οἰόμενος, εἴτε Ἀρχέλαος εἴτ’ ἄλλος ἀνθρώπων ὁστισοῦν μὴ δίδωσι δίκην ἀδικῶν, τούτῳ προσήκειν ἀθλίῳ εἶναι διαφερόντως τῶν ἄλλων ἀνθρώπων, καὶ ἀεὶ τὸν ἀδικοῦντα τοῦ ἀδικουμένου ἀθλιώτερον εἶναι καὶ τὸν μὴ διδόντα δίκην τοῦ διδόντος; οὐ ταῦτ’ ἦν τὰ ὑπ’ ἐμοῦ λεγόμενα;","st":"479e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί.","st":"479e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀποδέδεικται ὅτι ἀληθῆ ἐλέγετο;","st":"479e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> φαίνεται.","st":"479e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: εἰ οὖν δὴ ταῦτα ἀληθῆ, ὦ Πῶλε, τίς ἡ μεγάλη χρεία ἐστὶν τῆς ῥητορικῆς; δεῖ μὲν γὰρ δὴ ἐκ τῶν νῦν ὡμολογημένων αὐτὸν ἑαυτὸν μάλιστα φυλάττειν ὅπως μὴ ἀδικήσει, ὡς ἱκανὸν κακὸν ἕξοντα. οὐ γάρ;","st":"480a"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> πάνυ γε.","st":"480a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐὰν δέ γε ἀδικήσῃ ἢ αὐτὸς ἢ ἄλλος τις ὧν ἂν κήδηται, αὐτὸν ἑκόντα ἰέναι ἐκεῖσε ὅπου ὡς τάχιστα δώσει δίκην, παρὰ τὸν δικαστὴν ὥσπερ παρὰ τὸν ἰατρόν,","st":"480a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σπεύδοντα ὅπως μὴ ἐγχρονισθὲν τὸ νόσημα τῆς ἀδικίας ὕπουλον τὴν ψυχὴν ποιήσει καὶ ἀνίατον: ἢ πῶς λέγομεν, ὦ Πῶλε, εἴπερ τὰ πρότερον μένει ἡμῖν ὁμολογήματα; οὐκ ἀνάγκη ταῦτα ἐκείνοις οὕτω μὲν συμφωνεῖν, ἄλλως δὲ μή;","st":"480b"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> τί γὰρ δὴ φῶμεν, ὦ Σώκρατες;","st":"480b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπὶ μὲν ἄρα τὸ ἀπολογεῖσθαι ὑπὲρ τῆς ἀδικίας τῆς αὑτοῦ ἢ γονέων ἢ ἑταίρων ἢ παίδων ἢ πατρίδος ἀδικούσης οὐ χρήσιμος οὐδὲν ἡ ῥητορικὴ ἡμῖν, ὦ Πῶλε, εἰ μὴ εἴ τις","st":"480b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὑπολάβοι ἐπὶ τοὐναντίον — κατηγορεῖν δεῖν μάλιστα μὲν ἑαυτοῦ, ἔπειτα δὲ καὶ τῶν οἰκείων καὶ τῶν ἄλλων ὃς ἂν ἀεὶ τῶν φίλων τυγχάνῃ ἀδικῶν, καὶ μὴ ἀποκρύπτεσθαι ἀλλ’ εἰς τὸ φανερὸν ἄγειν τὸ ἀδίκημα, ἵνα δῷ δίκην καὶ ὑγιὴς γένηται, ἀναγκάζειν τε αὑτὸν καὶ τοὺς ἄλλους μὴ ἀποδειλιᾶν ἀλλὰ παρέχειν μύσαντα εὖ καὶ ἀνδρείως ὥσπερ τέμνειν καὶ κάειν ἰατρῷ, τὸ ἀγαθὸν καὶ καλὸν διώκοντα, μὴ ὑπολογιζόμενον τὸ ἀλγεινόν, ἐὰν μέν γε πληγῶν ἄξια ἠδικηκὼς","st":"480c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ᾖ, τύπτειν παρέχοντα, ἐὰν δὲ δεσμοῦ, δεῖν, ἐὰν δὲ ζημίας, ἀποτίνοντα, ἐὰν δὲ φυγῆς, φεύγοντα, ἐὰν δὲ θανάτου, ἀποθνῄσκοντα, αὐτὸν πρῶτον ὄντα κατήγορον καὶ αὑτοῦ καὶ τῶν ἄλλων οἰκείων καὶ ἐπὶ τοῦτο χρώμενον τῇ ῥητορικῇ, ὅπως ἂν καταδήλων τῶν ἀδικημάτων γιγνομένων ἀπαλλάττωνται τοῦ μεγίστου κακοῦ, ἀδικίας. φῶμεν οὕτως ἢ μὴ φῶμεν, ὦ Πῶλε;","st":"480d"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ἄτοπα μέν, ὦ Σώκρατες, ἔμοιγε δοκεῖ, τοῖς μέντοι ἔμπροσθεν ἴσως σοι ὁμολογεῖται.","st":"480e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἢ κἀκεῖνα λυτέον ἢ τάδε ἀνάγκη συμβαίνειν;","st":"480e"},{"sp":"N","t":"<span class=\"speaker-label\">Πῶλος:<\/span> ναί, τοῦτό γε οὕτως ἔχει.","st":"480e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοὐναντίον δέ γε αὖ μεταβαλόντα, εἰ ἄρα δεῖ τινα κακῶς ποιεῖν, εἴτ’ ἐχθρὸν εἴτε ὁντινοῦν, ἐὰν μόνον μὴ αὐτὸς ἀδικῆται ὑπὸ τοῦ ἐχθροῦ — τοῦτο μὲν γὰρ εὐλαβητέον — ἐὰν δὲ ἄλλον ἀδικῇ ὁ ἐχθρός, παντὶ τρόπῳ παρασκευαστέον, καὶ","st":"480e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πράττοντα καὶ λέγοντα, ὅπως μὴ δῷ δίκην μηδὲ ἔλθῃ παρὰ τὸν δικαστήν: ἐὰν δὲ ἔλθῃ, μηχανητέον ὅπως ἂν διαφύγῃ καὶ μὴ δῷ δίκην ὁ ἐχθρός, ἀλλ’ ἐάντε χρυσίον ⟨ᾖ⟩ ἡρπακὼς πολύ, μὴ ἀποδιδῷ τοῦτο ἀλλ’ ἔχων ἀναλίσκῃ καὶ εἰς ἑαυτὸν καὶ εἰς τοὺς ἑαυτοῦ ἀδίκως καὶ ἀθέως, ἐάντε αὖ θανάτου ἄξια ἠδικηκὼς ᾖ, ὅπως μὴ ἀποθανεῖται, μάλιστα μὲν μηδέποτε, ἀλλ’ ἀθάνατος ἔσται πονηρὸς ὤν, εἰ δὲ μή, ὅπως ὡς","st":"481a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πλεῖστον χρόνον βιώσεται τοιοῦτος ὤν. ἐπὶ τὰ τοιαῦτα ἔμοιγε δοκεῖ, ὦ Πῶλε, ἡ ῥητορικὴ χρήσιμος εἶναι, ἐπεὶ τῷ γε μὴ μέλλοντι ἀδικεῖν οὐ μεγάλη τίς μοι δοκεῖ ἡ χρεία αὐτῆς εἶναι, εἰ δὴ καὶ ἔστιν τις χρεία, ὡς ἔν γε τοῖς πρόσθεν οὐδαμῇ ἐφάνη οὖσα.","st":"481b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> εἰπέ μοι, ὦ Χαιρεφῶν, σπουδάζει ταῦτα Σωκράτης ἢ παίζει;","st":"481b"},{"sp":"N","t":"<span class=\"speaker-label\">Χαιρεφῶν:<\/span> ἐμοὶ μὲν δοκεῖ, ὦ Καλλίκλεις, ὑπερφυῶς σπουδάζειν: οὐδὲν μέντοι οἷον τὸ αὐτὸν ἐρωτᾶν.","st":"481b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> νὴ τοὺς θεοὺς ἀλλ’ ἐπιθυμῶ. εἰπέ μοι, ὦ Σώκρατες,","st":"481b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πότερόν σε θῶμεν νυνὶ σπουδάζοντα ἢ παίζοντα; εἰ μὲν γὰρ σπουδάζεις τε καὶ τυγχάνει ταῦτα ἀληθῆ ὄντα ἃ λέγεις, ἄλλο τι ἢ ἡμῶν ὁ βίος ἀνατετραμμένος ἂν εἴη τῶν ἀνθρώπων καὶ πάντα τὰ ἐναντία πράττομεν, ὡς ἔοικεν, ἢ ἃ δεῖ;","st":"481c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ Καλλίκλεις, εἰ μή τι ἦν τοῖς ἀνθρώποις πάθος, τοῖς μὲν ἄλλο τι, τοῖς δὲ ἄλλο τι [ἢ] τὸ αὐτό, ἀλλά τις ἡμῶν ἴδιόν τι ἔπασχεν πάθος ἢ οἱ ἄλλοι, οὐκ ἂν ἦν ῥᾴδιον","st":"481c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐνδείξασθαι τῷ ἑτέρῳ τὸ ἑαυτοῦ πάθημα. λέγω δ’ ἐννοήσας ὅτι ἐγώ τε καὶ σὺ νῦν τυγχάνομεν ταὐτόν τι πεπονθότες, ἐρῶντε δύο ὄντε δυοῖν ἑκάτερος, ἐγὼ μὲν Ἀλκιβιάδου τε τοῦ Κλεινίου καὶ φιλοσοφίας, σὺ δὲ δυοῖν, τοῦ τε Ἀθηναίων δήμου καὶ τοῦ Πυριλάμπους. αἰσθάνομαι οὖν σου ἑκάστοτε, καίπερ ὄντος δεινοῦ, ὅτι ἂν φῇ σου τὰ παιδικὰ καὶ ὅπως ἂν φῇ ἔχειν, οὐ δυναμένου ἀντιλέγειν, ἀλλ’ ἄνω","st":"481d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ κάτω μεταβαλλομένου: ἔν τε τῇ ἐκκλησίᾳ, ἐάν τι σοῦ λέγοντος ὁ δῆμος ὁ Ἀθηναίων μὴ φῇ οὕτως ἔχειν, μεταβαλλόμενος λέγεις ἃ ἐκεῖνος βούλεται, καὶ πρὸς τὸν Πυριλάμπους νεανίαν τὸν καλὸν τοῦτον τοιαῦτα ἕτερα πέπονθας. τοῖς γὰρ τῶν παιδικῶν βουλεύμασίν τε καὶ λόγοις οὐχ οἷός τ’ εἶ ἐναντιοῦσθαι, ὥστε, εἴ τίς σου λέγοντος ἑκάστοτε ἃ διὰ τούτους λέγεις θαυμάζοι ὡς ἄτοπά ἐστιν, ἴσως εἴποις ἂν αὐτῷ, εἰ βούλοιο τἀληθῆ λέγειν, ὅτι εἰ μή τις παύσει τὰ","st":"481e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σὰ παιδικὰ τούτων τῶν λόγων, οὐδὲ σὺ παύσῃ ποτὲ ταῦτα λέγων. νόμιζε τοίνυν καὶ παρ’ ἐμοῦ χρῆναι ἕτερα τοιαῦτα ἀκούειν, καὶ μὴ θαύμαζε ὅτι ἐγὼ ταῦτα λέγω, ἀλλὰ τὴν φιλοσοφίαν, τὰ ἐμὰ παιδικά, παῦσον ταῦτα λέγουσαν. λέγει γάρ, ὦ φίλε ἑταῖρε, ἃ νῦν ἐμοῦ ἀκούεις, καί μοί ἐστιν τῶν ἑτέρων παιδικῶν πολὺ ἧττον ἔμπληκτος: ὁ μὲν γὰρ Κλεινίειος οὗτος ἄλλοτε ἄλλων ἐστὶ λόγων, ἡ δὲ φιλοσοφία ἀεὶ","st":"482a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν αὐτῶν, λέγει δὲ ἃ σὺ νῦν θαυμάζεις, παρῆσθα δὲ καὶ αὐτὸς λεγομένοις. ἢ οὖν ἐκείνην ἐξέλεγξον, ὅπερ ἄρτι ἔλεγον, ὡς οὐ τὸ ἀδικεῖν ἐστιν καὶ ἀδικοῦντα δίκην μὴ διδόναι ἁπάντων ἔσχατον κακῶν: ἢ εἰ τοῦτο ἐάσεις ἀνέλεγκτον, μὰ τὸν κύνα τὸν Αἰγυπτίων θεόν, οὔ σοι ὁμολογήσει Καλλικλῆς, ὦ Καλλίκλεις, ἀλλὰ διαφωνήσει ἐν ἅπαντι τῷ βίῳ. καίτοι ἔγωγε οἶμαι, ὦ βέλτιστε, καὶ τὴν λύραν μοι κρεῖττον εἶναι ἀνάρμοστόν τε καὶ διαφωνεῖν, καὶ χορὸν ᾧ χορηγοίην,","st":"482b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ πλείστους ἀνθρώπους μὴ ὁμολογεῖν μοι ἀλλ’ ἐναντία λέγειν μᾶλλον ἢ ἕνα ὄντα ἐμὲ ἐμαυτῷ ἀσύμφωνον εἶναι καὶ ἐναντία λέγειν.","st":"482c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὦ Σώκρατες, δοκεῖς νεανιεύεσθαι ἐν τοῖς λόγοις ὡς ἀληθῶς δημηγόρος ὤν: καὶ νῦν ταῦτα δημηγορεῖς ταὐτὸν παθόντος Πώλου πάθος ὅπερ Γοργίου κατηγόρει πρὸς σὲ παθεῖν. ἔφη γάρ που Γοργίαν ἐρωτώμενον ὑπὸ σοῦ, ἐὰν ἀφίκηται παρ’ αὐτὸν μὴ ἐπιστάμενος τὰ δίκαια ὁ τὴν ῥητορικὴν","st":"482c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> βουλόμενος μαθεῖν, εἰ διδάξοι αὐτὸν ὁ Γοργίας, αἰσχυνθῆναι αὐτὸν καὶ φάναι διδάξειν διὰ τὸ ἔθος τῶν ἀνθρώπων, ὅτι ἀγανακτοῖεν ἂν εἴ τις μὴ φαίη — διὰ δὴ ταύτην τὴν ὁμολογίαν ἀναγκασθῆναι ἐναντία αὐτὸν αὑτῷ εἰπεῖν, σὲ δὲ αὐτὸ τοῦτο ἀγαπᾶν — καί σου καταγελᾶν, ὥς γέ μοι δοκεῖν ὀρθῶς, τότε: νῦν δὲ πάλιν αὐτὸς ταὐτὸν τοῦτο ἔπαθεν. καὶ ἔγωγε κατ’ αὐτὸ τοῦτο οὐκ ἄγαμαι Πῶλον, ὅτι σοι συνεχώρησεν τὸ ἀδικεῖν αἴσχιον εἶναι τοῦ ἀδικεῖσθαι: ἐκ","st":"482d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ταύτης γὰρ αὖ τῆς ὁμολογίας αὐτὸς ὑπὸ σοῦ συμποδισθεὶς ἐν τοῖς λόγοις ἐπεστομίσθη, αἰσχυνθεὶς ἃ ἐνόει εἰπεῖν. σὺ γὰρ τῷ ὄντι, ὦ Σώκρατες, εἰς τοιαῦτα ἄγεις φορτικὰ καὶ δημηγορικά, φάσκων τὴν ἀλήθειαν διώκειν, ἃ φύσει μὲν οὐκ ἔστιν καλά, νόμῳ δέ. ὡς τὰ πολλὰ δὲ ταῦτα ἐναντί’ ἀλλήλοις ἐστίν, ἥ τε φύσις καὶ ὁ νόμος: ἐὰν οὖν τις αἰσχύνηται","st":"482e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> καὶ μὴ τολμᾷ λέγειν ἅπερ νοεῖ, ἀναγκάζεται ἐναντία λέγειν. ὃ δὴ καὶ σὺ τοῦτο τὸ σοφὸν κατανενοηκὼς κακουργεῖς ἐν τοῖς λόγοις, ἐὰν μέν τις κατὰ νόμον λέγῃ, κατὰ φύσιν ὑπερωτῶν, ἐὰν δὲ τὰ τῆς φύσεως, τὰ τοῦ νόμου. ὥσπερ αὐτίκα ἐν τούτοις, τῷ ἀδικεῖν τε καὶ τῷ ἀδικεῖσθαι, Πώλου τὸ κατὰ νόμον αἴσχιον λέγοντος, σὺ τὸν λόγον ἐδιώκαθες κατὰ φύσιν. φύσει μὲν γὰρ πᾶν αἴσχιόν ἐστιν ὅπερ καὶ κάκιον, τὸ ἀδικεῖσθαι, νόμῳ δὲ τὸ ἀδικεῖν. οὐδὲ","st":"483a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> γὰρ ἀνδρὸς τοῦτό γ’ ἐστὶν τὸ πάθημα, τὸ ἀδικεῖσθαι, ἀλλ’ ἀνδραπόδου τινὸς ᾧ κρεῖττόν ἐστιν τεθνάναι ἢ ζῆν, ὅστις ἀδικούμενος καὶ προπηλακιζόμενος μὴ οἷός τέ ἐστιν αὐτὸς αὑτῷ βοηθεῖν μηδὲ ἄλλῳ οὗ ἂν κήδηται. ἀλλ’ οἶμαι οἱ τιθέμενοι τοὺς νόμους οἱ ἀσθενεῖς ἄνθρωποί εἰσιν καὶ οἱ πολλοί. πρὸς αὑτοὺς οὖν καὶ τὸ αὑτοῖς συμφέρον τούς τε νόμους τίθενται καὶ τοὺς ἐπαίνους ἐπαινοῦσιν καὶ τοὺς","st":"483b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ψόγους ψέγουσιν: ἐκφοβοῦντες τοὺς ἐρρωμενεστέρους τῶν ἀνθρώπων καὶ δυνατοὺς ὄντας πλέον ἔχειν, ἵνα μὴ αὐτῶν πλέον ἔχωσιν, λέγουσιν ὡς αἰσχρὸν καὶ ἄδικον τὸ πλεονεκτεῖν, καὶ τοῦτό ἐστιν τὸ ἀδικεῖν, τὸ πλέον τῶν ἄλλων ζητεῖν ἔχειν: ἀγαπῶσι γὰρ οἶμαι αὐτοὶ ἂν τὸ ἴσον ἔχωσιν φαυλότεροι ὄντες. διὰ ταῦτα δὴ νόμῳ μὲν τοῦτο ἄδικον καὶ αἰσχρὸν λέγεται, τὸ πλέον ζητεῖν ἔχειν τῶν πολλῶν, καὶ ἀδικεῖν αὐτὸ καλοῦσιν: ἡ δέ γε οἶμαι φύσις αὐτὴ ἀποφαίνει","st":"483c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> αὐτό, ὅτι δίκαιόν ἐστιν τὸν ἀμείνω τοῦ χείρονος πλέον ἔχειν καὶ τὸν δυνατώτερον τοῦ ἀδυνατωτέρου. δηλοῖ δὲ ταῦτα πολλαχοῦ ὅτι οὕτως ἔχει, καὶ ἐν τοῖς ἄλλοις ζῴοις καὶ τῶν ἀνθρώπων ἐν ὅλαις ταῖς πόλεσι καὶ τοῖς γένεσιν, ὅτι οὕτω τὸ δίκαιον κέκριται, τὸν κρείττω τοῦ ἥττονος ἄρχειν καὶ πλέον ἔχειν. ἐπεὶ ποίῳ δικαίῳ χρώμενος Ξέρξης ἐπὶ τὴν Ἑλλάδα ἐστράτευσεν ἢ ὁ πατὴρ αὐτοῦ ἐπὶ Σκύθας; ἢ","st":"483d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἄλλα μυρία ἄν τις ἔχοι τοιαῦτα λέγειν. ἀλλ’ οἶμαι οὗτοι κατὰ φύσιν τὴν τοῦ δικαίου ταῦτα πράττουσιν, καὶ ναὶ μὰ Δία κατὰ νόμον γε τὸν τῆς φύσεως, οὐ μέντοι ἴσως κατὰ τοῦτον ὃν ἡμεῖς τιθέμεθα: πλάττοντες τοὺς βελτίστους καὶ ἐρρωμενεστάτους ἡμῶν αὐτῶν, ἐκ νέων λαμβάνοντες, ὥσπερ λέοντας, κατεπᾴδοντές τε καὶ γοητεύοντες καταδουλούμεθα","st":"483e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγοντες ὡς τὸ ἴσον χρὴ ἔχειν καὶ τοῦτό ἐστιν τὸ καλὸν καὶ τὸ δίκαιον. ἐὰν δέ γε οἶμαι φύσιν ἱκανὴν γένηται ἔχων ἀνήρ, πάντα ταῦτα ἀποσεισάμενος καὶ διαρρήξας καὶ διαφυγών, καταπατήσας τὰ ἡμέτερα γράμματα καὶ μαγγανεύματα καὶ ἐπῳδὰς καὶ νόμους τοὺς παρὰ φύσιν ἅπαντας, ἐπαναστὰς ἀνεφάνη δεσπότης ἡμέτερος ὁ δοῦλος, καὶ ἐνταῦθα","st":"484a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἐξέλαμψεν τὸ τῆς φύσεως δίκαιον. δοκεῖ δέ μοι καὶ Πίνδαρος ἅπερ ἐγὼ λέγω ἐνδείκνυσθαι ἐν τῷ ᾄσματι ἐν ᾧ λέγει ὅτι —","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> νόμος ὁ πάντων βασιλεὺς","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> θνατῶν τε καὶ ἀθανάτων:","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὗτος δὲ δή, φησίν, —","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἄγει δικαιῶν τὸ βιαιότατον","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὑπερτάτᾳ χειρί: τεκμαίρομαι","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔργοισιν Ἡρακλέος, ἐπεὶ — ἀπριάτας —","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγει οὕτω πως — τὸ γὰρ ᾆσμα οὐκ ἐπίσταμαι — λέγει δ’ ὅτι οὔτε πριάμενος οὔτε δόντος τοῦ Γηρυόνου ἠλάσατο τὰς βοῦς,","st":"484b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς τούτου ὄντος τοῦ δικαίου φύσει, καὶ βοῦς καὶ τἆλλα κτήματα εἶναι πάντα τοῦ βελτίονός τε καὶ κρείττονος τὰ τῶν χειρόνων τε καὶ ἡττόνων.","st":"484c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τὸ μὲν οὖν ἀληθὲς οὕτως ἔχει, γνώσῃ δέ, ἂν ἐπὶ τὰ μείζω ἔλθῃς ἐάσας ἤδη φιλοσοφίαν. φιλοσοφία γάρ τοί ἐστιν, ὦ Σώκρατες, χαρίεν, ἄν τις αὐτοῦ μετρίως ἅψηται ἐν τῇ ἡλικίᾳ: ἐὰν δὲ περαιτέρω τοῦ δέοντος ἐνδιατρίψῃ, διαφθορὰ τῶν ἀνθρώπων. ἐὰν γὰρ καὶ πάνυ εὐφυὴς ᾖ καὶ πόρρω τῆς ἡλικίας φιλοσοφῇ, ἀνάγκη πάντων ἄπειρον γεγονέναι","st":"484c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἐστὶν ὧν χρὴ ἔμπειρον εἶναι τὸν μέλλοντα καλὸν κἀγαθὸν καὶ εὐδόκιμον ἔσεσθαι ἄνδρα. καὶ γὰρ τῶν νόμων ἄπειροι γίγνονται τῶν κατὰ τὴν πόλιν, καὶ τῶν λόγων οἷς δεῖ χρώμενον ὁμιλεῖν ἐν τοῖς συμβολαίοις τοῖς ἀνθρώποις καὶ ἰδίᾳ καὶ δημοσίᾳ, καὶ τῶν ἡδονῶν τε καὶ ἐπιθυμιῶν τῶν ἀνθρωπείων, καὶ συλλήβδην τῶν ἠθῶν παντάπασιν ἄπειροι γίγνονται. ἐπειδὰν οὖν ἔλθωσιν εἴς τινα ἰδίαν ἢ πολιτικὴν","st":"484d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πρᾶξιν, καταγέλαστοι γίγνονται, ὥσπερ γε οἶμαι οἱ πολιτικοί, ἐπειδὰν αὖ εἰς τὰς ὑμετέρας διατριβὰς ἔλθωσιν καὶ τοὺς λόγους, καταγέλαστοί εἰσιν. συμβαίνει γὰρ τὸ τοῦ Εὐριπίδου: λαμπρός τέ ἐστιν ἕκαστος ἐν τούτῳ, καὶ ἐπὶ τοῦτ’ ἐπείγεται,","st":"484e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> νέμων τὸ πλεῖστον ἡμέρας τούτῳ μέρος,","st":"484e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἵν’ αὐτὸς αὑτοῦ τυγχάνει βέλτιστος ὤν:","st":"484e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὅπου δ’ ἂν φαῦλος ᾖ, ἐντεῦθεν φεύγει καὶ λοιδορεῖ τοῦτο, τὸ δ’ ἕτερον ἐπαινεῖ, εὐνοίᾳ τῇ ἑαυτοῦ, ἡγούμενος οὕτως αὐτὸς ἑαυτὸν ἐπαινεῖν. ἀλλ’ οἶμαι τὸ ὀρθότατόν ἐστιν ἀμφοτέρων μετασχεῖν. φιλοσοφίας μὲν ὅσον παιδείας χάριν καλὸν μετέχειν, καὶ οὐκ αἰσχρὸν μειρακίῳ ὄντι φιλοσοφεῖν: ἐπειδὰν δὲ ἤδη πρεσβύτερος ὢν ἄνθρωπος ἔτι φιλοσοφῇ, καταγέλαστον, ὦ Σώκρατες, τὸ χρῆμα γίγνεται, καὶ ἔγωγε","st":"485a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὁμοιότατον πάσχω πρὸς τοὺς φιλοσοφοῦντας ὥσπερ πρὸς τοὺς ψελλιζομένους καὶ παίζοντας. ὅταν μὲν γὰρ παιδίον ἴδω, ᾧ ἔτι προσήκει διαλέγεσθαι οὕτω, ψελλιζόμενον καὶ παῖζον, χαίρω τε καὶ χαρίεν μοι φαίνεται καὶ ἐλευθέριον καὶ πρέπον τῇ τοῦ παιδίου ἡλικίᾳ, ὅταν δὲ σαφῶς διαλεγομένου παιδαρίου ἀκούσω, πικρόν τί μοι δοκεῖ χρῆμα εἶναι καὶ ἀνιᾷ μου τὰ ὦτα καί μοι δοκεῖ δουλοπρεπές τι εἶναι: ὅταν δὲ","st":"485b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀνδρὸς ἀκούσῃ τις ψελλιζομένου ἢ παίζοντα ὁρᾷ, καταγέλαστον φαίνεται καὶ ἄνανδρον καὶ πληγῶν ἄξιον. ταὐτὸν οὖν ἔγωγε τοῦτο πάσχω καὶ πρὸς τοὺς φιλοσοφοῦντας. παρὰ νέῳ μὲν γὰρ μειρακίῳ ὁρῶν φιλοσοφίαν ἄγαμαι, καὶ πρέπειν μοι δοκεῖ, καὶ ἡγοῦμαι ἐλεύθερόν τινα εἶναι τοῦτον τὸν ἄνθρωπον, τὸν δὲ μὴ φιλοσοφοῦντα ἀνελεύθερον καὶ οὐδέποτε οὐδενὸς ἀξιώσοντα ἑαυτὸν οὔτε καλοῦ οὔτε γενναίου","st":"485c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πράγματος: ὅταν δὲ δὴ πρεσβύτερον ἴδω ἔτι φιλοσοφοῦντα καὶ μὴ ἀπαλλαττόμενον, πληγῶν μοι δοκεῖ ἤδη δεῖσθαι, ὦ Σώκρατες, οὗτος ὁ ἀνήρ. ὃ γὰρ νυνδὴ ἔλεγον, ὑπάρχει τούτῳ τῷ ἀνθρώπῳ, κἂν πάνυ εὐφυὴς ᾖ, ἀνάνδρῳ γενέσθαι φεύγοντι τὰ μέσα τῆς πόλεως καὶ τὰς ἀγοράς, ἐν αἷς ἔφη ὁ ποιητὴς τοὺς ἄνδρας ἀριπρεπεῖς γίγνεσθαι, καταδεδυκότι δὲ τὸν λοιπὸν βίον βιῶναι μετὰ μειρακίων ἐν γωνίᾳ τριῶν ἢ","st":"485d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τεττάρων ψιθυρίζοντα, ἐλεύθερον δὲ καὶ μέγα καὶ ἱκανὸν μηδέποτε φθέγξασθαι. ἐγὼ δέ, ὦ Σώκρατες, πρὸς σὲ ἐπιεικῶς ἔχω φιλικῶς: κινδυνεύω οὖν πεπονθέναι νῦν ὅπερ ὁ Ζῆθος πρὸς τὸν Ἀμφίονα ὁ Εὐριπίδου, οὗπερ ἐμνήσθην. καὶ γὰρ ἐμοὶ τοιαῦτ’ ἄττα ἐπέρχεται πρὸς σὲ λέγειν, οἷάπερ ἐκεῖνος πρὸς τὸν ἀδελφόν, ὅτι “ἀμελεῖς, ὦ Σώκρατες, ὧν δεῖ σε ἐπιμελεῖσθαι, καὶ φύσιν ψυχῆς ὧδε γενναίαν μειρακιώδει","st":"485e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τινὶ διατρέπεις μορφώματι, καὶ οὔτ’ ἂν δίκης βουλαῖσι προσθεῖ’ ἂν ὀρθῶς λόγον, οὔτ’ εἰκὸς ἂν καὶ πιθανὸν ἂν λάβοις, οὔθ’ ὑπὲρ ἄλλου νεανικὸν βούλευμα βουλεύσαιο.” καίτοι, ὦ φίλε Σώκρατες — καί μοι μηδὲν ἀχθεσθῇς: εὐνοίᾳ γὰρ ἐρῶ τῇ σῇ — οὐκ αἰσχρὸν δοκεῖ σοι εἶναι οὕτως ἔχειν ὡς ἐγὼ σὲ οἶμαι ἔχειν καὶ τοὺς ἄλλους τοὺς πόρρω ἀεὶ φιλοσοφίας ἐλαύνοντας; νῦν γὰρ εἴ τις σοῦ λαβόμενος ἢ ἄλλου ὁτουοῦν τῶν τοιούτων εἰς τὸ δεσμωτήριον ἀπάγοι, φάσκων ἀδικεῖν μηδὲν ἀδικοῦντα, οἶσθ’ ὅτι οὐκ ἂν ἔχοις ὅτι","st":"486a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> χρήσαιο σαυτῷ, ἀλλ’ ἰλιγγιῴης ἂν καὶ χασμῷο οὐκ ἔχων ὅτι εἴποις, καὶ εἰς τὸ δικαστήριον ἀναβάς, κατηγόρου τυχὼν πάνυ φαύλου καὶ μοχθηροῦ, ἀποθάνοις ἄν, εἰ βούλοιτο θανάτου σοι τιμᾶσθαι. καίτοι πῶς σοφὸν τοῦτό ἐστιν, ὦ Σώκρατες, ἥτις εὐφυῆ λαβοῦσα τέχνη φῶτα ἔθηκε χείρονα, μήτε αὐτὸν αὑτῷ δυνάμενον βοηθεῖν μηδ’ ἐκσῶσαι ἐκ τῶν μεγίστων κινδύνων μήτε ἑαυτὸν μήτε ἄλλον μηδένα, ὑπὸ δὲ","st":"486b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τῶν ἐχθρῶν περισυλᾶσθαι πᾶσαν τὴν οὐσίαν, ἀτεχνῶς δὲ ἄτιμον ζῆν ἐν τῇ πόλει; τὸν δὲ τοιοῦτον, εἴ τι καὶ ἀγροικότερον εἰρῆσθαι, ἔξεστιν ἐπὶ κόρρης τύπτοντα μὴ διδόναι δίκην. ἀλλ’ ὠγαθέ, ἐμοὶ πείθου, παῦσαι δὲ ἐλέγχων, πραγμάτων δ’ εὐμουσίαν ἄσκει, καὶ ἄσκει ὁπόθεν δόξεις φρονεῖν, ἄλλοις τὰ κομψὰ ταῦτα ἀφείς, εἴτε ληρήματα χρὴ φάναι εἶναι εἴτε φλυαρίας, ἐξ ὧν κενοῖσιν ἐγκατοικήσεις δόμοις: ζηλῶν οὐκ ἐλέγχοντας ἄνδρας τὰ μικρὰ","st":"486c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ταῦτα, ἀλλ’ οἷς ἔστιν καὶ βίος καὶ δόξα καὶ ἄλλα πολλὰ ἀγαθά.","st":"486d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ χρυσῆν ἔχων ἐτύγχανον τὴν ψυχήν, ὦ Καλλίκλεις, οὐκ ἂν οἴει με ἅσμενον εὑρεῖν τούτων τινὰ τῶν λίθων ᾗ βασανίζουσιν τὸν χρυσόν, τὴν ἀρίστην, πρὸς ἥντινα ἔμελλον προσαγαγὼν αὐτήν, εἴ μοι ὁμολογήσειεν ἐκείνη καλῶς τεθεραπεῦσθαι τὴν ψυχήν, εὖ εἴσεσθαι ὅτι ἱκανῶς ἔχω καὶ οὐδέν με δεῖ ἄλλης βασάνου;","st":"486d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πρὸς τί δὴ τοῦτο ἐρωτᾷς, ὦ Σώκρατες;","st":"486e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγώ σοι ἐρῶ: νῦν οἶμαι ἐγὼ σοὶ ἐντετυχηκὼς τοιούτῳ ἑρμαίῳ ἐντετυχηκέναι.","st":"486e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί δή;","st":"486e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὖ οἶδ’ ὅτι, ἅν μοι σὺ ὁμολογήσῃς περὶ ὧν ἡ ἐμὴ ψυχὴ δοξάζει, ταῦτ’ ἤδη ἐστὶν αὐτὰ τἀληθῆ. ἐννοῶ γὰρ","st":"486e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι τὸν μέλλοντα βασανιεῖν ἱκανῶς ψυχῆς πέρι ὀρθῶς τε ζώσης καὶ μὴ τρία ἄρα δεῖ ἔχειν ἃ σὺ πάντα ἔχεις, ἐπιστήμην τε καὶ εὔνοιαν καὶ παρρησίαν. ἐγὼ γὰρ πολλοῖς ἐντυγχάνω οἳ ἐμὲ οὐχ οἷοί τέ εἰσιν βασανίζειν διὰ τὸ μὴ σοφοὶ εἶναι ὥσπερ σύ: ἕτεροι δὲ σοφοὶ μέν εἰσιν, οὐκ ἐθέλουσιν δέ μοι λέγειν τὴν ἀλήθειαν διὰ τὸ μὴ κήδεσθαί μου ὥσπερ σύ: τὼ δὲ ξένω τώδε, Γοργίας τε καὶ Πῶλος, σοφὼ μὲν καὶ","st":"487a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φίλω ἐστὸν ἐμώ, ἐνδεεστέρω δὲ παρρησίας καὶ αἰσχυντηροτέρω μᾶλλον τοῦ δέοντος: πῶς γὰρ οὔ; ὥ γε εἰς τοσοῦτον αἰσχύνης ἐληλύθατον, ὥστε διὰ τὸ αἰσχύνεσθαι τολμᾷ ἑκάτερος αὐτῶν αὐτὸς αὑτῷ ἐναντία λέγειν ἐναντίον πολλῶν ἀνθρώπων, καὶ ταῦτα περὶ τῶν μεγίστων. σὺ δὲ ταῦτα πάντα ἔχεις ἃ οἱ ἄλλοι οὐκ ἔχουσιν: πεπαίδευσαί τε γὰρ ἱκανῶς, ὡς πολλοὶ ἂν φήσαιεν Ἀθηναίων, καὶ ἐμοὶ εἶ εὔνους.","st":"487b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίνι τεκμηρίῳ χρῶμαι; ἐγώ σοι ἐρῶ. οἶδα ὑμᾶς ἐγώ, ὦ Καλλίκλεις, τέτταρας ὄντας κοινωνοὺς γεγονότας σοφίας, σέ τε καὶ Τείσανδρον τὸν Ἀφιδναῖον καὶ Ἄνδρωνα τὸν Ἀνδροτίωνος καὶ Ναυσικύδην τὸν Χολαργέα: καί ποτε ὑμῶν ἐγὼ ἐπήκουσα βουλευομένων μέχρι ὅποι τὴν σοφίαν ἀσκητέον εἴη, καὶ οἶδα ὅτι ἐνίκα ἐν ὑμῖν τοιάδε τις δόξα, μὴ προθυμεῖσθαι εἰς τὴν ἀκρίβειαν φιλοσοφεῖν, ἀλλὰ εὐλαβεῖσθαι","st":"487c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρεκελεύεσθε ἀλλήλοις ὅπως μὴ πέρα τοῦ δέοντος σοφώτεροι γενόμενοι λήσετε διαφθαρέντες. ἐπειδὴ οὖν σου ἀκούω ταὐτὰ ἐμοὶ συμβουλεύοντος ἅπερ τοῖς σεαυτοῦ ἑταιροτάτοις, ἱκανόν μοι τεκμήριόν ἐστιν ὅτι ὡς ἀληθῶς μοι εὔνους εἶ. καὶ μὴν ὅτι γε οἷος παρρησιάζεσθαι καὶ μὴ αἰσχύνεσθαι, αὐτός τε φῂς καὶ ὁ λόγος ὃν ὀλίγον πρότερον ἔλεγες ὁμολογεῖ σοι. ἔχει δὴ οὑτωσὶ δῆλον ὅτι τούτων πέρι νυνί:","st":"487d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐάν τι σὺ ἐν τοῖς λόγοις ὁμολογήσῃς μοι, βεβασανισμένον τοῦτ’ ἤδη ἔσται ἱκανῶς ὑπ’ ἐμοῦ τε καὶ σοῦ, καὶ οὐκέτι αὐτὸ δεήσει ἐπ’ ἄλλην βάσανον ἀναφέρειν. οὐ γὰρ ἄν ποτε αὐτὸ συνεχώρησας σὺ οὔτε σοφίας ἐνδείᾳ οὔτ’ αἰσχύνης περιουσίᾳ, οὐδ’ αὖ ἀπατῶν ἐμὲ συγχωρήσαις ἄν: φίλος γάρ μοι εἶ, ὡς καὶ αὐτὸς φῄς. τῷ ὄντι οὖν ἡ ἐμὴ καὶ ἡ σὴ ὁμολογία τέλος ἤδη ἕξει τῆς ἀληθείας. πάντων δὲ καλλίστη ἐστὶν ἡ σκέψις, ὦ Καλλίκλεις, περὶ τούτων ὧν σὺ δή μοι ἐπετίμησας, ποῖόν τινα χρὴ εἶναι τὸν ἄνδρα καὶ τί","st":"487e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπιτηδεύειν καὶ μέχρι τοῦ, καὶ πρεσβύτερον καὶ νεώτερον ὄντα. ἐγὼ γὰρ εἴ τι μὴ ὀρθῶς πράττω κατὰ τὸν βίον τὸν ἐμαυτοῦ, εὖ ἴσθι τοῦτο ὅτι οὐχ ἑκὼν ἐξαμαρτάνω ἀλλ’ ἀμαθίᾳ τῇ ἐμῇ: σὺ οὖν, ὥσπερ ἤρξω νουθετεῖν με, μὴ ἀποστῇς, ἀλλ’ ἱκανῶς μοι ἔνδειξαι τί ἔστιν τοῦτο ὃ ἐπιτηδευτέον μοι, καὶ τίνα τρόπον κτησαίμην ἂν αὐτό, καὶ ἐάν με λάβῃς νῦν μέν σοι ὁμολογήσαντα, ἐν δὲ τῷ ὑστέρῳ χρόνῳ μὴ ταὐτὰ πράττοντα ἅπερ ὡμολόγησα, πάνυ με ἡγοῦ βλᾶκα εἶναι καὶ","st":"488a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μηκέτι ποτέ με νουθετήσῃς ὕστερον, ὡς μηδενὸς ἄξιον ὄντα. ἐξ ἀρχῆς δέ μοι ἐπανάλαβε πῶς φῂς τὸ δίκαιον ἔχειν καὶ σὺ καὶ Πίνδαρος τὸ κατὰ φύσιν; ἄγειν βίᾳ τὸν κρείττω τὰ τῶν ἡττόνων καὶ ἄρχειν τὸν βελτίω τῶν χειρόνων καὶ πλέον ἔχειν τὸν ἀμείνω τοῦ φαυλοτέρου; μή τι ἄλλο λέγεις τὸ δίκαιον εἶναι, ἢ ὀρθῶς μέμνημαι;","st":"488b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ ταῦτα ἔλεγον καὶ τότε καὶ νῦν λέγω.","st":"488b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον δὲ τὸν αὐτὸν βελτίω καλεῖς σὺ καὶ κρείττω;","st":"488b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲ γάρ τοι τότε οἷός τ’ ἦ μαθεῖν σου τί ποτε λέγοις. πότερον τοὺς ἰσχυροτέρους κρείττους καλεῖς καὶ δεῖ ἀκροᾶσθαι τοῦ ἰσχυροτέρου τοὺς ἀσθενεστέρους, οἷόν μοι δοκεῖς καὶ τότε ἐνδείκνυσθαι, ὡς αἱ μεγάλαι πόλεις ἐπὶ τὰς σμικρὰς κατὰ τὸ φύσει δίκαιον ἔρχονται, ὅτι κρείττους εἰσὶν καὶ ἰσχυρότεραι, ὡς τὸ κρεῖττον καὶ τὸ ἰσχυρότερον καὶ βέλτιον ταὐτὸν ὄν, ἢ ἔστι βελτίω μὲν εἶναι, ἥττω δὲ καὶ ἀσθενέστερον, καὶ κρείττω μὲν εἶναι, μοχθηρότερον δέ: ἢ ὁ αὐτὸς","st":"488c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅρος ἐστὶν τοῦ βελτίονος καὶ τοῦ κρείττονος; τοῦτό μοι αὐτὸ σαφῶς διόρισον, ταὐτὸν ἢ ἕτερόν ἐστιν τὸ κρεῖττον καὶ τὸ βέλτιον καὶ τὸ ἰσχυρότερον;","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ἐγώ σοι σαφῶς λέγω, ὅτι ταὐτόν ἐστιν.","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οἱ πολλοὶ τοῦ ἑνὸς κρείττους εἰσὶν κατὰ φύσιν; οἳ δὴ καὶ τοὺς νόμους τίθενται ἐπὶ τῷ ἑνί, ὥσπερ καὶ σὺ ἄρτι ἔλεγες.","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ τῶν πολλῶν ἄρα νόμιμα τὰ τῶν κρειττόνων ἐστίν.","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"488d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ τῶν βελτιόνων; οἱ γὰρ κρείττους βελτίους πολὺ κατὰ τὸν σὸν λόγον.","st":"488e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"488e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ τούτων νόμιμα κατὰ φύσιν καλά, κρειττόνων γε ὄντων;","st":"488e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"488e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν οἱ πολλοὶ νομίζουσιν οὕτως, ὡς ἄρτι αὖ σὺ ἔλεγες, δίκαιον εἶναι τὸ ἴσον ἔχειν καὶ αἴσχιον τὸ ἀδικεῖν","st":"488e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ ἀδικεῖσθαι; ἔστιν ταῦτα ἢ οὔ; καὶ ὅπως μὴ ἁλώσῃ ἐνταῦθα σὺ αὖ αἰσχυνόμενος. νομίζουσιν, ἢ οὔ, οἱ πολλοὶ τὸ ἴσον ἔχειν ἀλλ’ οὐ τὸ πλέον δίκαιον εἶναι, καὶ αἴσχιον τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι; μὴ φθόνει μοι ἀποκρίνασθαι τοῦτο, Καλλίκλεις, ἵν’, ἐάν μοι ὁμολογήσῃς, βεβαιώσωμαι ἤδη παρὰ σοῦ, ἅτε ἱκανοῦ ἀνδρὸς διαγνῶναι ὡμολογηκότος.","st":"489a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ οἵ γε πολλοὶ νομίζουσιν οὕτως.","st":"489a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ νόμῳ ἄρα μόνον ἐστὶν αἴσχιον τὸ ἀδικεῖν τοῦ","st":"489a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀδικεῖσθαι, οὐδὲ δίκαιον τὸ ἴσον ἔχειν, ἀλλὰ καὶ φύσει: ὥστε κινδυνεύεις οὐκ ἀληθῆ λέγειν ἐν τοῖς πρόσθεν οὐδὲ ὀρθῶς ἐμοῦ κατηγορεῖν λέγων ὅτι ἐναντίον ἐστὶν ὁ νόμος καὶ ἡ φύσις, ἃ δὴ καὶ ἐγὼ γνοὺς κακουργῶ ἐν τοῖς λόγοις, ἐὰν μέν τις κατὰ φύσιν λέγῃ, ἐπὶ τὸν νόμον ἄγων, ἐὰν δέ τις κατὰ νόμον, ἐπὶ τὴν φύσιν.","st":"489b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὑτοσὶ ἀνὴρ οὐ παύσεται φλυαρῶν. εἰπέ μοι, ὦ Σώκρατες, οὐκ αἰσχύνῃ τηλικοῦτος ὢν ὀνόματα θηρεύων, καὶ","st":"489b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἐάν τις ῥήματι ἁμάρτῃ, ἕρμαιον τοῦτο ποιούμενος; ἐμὲ γὰρ οἴει ἄλλο τι λέγειν τὸ κρείττους εἶναι ἢ τὸ βελτίους; οὐ πάλαι σοι λέγω ὅτι ταὐτόν φημι εἶναι τὸ βέλτιον καὶ τὸ κρεῖττον; ἢ οἴει με λέγειν, ἐὰν συρφετὸς συλλεγῇ δούλων καὶ παντοδαπῶν ἀνθρώπων μηδενὸς ἀξίων πλὴν ἴσως τῷ σώματι ἰσχυρίσασθαι, καὶ οὗτοι φῶσιν, αὐτὰ ταῦτα εἶναι νόμιμα;","st":"489c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν, ὦ σοφώτατε Καλλίκλεις: οὕτω λέγεις;","st":"489c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ μὲν οὖν.","st":"489c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐγὼ μέν, ὦ δαιμόνιε, καὶ αὐτὸς πάλαι τοπάζω τοιοῦτόν τί σε λέγειν τὸ κρεῖττον, καὶ ἀνερωτῶ γλιχόμενος σαφῶς εἰδέναι ὅτι λέγεις. οὐ γὰρ δήπου σύ γε τοὺς δύο βελτίους ἡγῇ τοῦ ἑνός, οὐδὲ τοὺς σοὺς δούλους βελτίους σου, ὅτι ἰσχυρότεροί εἰσιν ἢ σύ. ἀλλὰ πάλιν ἐξ ἀρχῆς εἰπὲ τί ποτε λέγεις τοὺς βελτίους, ἐπειδὴ οὐ τοὺς ἰσχυροτέρους; καὶ ὦ θαυμάσιε πρᾳότερόν με προδίδασκε, ἵνα μὴ ἀποφοιτήσω παρὰ σοῦ.","st":"489d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> εἰρωνεύῃ, ὦ Σώκρατες.","st":"489e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὰ τὸν Ζῆθον, ὦ Καλλίκλεις, ᾧ σὺ χρώμενος πολλὰ νυνδὴ εἰρωνεύου πρός με: ἀλλ’ ἴθι εἰπέ, τίνας λέγεις τοὺς βελτίους εἶναι;","st":"489e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τοὺς ἀμείνους ἔγωγε.","st":"489e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁρᾷς ἄρα ὅτι σὺ αὐτὸς ὀνόματα λέγεις, δηλοῖς δὲ οὐδέν; οὐκ ἐρεῖς, τοὺς βελτίους καὶ κρείττους πότερον τοὺς φρονιμωτέρους λέγεις ἢ ἄλλους τινάς;","st":"489e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ ναὶ μὰ Δία τούτους λέγω, καὶ σφόδρα γε.","st":"489e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πολλάκις ἄρα εἷς φρονῶν μυρίων μὴ φρονούντων κρείττων ἐστὶν κατὰ τὸν σὸν λόγον, καὶ τοῦτον ἄρχειν δεῖ, τοὺς δ’ ἄρχεσθαι, καὶ πλέον ἔχειν τὸν ἄρχοντα τῶν ἀρχομένων: τοῦτο γάρ μοι δοκεῖς βούλεσθαι λέγειν — καὶ οὐ ῥήματι θηρεύω — εἰ ὁ εἷς τῶν μυρίων κρείττων.","st":"490a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ ταῦτ’ ἔστιν ἃ λέγω. τοῦτο γὰρ οἶμαι ἐγὼ τὸ δίκαιον εἶναι φύσει, τὸ βελτίω ὄντα καὶ φρονιμώτερον καὶ ἄρχειν καὶ πλέον ἔχειν τῶν φαυλοτέρων.","st":"490a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχε δὴ αὐτοῦ. τί ποτε αὖ νῦν λέγεις; ἐὰν ἐν τῷ αὐτῷ ὦμεν, ὥσπερ νῦν, πολλοὶ ἁθρόοι, καὶ ἡμῖν ᾖ ἐν κοινῷ πολλὰ σιτία καὶ ποτά, ὦμεν δὲ παντοδαποί, οἱ μὲν ἰσχυροί, οἱ δ’ ἀσθενεῖς, εἷς δὲ ἡμῶν ᾖ φρονιμώτερος περὶ ταῦτα, ἰατρὸς ὤν, ᾖ δέ, οἷον εἰκός, τῶν μὲν ἰσχυρότερος, τῶν δὲ ἀσθενέστερος, ἄλλο τι ἢ οὗτος, φρονιμώτερος ἡμῶν ὤν, βελτίων καὶ κρείττων ἔσται εἰς ταῦτα;","st":"490b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"490b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ οὖν τούτων τῶν σιτίων πλέον ἡμῶν ἑκτέον αὐτῷ, ὅτι βελτίων ἐστίν, ἢ τῷ μὲν ἄρχειν πάντα ἐκεῖνον δεῖ νέμειν, ἐν τῷ δὲ ἀναλίσκειν τε αὐτὰ καὶ καταχρῆσθαι εἰς τὸ ἑαυτοῦ σῶμα οὐ πλεονεκτητέον, εἰ μὴ μέλλει ζημιοῦσθαι, ἀλλὰ τῶν μὲν πλέον, τῶν δ’ ἔλαττον ἑκτέον: ἐὰν δὲ τύχῃ πάντων ἀσθενέστατος ὤν, πάντων ἐλάχιστον τῷ βελτίστῳ, ὦ Καλλίκλεις; οὐχ οὕτως, ὠγαθέ;","st":"490c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> περὶ σιτία, λέγεις, καὶ ποτὰ καὶ ἰατροὺς καὶ φλυαρίας:","st":"490c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἐγὼ δὲ οὐ ταῦτα λέγω.","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὐ τὸν φρονιμώτερον βελτίω λέγεις; φάθι ἢ μή.","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὐ τὸν βελτίω πλέον δεῖν ἔχειν;","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐ σιτίων γε οὐδὲ ποτῶν.","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνω, ἀλλ’ ἴσως ἱματίων, καὶ δεῖ τὸν ὑφαντικώτατον μέγιστον ἱμάτιον ἔχειν καὶ πλεῖστα καὶ κάλλιστα ἀμπεχόμενον περιιέναι;","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ποίων ἱματίων;","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ εἰς ὑποδήματα δῆλον ὅτι δεῖ πλεονεκτεῖν τὸν","st":"490d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φρονιμώτατον εἰς ταῦτα καὶ βέλτιστον. τὸν σκυτοτόμον ἴσως μέγιστα δεῖ ὑποδήματα καὶ πλεῖστα ὑποδεδεμένον περιπατεῖν.","st":"490e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ποῖα ὑποδήματα; φλυαρεῖς ἔχων.","st":"490e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ εἰ μὴ τὰ τοιαῦτα λέγεις, ἴσως τὰ τοιάδε: οἷον γεωργικὸν ἄνδρα περὶ γῆν φρόνιμόν τε καὶ καλὸν καὶ ἀγαθόν, τοῦτον δὴ ἴσως δεῖ πλεονεκτεῖν τῶν σπερμάτων καὶ ὡς πλείστῳ σπέρματι χρῆσθαι εἰς τὴν αὑτοῦ γῆν.","st":"490e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς ἀεὶ ταὐτὰ λέγεις, ὦ Σώκρατες.","st":"490e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ μόνον γε, ὦ Καλλίκλεις, ἀλλὰ καὶ περὶ τῶν αὐτῶν.","st":"490e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> νὴ τοὺς θεούς, ἀτεχνῶς γε ἀεὶ σκυτέας τε καὶ κναφέας καὶ μαγείρους λέγων καὶ ἰατροὺς οὐδὲν παύῃ, ὡς περὶ τούτων ἡμῖν ὄντα τὸν λόγον.","st":"491a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν σὺ ἐρεῖς περὶ τίνων ὁ κρείττων τε καὶ φρονιμώτερος πλέον ἔχων δικαίως πλεονεκτεῖ; ἢ οὔτε ἐμοῦ ὑποβάλλοντος ἀνέξῃ οὔτ’ αὐτὸς ἐρεῖς;","st":"491a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ἔγωγε καὶ πάλαι λέγω. πρῶτον μὲν τοὺς κρείττους οἵ εἰσιν οὐ σκυτοτόμους λέγω οὐδὲ μαγείρους, ἀλλ’","st":"491a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οἳ ἂν εἰς τὰ τῆς πόλεως πράγματα φρόνιμοι ὦσιν, ὅντινα ἂν τρόπον εὖ οἰκοῖτο, καὶ μὴ μόνον φρόνιμοι, ἀλλὰ καὶ ἀνδρεῖοι, ἱκανοὶ ὄντες ἃ ἂν νοήσωσιν ἐπιτελεῖν, καὶ μὴ ἀποκάμνωσι διὰ μαλακίαν τῆς ψυχῆς.","st":"491b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁρᾷς, ὦ βέλτιστε Καλλίκλεις, ὡς οὐ ταὐτὰ σύ τ’ ἐμοῦ κατηγορεῖς καὶ ἐγὼ σοῦ; σὺ μὲν γὰρ ἐμὲ φῂς ἀεὶ ταὐτὰ λέγειν, καὶ μέμφῃ μοι: ἐγὼ δὲ σοῦ τοὐναντίον, ὅτι οὐδέποτε ταὐτὰ λέγεις περὶ τῶν αὐτῶν, ἀλλὰ τοτὲ μὲν τοὺς","st":"491b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βελτίους τε καὶ κρείττους τοὺς ἰσχυροτέρους ὡρίζου, αὖθις δὲ τοὺς φρονιμωτέρους, νῦν δ’ αὖ ἕτερόν τι ἥκεις ἔχων: ἀνδρειότεροί τινες ὑπὸ σοῦ λέγονται οἱ κρείττους καὶ οἱ βελτίους. ἀλλ’, ὠγαθέ, εἰπὼν ἀπαλλάγηθι τίνας ποτὲ λέγεις τοὺς βελτίους τε καὶ κρείττους καὶ εἰς ὅτι.","st":"491c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ εἴρηκά γε ἔγωγε τοὺς φρονίμους εἰς τὰ τῆς πόλεως πράγματα καὶ ἀνδρείους. τούτους γὰρ","st":"491c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> προσήκει τῶν πόλεων ἄρχειν, καὶ τὸ δίκαιον τοῦτ’ ἐστίν, πλέον ἔχειν τούτους τῶν ἄλλων, τοὺς ἄρχοντας τῶν ἀρχομένων.","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; αὑτῶν, ὦ ἑταῖρε, τί; ἦ τι ἄρχοντας ἢ ἀρχομένους;","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς λέγεις;","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕνα ἕκαστον λέγω αὐτὸν ἑαυτοῦ ἄρχοντα: ἢ τοῦτο μὲν οὐδὲν δεῖ, αὐτὸν ἑαυτοῦ ἄρχειν, τῶν δὲ ἄλλων;","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς ἑαυτοῦ ἄρχοντα λέγεις;","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲν ποικίλον ἀλλ’ ὥσπερ οἱ πολλοί, σώφρονα ὄντα καὶ ἐγκρατῆ αὐτὸν ἑαυτοῦ, τῶν ἡδονῶν καὶ ἐπιθυμιῶν","st":"491d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄρχοντα τῶν ἐν ἑαυτῷ.","st":"491e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς ἡδὺς εἶ: τοὺς ἠλιθίους λέγεις τοὺς σώφρονας.","st":"491e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς γὰρ [οὔ]; οὐδεὶς ὅστις οὐκ ἂν γνοίη ὅτι οὐ τοῦτο λέγω.","st":"491e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε σφόδρα, ὦ Σώκρατες. ἐπεὶ πῶς ἂν εὐδαίμων γένοιτο ἄνθρωπος δουλεύων ὁτῳοῦν; ἀλλὰ τοῦτ’ ἐστὶν τὸ κατὰ φύσιν καλὸν καὶ δίκαιον, ὃ ἐγώ σοι νῦν παρρησιαζόμενος λέγω, ὅτι δεῖ τὸν ὀρθῶς βιωσόμενον τὰς μὲν ἐπιθυμίας τὰς ἑαυτοῦ ἐᾶν ὡς μεγίστας εἶναι καὶ μὴ κολάζειν,","st":"491e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ταύταις δὲ ὡς μεγίσταις οὔσαις ἱκανὸν εἶναι ὑπηρετεῖν δι’ ἀνδρείαν καὶ φρόνησιν, καὶ ἀποπιμπλάναι ὧν ἂν ἀεὶ ἡ ἐπιθυμία γίγνηται. ἀλλὰ τοῦτ’ οἶμαι τοῖς πολλοῖς οὐ δυνατόν: ὅθεν ψέγουσιν τοὺς τοιούτους δι’ αἰσχύνην, ἀποκρυπτόμενοι τὴν αὑτῶν ἀδυναμίαν, καὶ αἰσχρὸν δή φασιν εἶναι τὴν ἀκολασίαν, ὅπερ ἐν τοῖς πρόσθεν ἐγὼ ἔλεγον, δουλούμενοι τοὺς βελτίους τὴν φύσιν ἀνθρώπους, καὶ αὐτοὶ οὐ δυνάμενοι ἐκπορίζεσθαι ταῖς ἡδοναῖς πλήρωσιν ἐπαινοῦσιν τὴν σωφροσύνην","st":"492a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> καὶ τὴν δικαιοσύνην διὰ τὴν αὑτῶν ἀνανδρίαν. ἐπεὶ ὅσοις ἐξ ἀρχῆς ὑπῆρξεν ἢ βασιλέων ὑέσιν εἶναι ἢ αὐτοὺς τῇ φύσει ἱκανοὺς ἐκπορίσασθαι ἀρχήν τινα ἢ τυραννίδα ἢ δυναστείαν, ⟨τί ἂν⟩ τῇ ἀληθείᾳ αἴσχιον καὶ κάκιον εἴη σωφροσύνης καὶ δικαιοσύνης τούτοις τοῖς ἀνθρώποις, οἷς ἐξὸν ἀπολαύειν τῶν ἀγαθῶν καὶ μηδενὸς ἐμποδὼν ὄντος, αὐτοὶ ἑαυτοῖς δεσπότην ἐπαγάγοιντο τὸν τῶν πολλῶν ἀνθρώπων νόμον τε καὶ λόγον καὶ ψόγον; ἢ πῶς οὐκ ἂν ἄθλιοι γεγονότες","st":"492b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> εἶεν ὑπὸ τοῦ καλοῦ τοῦ τῆς δικαιοσύνης καὶ τῆς σωφροσύνης, μηδὲν πλέον νέμοντες τοῖς φίλοις τοῖς αὑτῶν ἢ τοῖς ἐχθροῖς, καὶ ταῦτα ἄρχοντες ἐν τῇ ἑαυτῶν πόλει; ἀλλὰ τῇ ἀληθείᾳ, ὦ Σώκρατες, ἣν φῂς σὺ διώκειν, ὧδ’ ἔχει: τρυφὴ καὶ ἀκολασία καὶ ἐλευθερία, ἐὰν ἐπικουρίαν ἔχῃ, τοῦτ’ ἐστὶν ἀρετή τε καὶ εὐδαιμονία, τὰ δὲ ἄλλα ταῦτ’ ἐστὶν τὰ καλλωπίσματα, τὰ παρὰ φύσιν συνθήματα ἀνθρώπων, φλυαρία καὶ οὐδενὸς ἄξια.","st":"492c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἀγεννῶς γε, ὦ Καλλίκλεις, ἐπεξέρχῃ τῷ λόγῳ παρρησιαζόμενος: σαφῶς γὰρ σὺ νῦν λέγεις ἃ οἱ ἄλλοι διανοοῦνται μέν, λέγειν δὲ οὐκ ἐθέλουσιν. δέομαι οὖν ἐγώ σου μηδενὶ τρόπῳ ἀνεῖναι, ἵνα τῷ ὄντι κατάδηλον γένηται πῶς βιωτέον. καί μοι λέγε: τὰς μὲν ἐπιθυμίας φῂς οὐ κολαστέον, εἰ μέλλει τις οἷον δεῖ εἶναι, ἐῶντα δὲ αὐτὰς ὡς μεγίστας πλήρωσιν αὐταῖς ἁμόθεν γέ ποθεν ἑτοιμάζειν, καὶ","st":"492d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο εἶναι τὴν ἀρετήν;","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημὶ ταῦτα ἐγώ.","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα ὀρθῶς λέγονται οἱ μηδενὸς δεόμενοι εὐδαίμονες εἶναι.","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οἱ λίθοι γὰρ ἂν οὕτω γε καὶ οἱ νεκροὶ εὐδαιμονέστατοι εἶεν.","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὲν δὴ καὶ ὥς γε σὺ λέγεις δεινὸς ὁ βίος. οὐ γάρ τοι θαυμάζοιμ’ ἂν εἰ Εὐριπίδης ἀληθῆ ἐν τοῖσδε λέγει, λέγων —","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς δ’ οἶδεν, εἰ τὸ ζῆν μέν ἐστι κατθανεῖν,","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ κατθανεῖν δὲ ζῆν; . . .","st":"492e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἡμεῖς τῷ ὄντι ἴσως τέθναμεν: ἤδη γάρ του ἔγωγε καὶ ἤκουσα τῶν σοφῶν ὡς νῦν ἡμεῖς τέθναμεν καὶ τὸ μὲν σῶμά ἐστιν ἡμῖν σῆμα, τῆς δὲ ψυχῆς τοῦτο ἐν ᾧ ἐπιθυμίαι εἰσὶ τυγχάνει ὂν οἷον ἀναπείθεσθαι καὶ μεταπίπτειν ἄνω κάτω, καὶ τοῦτο ἄρα τις μυθολογῶν κομψὸς ἀνήρ, ἴσως Σικελός τις ἢ Ἰταλικός, παράγων τῷ ὀνόματι διὰ τὸ πιθανόν τε καὶ πειστικὸν ὠνόμασε πίθον, τοὺς δὲ ἀνοήτους ἀμυήτους,","st":"493a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν δ’ ἀνοήτων τοῦτο τῆς ψυχῆς οὗ αἱ ἐπιθυμίαι εἰσί, τὸ ἀκόλαστον αὐτοῦ καὶ οὐ στεγανόν, ὡς τετρημένος εἴη πίθος, διὰ τὴν ἀπληστίαν ἀπεικάσας. τοὐναντίον δὴ οὗτος σοί, ὦ Καλλίκλεις, ἐνδείκνυται ὡς τῶν ἐν Ἅιδου — τὸ ἀιδὲς δὴ λέγων — οὗτοι ἀθλιώτατοι ἂν εἶεν, οἱ ἀμύητοι, καὶ φοροῖεν εἰς τὸν τετρημένον πίθον ὕδωρ ἑτέρῳ τοιούτῳ τετρημένῳ κοσκίνῳ. τὸ δὲ κόσκινον ἄρα λέγει, ὡς ἔφη ὁ πρὸς ἐμὲ","st":"493b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγων, τὴν ψυχὴν εἶναι: τὴν δὲ ψυχὴν κοσκίνῳ ἀπῄκασεν τὴν τῶν ἀνοήτων ὡς τετρημένην, ἅτε οὐ δυναμένην στέγειν δι’ ἀπιστίαν τε καὶ λήθην. ταῦτ’ ἐπιεικῶς μέν ἐστιν ὑπό τι ἄτοπα, δηλοῖ μὴν ὃ ἐγὼ βούλομαί σοι ἐνδειξάμενος, ἐάν πως οἷός τε ὦ, πεῖσαι μεταθέσθαι, ἀντὶ τοῦ ἀπλήστως καὶ ἀκολάστως ἔχοντος βίου τὸν κοσμίως καὶ τοῖς ἀεὶ παροῦσιν ἱκανῶς καὶ ἐξαρκούντως ἔχοντα βίον ἑλέσθαι. ἀλλὰ πότερον","st":"493c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πείθω τί σε καὶ μετατίθεσθαι εὐδαιμονεστέρους εἶναι τοὺς κοσμίους τῶν ἀκολάστων, ἢ οὐδ’ ἂν ἄλλα πολλὰ τοιαῦτα μυθολογῶ, οὐδέν τι μᾶλλον μεταθήσῃ;","st":"493d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τοῦτ’ ἀληθέστερον εἴρηκας, ὦ Σώκρατες.","st":"493d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, ἄλλην σοι εἰκόνα λέγω ἐκ τοῦ αὐτοῦ γυμνασίου τῇ νῦν. σκόπει γὰρ εἰ τοιόνδε λέγεις περὶ τοῦ βίου ἑκατέρου, τοῦ τε σώφρονος καὶ τοῦ ἀκολάστου, οἷον εἰ δυοῖν ἀνδροῖν ἑκατέρῳ πίθοι πολλοὶ εἶεν καὶ τῷ μὲν","st":"493d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἑτέρῳ ὑγιεῖς καὶ πλήρεις, ὁ μὲν οἴνου, ὁ δὲ μέλιτος, ὁ δὲ γάλακτος, καὶ ἄλλοι πολλοὶ πολλῶν, νάματα δὲ σπάνια καὶ χαλεπὰ ἑκάστου τούτων εἴη καὶ μετὰ πολλῶν πόνων καὶ χαλεπῶν ἐκποριζόμενα: ὁ μὲν οὖν ἕτερος πληρωσάμενος μήτ’ ἐποχετεύοι μήτε τι φροντίζοι, ἀλλ’ ἕνεκα τούτων ἡσυχίαν ἔχοι: τῷ δ’ ἑτέρῳ τὰ μὲν νάματα, ὥσπερ καὶ ἐκείνῳ, δυνατὰ μὲν πορίζεσθαι, χαλεπὰ δέ, τὰ δ’ ἀγγεῖα τετρημένα καὶ σαθρά, ἀναγκάζοιτο δ’ ἀεὶ καὶ νύκτα καὶ","st":"493e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμέραν πιμπλάναι αὐτά, ἢ τὰς ἐσχάτας λυποῖτο λύπας: ἆρα τοιούτου ἑκατέρου ὄντος τοῦ βίου, λέγεις τὸν τοῦ ἀκολάστου εὐδαιμονέστερον εἶναι ἢ τὸν τοῦ κοσμίου; πείθω τί σε ταῦτα λέγων συγχωρῆσαι τὸν κόσμιον βίον τοῦ ἀκολάστου ἀμείνω εἶναι, ἢ οὐ πείθω;","st":"494a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐ πείθεις, ὦ Σώκρατες. τῷ μὲν γὰρ πληρωσαμένῳ ἐκείνῳ οὐκέτ’ ἔστιν ἡδονὴ οὐδεμία, ἀλλὰ τοῦτ’ ἔστιν, ὃ νυνδὴ ἐγὼ ἔλεγον, τὸ ὥσπερ λίθον ζῆν, ἐπειδὰν","st":"494a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πληρώσῃ, μήτε χαίροντα ἔτι μήτε λυπούμενον. ἀλλ’ ἐν τούτῳ ἐστὶν τὸ ἡδέως ζῆν, ἐν τῷ ὡς πλεῖστον ἐπιρρεῖν.","st":"494b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀνάγκη γ’, ἂν πολὺ ἐπιρρέῃ, πολὺ καὶ τὸ ἀπιὸν εἶναι, καὶ μεγάλ’ ἄττα τὰ τρήματα εἶναι ταῖς ἐκροαῖς;","st":"494b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ μὲν οὖν.","st":"494b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χαραδριοῦ τινα αὖ σὺ βίον λέγεις, ἀλλ’ οὐ νεκροῦ οὐδὲ λίθου. καί μοι λέγε: τὸ τοιόνδε λέγεις οἷον πεινῆν καὶ πεινῶντα ἐσθίειν;","st":"494b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"494b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ διψῆν γε καὶ διψῶντα πίνειν;","st":"494c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγω, καὶ τὰς ἄλλας ἐπιθυμίας ἁπάσας ἔχοντα καὶ δυνάμενον πληροῦντα χαίροντα εὐδαιμόνως ζῆν.","st":"494c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὖγε, ὦ βέλτιστε: διατέλει γὰρ ὥσπερ ἤρξω, καὶ ὅπως μὴ ἀπαισχυνῇ. δεῖ δέ, ὡς ἔοικε, μηδ’ ἐμὲ ἀπαισχυνθῆναι. καὶ πρῶτον μὲν εἰπὲ εἰ καὶ ψωρῶντα καὶ κνησιῶντα, ἀφθόνως ἔχοντα τοῦ κνῆσθαι, κνώμενον διατελοῦντα τὸν βίον εὐδαιμόνως ἔστι ζῆν.","st":"494c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς ἄτοπος εἶ, ὦ Σώκρατες, καὶ ἀτεχνῶς δημηγόρος.","st":"494d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοιγάρτοι, ὦ Καλλίκλεις, Πῶλον μὲν καὶ Γοργίαν καὶ ἐξέπληξα καὶ αἰσχύνεσθαι ἐποίησα, σὺ δὲ οὐ μὴ ἐκπλαγῇς οὐδὲ μὴ αἰσχυνθῇς: ἀνδρεῖος γὰρ εἶ. ἀλλ’ ἀποκρίνου μόνον.","st":"494d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημὶ τοίνυν καὶ τὸν κνώμενον ἡδέως ἂν βιῶναι.","st":"494d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ ἡδέως, καὶ εὐδαιμόνως;","st":"494d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"494d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον εἰ τὴν κεφαλὴν μόνον κνησιῷ — ἢ ἔτι τί σε ἐρωτῶ; ὅρα, ὦ Καλλίκλεις, τί ἀποκρινῇ, ἐάν τίς σε τὰ ἐχόμενα τούτοις ἐφεξῆς ἅπαντα ἐρωτᾷ. καὶ τούτων τοιούτων ὄντων κεφάλαιον, ὁ τῶν κιναίδων βίος, οὗτος οὐ δεινὸς καὶ αἰσχρὸς καὶ ἄθλιος; ἢ τούτους τολμήσεις λέγειν εὐδαίμονας εἶναι, ἐὰν ἀφθόνως ἔχωσιν ὧν δέονται;","st":"494e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ αἰσχύνῃ εἰς τοιαῦτα ἄγων, ὦ Σώκρατες, τοὺς λόγους;","st":"494e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ γὰρ ἐγὼ ἄγω ἐνταῦθα, ὦ γενναῖε, ἢ ἐκεῖνος ὃς ἂν φῇ ἀνέδην οὕτω τοὺς χαίροντας, ὅπως ἂν χαίρωσιν,","st":"494e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐδαίμονας εἶναι, καὶ μὴ διορίζηται τῶν ἡδονῶν ὁποῖαι ἀγαθαὶ καὶ κακαί; ἀλλ’ ἔτι καὶ νῦν λέγε πότερον φῂς εἶναι τὸ αὐτὸ ἡδὺ καὶ ἀγαθόν, ἢ εἶναί τι τῶν ἡδέων ὃ οὐκ ἔστιν ἀγαθόν;","st":"495a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἵνα δή μοι μὴ ἀνομολογούμενος ᾖ ὁ λόγος, ἐὰν ἕτερον φήσω εἶναι, τὸ αὐτό φημι εἶναι.","st":"495a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διαφθείρεις, ὦ Καλλίκλεις, τοὺς πρώτους λόγους, καὶ οὐκ ἂν ἔτι μετ’ ἐμοῦ ἱκανῶς τὰ ὄντα ἐξετάζοις, εἴπερ παρὰ τὰ δοκοῦντα σαυτῷ ἐρεῖς.","st":"495a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> καὶ γὰρ σύ, ὦ Σώκρατες.","st":"495b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ τοίνυν ὀρθῶς ποιῶ οὔτ’ ἐγώ, εἴπερ ποιῶ τοῦτο, οὔτε σύ. ἀλλ’, ὦ μακάριε, ἄθρει μὴ οὐ τοῦτο ᾖ τὸ ἀγαθόν, τὸ πάντως χαίρειν: ταῦτά τε γὰρ τὰ νυνδὴ αἰνιχθέντα πολλὰ καὶ αἰσχρὰ φαίνεται συμβαίνοντα, εἰ τοῦτο οὕτως ἔχει, καὶ ἄλλα πολλά.","st":"495b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς σύ γε οἴει, ὦ Σώκρατες.","st":"495b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σὺ δὲ τῷ ὄντι, ὦ Καλλίκλεις, ταῦτα ἰσχυρίζῃ;","st":"495b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"495b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπιχειρῶμεν ἄρα τῷ λόγῳ ὡς σοῦ σπουδάζοντος;","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε σφόδρα.","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή μοι, ἐπειδὴ οὕτω δοκεῖ, διελοῦ τάδε: ἐπιστήμην που καλεῖς τι;","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ καὶ ἀνδρείαν νυνδὴ ἔλεγές τινα εἶναι μετὰ ἐπιστήμης;","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔλεγον γάρ.","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλο τι οὖν ὡς ἕτερον τὴν ἀνδρείαν τῆς ἐπιστήμης δύο ταῦτα ἔλεγες;","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> σφόδρα γε.","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἡδονὴν καὶ ἐπιστήμην ταὐτὸν ἢ ἕτερον;","st":"495c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἕτερον δήπου, ὦ σοφώτατε σύ.","st":"495d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ καὶ ἀνδρείαν ἑτέραν ἡδονῆς;","st":"495d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"495d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δὴ ὅπως μεμνησόμεθα ταῦτα, ὅτι Καλλικλῆς ἔφη Ἀχαρνεὺς ἡδὺ μὲν καὶ ἀγαθὸν ταὐτὸν εἶναι, ἐπιστήμην δὲ καὶ ἀνδρείαν καὶ ἀλλήλων καὶ τοῦ ἀγαθοῦ ἕτερον.","st":"495d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> Σωκράτης δέ γε ἡμῖν ὁ Ἀλωπεκῆθεν οὐχ ὁμολογεῖ ταῦτα. ἢ ὁμολογεῖ;","st":"495d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐχ ὁμολογεῖ: οἶμαι δέ γε οὐδὲ Καλλικλῆς, ὅταν αὐτὸς αὑτὸν θεάσηται ὀρθῶς. εἰπὲ γάρ μοι, τοὺς εὖ πράττοντας τοῖς κακῶς πράττουσιν οὐ τοὐναντίον ἡγῇ πάθος πεπονθέναι;","st":"495e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"495e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν, εἴπερ ἐναντία ἐστὶν ταῦτα ἀλλήλοις, ἀνάγκη περὶ αὐτῶν ἔχειν ὥσπερ περὶ ὑγιείας ἔχει καὶ νόσου; οὐ γὰρ ἅμα δήπου ὑγιαίνει τε καὶ νοσεῖ ὁ ἄνθρωπος, οὐδὲ ἅμα ἀπαλλάττεται ὑγιείας τε καὶ νόσου.","st":"495e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς λέγεις;","st":"495e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἷον περὶ ὅτου βούλει τοῦ σώματος ἀπολαβὼν","st":"495e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκόπει. νοσεῖ που ἄνθρωπος ὀφθαλμούς, ᾧ ὄνομα ὀφθαλμία;","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ δήπου καὶ ὑγιαίνει γε ἅμα τοὺς αὐτούς;","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐδ’ ὁπωστιοῦν.","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ ὅταν τῆς ὀφθαλμίας ἀπαλλάττηται; ἆρα τότε καὶ τῆς ὑγιείας ἀπαλλάττεται τῶν ὀφθαλμῶν καὶ τελευτῶν ἅμα ἀμφοτέρων ἀπήλλακται;","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἥκιστά γε.","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> θαυμάσιον γὰρ","st":"496a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶμαι καὶ ἄλογον γίγνεται: ἦ γάρ;","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> σφόδρα γε.","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐν μέρει οἶμαι ἑκάτερον καὶ λαμβάνει καὶ ἀπολλύει;","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἰσχὺν καὶ ἀσθένειαν ὡσαύτως;","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τάχος καὶ βραδυτῆτα;","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ καὶ τἀγαθὰ καὶ τὴν εὐδαιμονίαν καὶ τἀναντία τούτων, κακά τε καὶ ἀθλιότητα, ἐν μέρει λαμβάνει καὶ ἐν μέρει ἀπαλλάττεται ἑκατέρου;","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάντως δήπου.","st":"496b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐὰν εὕρωμεν ἄρα ἄττα ὧν ἅμα τε ἀπαλλάττεται ἄνθρωπος καὶ ἅμα ἔχει, δῆλον ὅτι ταῦτά γε οὐκ ἂν εἴη τό τε ἀγαθὸν καὶ τὸ κακόν. ὁμολογοῦμεν ταῦτα; καὶ εὖ μάλα σκεψάμενος ἀποκρίνου.","st":"496c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ὑπερφυῶς ὡς ὁμολογῶ.","st":"496c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δὴ ἐπὶ τὰ ἔμπροσθεν ὡμολογημένα. τὸ πεινῆν ἔλεγες πότερον ἡδὺ ἢ ἀνιαρὸν εἶναι; αὐτὸ λέγω τὸ πεινῆν.","st":"496c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀνιαρὸν ἔγωγε: τὸ μέντοι πεινῶντα ἐσθίειν ἡδὺ","st":"496c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγω.","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνω: ἀλλ’ οὖν τό γε πεινῆν αὐτὸ ἀνιαρόν. ἢ οὐχί;","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τὸ διψῆν;","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> σφόδρα γε.","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν ἔτι πλείω ἐρωτῶ, ἢ ὁμολογεῖς ἅπασαν ἔνδειαν καὶ ἐπιθυμίαν ἀνιαρὸν εἶναι;","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὁμολογῶ, ἀλλὰ μὴ ἐρώτα.","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: διψῶντα δὲ δὴ πίνειν ἄλλο τι ἢ ἡδὺ φῂς εἶναι;","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τούτου οὗ λέγεις τὸ μὲν διψῶντα λυπούμενον δήπου ἐστίν;","st":"496d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὲ πίνειν πλήρωσίς τε τῆς ἐνδείας καὶ ἡδονή;","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν κατὰ τὸ πίνειν χαίρειν λέγεις;","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> μάλιστα.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διψῶντά γε.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λυπούμενον;","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αἰσθάνῃ οὖν τὸ συμβαῖνον, ὅτι λυπούμενον χαίρειν λέγεις ἅμα, ὅταν διψῶντα πίνειν λέγῃς; ἢ οὐχ ἅμα τοῦτο γίγνεται κατὰ τὸν αὐτὸν τόπον καὶ χρόνον εἴτε ψυχῆς εἴτε σώματος βούλει; οὐδὲν γὰρ οἶμαι διαφέρει. ἔστι ταῦτα ἢ οὔ;","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστιν.","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν εὖ γε πράττοντα κακῶς","st":"496e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πράττειν ἅμα ἀδύνατον φῂς εἶναι.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημὶ γάρ.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνιώμενον δέ γε χαίρειν δυνατὸν ὡμολόγηκας.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φαίνεται.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα τὸ χαίρειν ἐστὶν εὖ πράττειν οὐδὲ τὸ ἀνιᾶσθαι κακῶς, ὥστε ἕτερον γίγνεται τὸ ἡδὺ τοῦ ἀγαθοῦ.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ οἶδ’ ἅττα σοφίζῃ, ὦ Σώκρατες.","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶσθα, ἀλλὰ ἀκκίζῃ, ὦ Καλλίκλεις: καὶ πρόιθί γε ἔτι εἰς τὸ ἔμπροσθεν, [ὅτι ἔχων ληρεῖς] ἵνα εἰδῇς ὡς σοφὸς","st":"497a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὤν με νουθετεῖς. οὐχ ἅμα διψῶν τε ἕκαστος ἡμῶν πέπαυται καὶ ἅμα ἡδόμενος διὰ τοῦ πίνειν;","st":"497b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ οἶδα ὅτι λέγεις.","st":"497b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> μηδαμῶς, ὦ Καλλίκλεις, ἀλλ’ ἀποκρίνου καὶ ἡμῶν ἕνεκα, ἵνα περανθῶσιν οἱ λόγοι.","st":"497b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ἀεὶ τοιοῦτός ἐστιν Σωκράτης, ὦ Γοργία: σμικρὰ καὶ ὀλίγου ἄξια ἀνερωτᾷ καὶ ἐξελέγχει.","st":"497b"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλὰ τί σοὶ διαφέρει; πάντως οὐ σὴ αὕτη ἡ τιμή, ὦ Καλλίκλεις: ἀλλ’ ὑπόσχες Σωκράτει ἐξελέγξαι ὅπως ἂν βούληται.","st":"497b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> Ἐρώτα δὴ σὺ τὰ σμικρά τε καὶ στενὰ ταῦτα, ἐπείπερ Γοργίᾳ δοκεῖ οὕτως.","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐδαίμων εἶ, ὦ Καλλίκλεις, ὅτι τὰ μεγάλα μεμύησαι πρὶν τὰ σμικρά: ἐγὼ δ’ οὐκ ᾤμην θεμιτὸν εἶναι. ὅθεν οὖν ἀπέλιπες ἀποκρίνου, εἰ οὐχ ἅμα παύεται διψῶν ἕκαστος ἡμῶν καὶ ἡδόμενος.","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ πεινῶν καὶ τῶν ἄλλων ἐπιθυμιῶν καὶ ἡδονῶν ἅμα παύεται;","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστι ταῦτα.","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τῶν λυπῶν","st":"497c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τῶν ἡδονῶν ἅμα παύεται;","st":"497d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"497d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν τῶν ἀγαθῶν γε καὶ κακῶν οὐχ ἅμα παύεται, ὡς σὺ ὡμολόγεις: νῦν δὲ οὐχ ὁμολογεῖς;","st":"497d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε: τί οὖν δή;","st":"497d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι οὐ τὰ αὐτὰ γίγνεται, ὦ φίλε, τἀγαθὰ τοῖς ἡδέσιν οὐδὲ τὰ κακὰ τοῖς ἀνιαροῖς. τῶν μὲν γὰρ ἅμα παύεται, τῶν δὲ οὔ, ὡς ἑτέρων ὄντων: πῶς οὖν ταὐτὰ ἂν εἴη τὰ ἡδέα τοῖς ἀγαθοῖς ἢ τὰ ἀνιαρὰ τοῖς κακοῖς; ἐὰν δὲ βούλῃ, καὶ τῇδε ἐπίσκεψαι (οἶμαι γάρ σοι οὐδὲ ταύτῃ","st":"497d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁμολογεῖσθαι: ἄθρει δέ᾽ τοὺς ἀγαθοὺς οὐχὶ ἀγαθῶν παρουσίᾳ ἀγαθοὺς καλεῖς, ὥσπερ τοὺς καλοὺς οἷς ἂν κάλλος παρῇ;","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἀγαθοὺς ἄνδρας καλεῖς ἄφρονας καὶ δειλούς; οὐ γὰρ ἄρτι γε, ἀλλὰ τοὺς ἀνδρείους καὶ φρονίμους ἔλεγες: ἢ οὐ τούτους ἀγαθοὺς καλεῖς;","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ μὲν οὖν.","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; παῖδα ἀνόητον χαίροντα ἤδη εἶδες;","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄνδρα δὲ οὔπω εἶδες ἀνόητον χαίροντα;","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οἶμαι ἔγωγε: ἀλλὰ τί τοῦτο;","st":"497e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέν: ἀλλ’ ἀποκρίνου.","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> εἶδον.","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; νοῦν ἔχοντα λυπούμενον καὶ χαίροντα;","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότεροι δὲ μᾶλλον χαίρουσι καὶ λυποῦνται, οἱ φρόνιμοι ἢ οἱ ἄφρονες;","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οἶμαι ἔγωγε οὐ πολύ τι διαφέρειν.","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἀρκεῖ καὶ τοῦτο. ἐν πολέμῳ δὲ ἤδη εἶδες ἄνδρα δειλόν;","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ἀπιόντων τῶν πολεμίων πότεροί σοι ἐδόκουν μᾶλλον χαίρειν, οἱ δειλοὶ ἢ οἱ ἀνδρεῖοι;","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀμφότεροι ἔμοιγε","st":"498a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> [μᾶλλον]: εἰ δὲ μή, παραπλησίως γε.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲν διαφέρει. χαίρουσιν δ’ οὖν καὶ οἱ δειλοί;","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> σφόδρα γε.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οἱ ἄφρονες, ὡς ἔοικεν.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προσιόντων δὲ οἱ δειλοὶ μόνον λυποῦνται ἢ καὶ οἱ ἀνδρεῖοι;","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀμφότεροι.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα ὁμοίως;","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> μᾶλλον ἴσως οἱ δειλοί.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀπιόντων δ’ οὐ μᾶλλον χαίρουσιν;","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἴσως.","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν λυποῦνται μὲν καὶ χαίρουσιν καὶ οἱ ἄφρονες καὶ οἱ φρόνιμοι καὶ οἱ δειλοὶ καὶ οἱ ἀνδρεῖοι παραπλησίως,","st":"498b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς σὺ φῄς, μᾶλλον δὲ οἱ δειλοὶ τῶν ἀνδρείων;","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν οἵ γε φρόνιμοι καὶ οἱ ἀνδρεῖοι ἀγαθοί, οἱ δὲ δειλοὶ καὶ ἄφρονες κακοί;","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παραπλησίως ἄρα χαίρουσιν καὶ λυποῦνται οἱ ἀγαθοὶ καὶ οἱ κακοί;","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν παραπλησίως εἰσὶν ἀγαθοὶ καὶ κακοὶ οἱ ἀγαθοί τε καὶ οἱ κακοί; ἢ καὶ ἔτι μᾶλλον ἀγαθοὶ [οἱ ἀγαθοὶ καὶ οἱ κακοί] εἰσιν οἱ κακοί;","st":"498c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ μὰ Δί’ οὐκ οἶδ’ ὅτι λέγεις.","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ οἶσθ’ ὅτι τοὺς ἀγαθοὺς ἀγαθῶν φῂς παρουσίᾳ εἶναι ἀγαθούς, καὶ κακοὺς δὲ κακῶν; τὰ δὲ ἀγαθὰ εἶναι τὰς ἡδονάς, κακὰ δὲ τὰς ἀνίας;","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τοῖς χαίρουσιν πάρεστιν τἀγαθά, αἱ ἡδοναί, εἴπερ χαίρουσιν;","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀγαθῶν παρόντων ἀγαθοί εἰσιν οἱ χαίροντες;","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; τοῖς ἀνιωμένοις οὐ πάρεστιν τὰ κακά, αἱ λῦπαι;","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάρεστιν.","st":"498d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακῶν δέ γε παρουσίᾳ φῂς σὺ εἶναι κακοὺς τοὺς κακούς: ἢ οὐκέτι φῄς;","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγαθοὶ ἄρα οἳ ἂν χαίρωσι, κακοὶ δὲ οἳ ἂν ἀνιῶνται;","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἳ μέν γε μᾶλλον μᾶλλον, οἳ δ’ ἧττον ἧττον, οἳ δὲ παραπλησίως παραπλησίως;","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν φῂς παραπλησίως χαίρειν καὶ λυπεῖσθαι τοὺς φρονίμους καὶ τοὺς ἄφρονας καὶ τοὺς δειλοὺς καὶ τοὺς ἀνδρείους, ἢ καὶ μᾶλλον ἔτι τοὺς δειλούς;","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> συλλόγισαι δὴ κοινῇ μετ’ ἐμοῦ τί ἡμῖν συμβαίνει ἐκ τῶν ὡμολογημένων: καὶ δὶς γάρ τοι καὶ τρίς φασιν καλὸν","st":"498e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι τὰ καλὰ λέγειν τε καὶ ἐπισκοπεῖσθαι. ἀγαθὸν μὲν εἶναι τὸν φρόνιμον καὶ ἀνδρεῖόν φαμεν. ἦ γάρ;","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸν δὲ τὸν ἄφρονα καὶ δειλόν;","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγαθὸν δὲ αὖ τὸν χαίροντα;","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸν δὲ τὸν ἀνιώμενον;","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀνάγκη.","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνιᾶσθαι δὲ καὶ χαίρειν τὸν ἀγαθὸν καὶ κακὸν ὁμοίως, ἴσως δὲ καὶ μᾶλλον τὸν κακόν;","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁμοίως γίγνεται κακὸς καὶ ἀγαθὸς τῷ ἀγαθῷ ἢ καὶ μᾶλλον","st":"499a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγαθὸς ὁ κακός; οὐ ταῦτα συμβαίνει καὶ τὰ πρότερα ἐκεῖνα, ἐάν τις ταὐτὰ φῇ ἡδέα τε καὶ ἀγαθὰ εἶναι; οὐ ταῦτα ἀνάγκη, ὦ Καλλίκλεις;","st":"499b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάλαι τοί σου ἀκροῶμαι, ὦ Σώκρατες, καθομολογῶν, ἐνθυμούμενος ὅτι, κἂν παίζων τίς σοι ἐνδῷ ὁτιοῦν, τούτου ἅσμενος ἔχῃ ὥσπερ τὰ μειράκια. ὡς δὴ σὺ οἴει ἐμὲ ἢ καὶ ἄλλον ὁντινοῦν ἀνθρώπων οὐχ ἡγεῖσθαι τὰς μὲν βελτίους ἡδονάς, τὰς δὲ χείρους.","st":"499b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἰοῦ ἰοῦ, ὦ Καλλίκλεις, ὡς πανοῦργος εἶ καί μοι","st":"499b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὥσπερ παιδὶ χρῇ, τοτὲ μὲν τὰ αὐτὰ φάσκων οὕτως ἔχειν, τοτὲ δὲ ἑτέρως, ἐξαπατῶν με. καίτοι οὐκ ᾤμην γε κατ’ ἀρχὰς ὑπὸ σοῦ ἑκόντος εἶναι ἐξαπατηθήσεσθαι, ὡς ὄντος φίλου: νῦν δὲ ἐψεύσθην, καὶ ὡς ἔοικεν ἀνάγκη μοι κατὰ τὸν παλαιὸν λόγον τὸ παρὸν εὖ ποιεῖν καὶ τοῦτο δέχεσθαι τὸ διδόμενον παρὰ σοῦ. ἔστιν δὲ δή, ὡς ἔοικεν, ὃ νῦν λέγεις, ὅτι ἡδοναί τινές εἰσιν αἱ μὲν ἀγαθαί, αἱ δὲ κακαί: ἦ γάρ;","st":"499c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν ἀγαθαὶ μὲν αἱ ὠφέλιμοι, κακαὶ δὲ αἱ βλαβεραί;","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὠφέλιμοι δέ γε αἱ ἀγαθόν τι ποιοῦσαι, κακαὶ δὲ αἱ κακόν τι;","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν τὰς τοιάσδε λέγεις, οἷον κατὰ τὸ σῶμα ἃς νυνδὴ ἐλέγομεν ἐν τῷ ἐσθίειν καὶ πίνειν ἡδονάς, ἦ ἄρα τούτων αἱ μὲν ὑγίειαν ποιοῦσαι ἐν τῷ σώματι, ἢ ἰσχὺν ἢ ἄλλην τινὰ ἀρετὴν τοῦ σώματος, αὗται μὲν ἀγαθαί, αἱ δὲ","st":"499d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τἀναντία τούτων κακαί;","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ λῦπαι ὡσαύτως αἱ μὲν χρησταί εἰσιν, αἱ δὲ πονηραί;","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰς μὲν χρηστὰς καὶ ἡδονὰς καὶ λύπας καὶ αἱρετέον ἐστὶν καὶ πρακτέον;","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς δὲ πονηρὰς οὔ;","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> δῆλον δή.","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕνεκα γάρ που τῶν ἀγαθῶν ἅπαντα ἡμῖν ἔδοξεν πρακτέον εἶναι, εἰ μνημονεύεις, ἐμοί τε καὶ Πώλῳ. ἆρα καὶ σοὶ συνδοκεῖ οὕτω, τέλος εἶναι ἁπασῶν τῶν πράξεων τὸ ἀγαθόν, καὶ ἐκείνου ἕνεκα δεῖν πάντα τἆλλα πράττεσθαι","st":"499e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὐκ ἐκεῖνο τῶν ἄλλων; σύμψηφος ἡμῖν εἶ καὶ σὺ ἐκ τρίτων;","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν ἀγαθῶν ἄρα ἕνεκα δεῖ καὶ τἆλλα καὶ τὰ ἡδέα πράττειν, ἀλλ’ οὐ τἀγαθὰ τῶν ἡδέων.","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν παντὸς ἀνδρός ἐστιν ἐκλέξασθαι ποῖα ἀγαθὰ τῶν ἡδέων ἐστὶν καὶ ὁποῖα κακά, ἢ τεχνικοῦ δεῖ εἰς ἕκαστον;","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τεχνικοῦ.","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀναμνησθῶμεν δὴ ὧν αὖ ἐγὼ πρὸς Πῶλον καὶ Γοργίαν ἐτύγχανον λέγων. ἔλεγον γὰρ αὖ, εἰ μνημονεύεις,","st":"500a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι εἶεν παρασκευαὶ αἱ μὲν μέχρι ἡδονῆς, αὐτὸ τοῦτο μόνον παρασκευάζουσαι, ἀγνοοῦσαι δὲ τὸ βέλτιον καὶ τὸ χεῖρον, αἱ δὲ γιγνώσκουσαι ὅτι τε ἀγαθὸν καὶ ὅτι κακόν: καὶ ἐτίθην τῶν μὲν περὶ τὰς ἡδονὰς τὴν μαγειρικὴν ἐμπειρίαν ἀλλὰ οὐ τέχνην, τῶν δὲ περὶ τὸ ἀγαθὸν τὴν ἰατρικὴν τέχνην. καὶ πρὸς Φιλίου, ὦ Καλλίκλεις, μήτε αὐτὸς οἴου δεῖν πρὸς ἐμὲ παίζειν μηδ’ ὅτι ἂν τύχῃς παρὰ τὰ δοκοῦντα ἀποκρίνου, μήτ’","st":"500b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὖ τὰ παρ’ ἐμοῦ οὕτως ἀποδέχου ὡς παίζοντος: ὁρᾷς γὰρ ὅτι περὶ τούτου ἡμῖν εἰσιν οἱ λόγοι, οὗ τί ἂν μᾶλλον σπουδάσειέ τις καὶ σμικρὸν νοῦν ἔχων ἄνθρωπος, ἢ τοῦτο, ὅντινα χρὴ τρόπον ζῆν, πότερον ἐπὶ ὃν σὺ παρακαλεῖς ἐμέ, τὰ τοῦ ἀνδρὸς δὴ ταῦτα πράττοντα, λέγοντά τε ἐν τῷ δήμῳ καὶ ῥητορικὴν ἀσκοῦντα καὶ πολιτευόμενον τοῦτον τὸν τρόπον ὃν ὑμεῖς νῦν πολιτεύεσθε, ἢ [ἐπὶ] τόνδε τὸν βίον τὸν ἐν φιλοσοφίᾳ, καὶ τί ποτ’ ἐστὶν οὗτος ἐκείνου διαφέρων. ἴσως","st":"500c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὖν βέλτιστόν ἐστιν, ὡς ἄρτι ἐγὼ ἐπεχείρησα, διαιρεῖσθαι, διελομένους δὲ καὶ ὁμολογήσαντας ἀλλήλοις, εἰ ἔστιν τούτω διττὼ τὼ βίω, σκέψασθαι τί τε διαφέρετον ἀλλήλοιν καὶ ὁπότερον βιωτέον αὐτοῖν. ἴσως οὖν οὔπω οἶσθα τί λέγω.","st":"500d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐ δῆτα.","st":"500d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ ἐγώ σοι σαφέστερον ἐρῶ. ἐπειδὴ ὡμολογήκαμεν ἐγώ τε καὶ σὺ εἶναι μέν τι ἀγαθόν, εἶναι δέ τι ἡδύ, ἕτερον δὲ τὸ ἡδὺ τοῦ ἀγαθοῦ, ἑκατέρου δὲ αὐτοῖν μελέτην τινὰ εἶναι καὶ παρασκευὴν τῆς κτήσεως, τὴν μὲν τοῦ ἡδέος θήραν, τὴν δὲ τοῦ ἀγαθοῦ — αὐτὸ δέ μοι τοῦτο πρῶτον ἢ","st":"500d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σύμφαθι ἢ μή. σύμφῃς;","st":"500e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὕτως φημί.","st":"500e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή, ἃ καὶ πρὸς τούσδε ἐγὼ ἔλεγον, διομολόγησαί μοι, εἰ ἄρα σοι ἔδοξα τότε ἀληθῆ λέγειν. ἔλεγον δέ που ὅτι ἡ μὲν ὀψοποιικὴ οὔ μοι δοκεῖ τέχνη εἶναι ἀλλ’ ἐμπειρία,","st":"500e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ δ’ ἰατρική, λέγων ὅτι ἡ μὲν τούτου οὗ θεραπεύει καὶ τὴν φύσιν ἔσκεπται καὶ τὴν αἰτίαν ὧν πράττει, καὶ λόγον ἔχει τούτων ἑκάστου δοῦναι, ἡ ἰατρική: ἡ δ’ ἑτέρα τῆς ἡδονῆς, πρὸς ἣν ἡ θεραπεία αὐτῇ ἐστιν ἅπασα, κομιδῇ ἀτέχνως ἐπ’ αὐτὴν ἔρχεται, οὔτε τι τὴν φύσιν σκεψαμένη τῆς ἡδονῆς οὔτε τὴν αἰτίαν, ἀλόγως τε παντάπασιν ὡς ἔπος εἰπεῖν οὐδὲν διαριθμησαμένη, τριβῇ καὶ ἐμπειρίᾳ μνήμην μόνον σῳζομένη","st":"501a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ εἰωθότος γίγνεσθαι, ᾧ δὴ καὶ πορίζεται τὰς ἡδονάς. ταῦτ’ οὖν πρῶτον σκόπει εἰ δοκεῖ σοι ἱκανῶς λέγεσθαι, καὶ εἶναί τινες καὶ περὶ ψυχὴν τοιαῦται ἄλλαι πραγματεῖαι, αἱ μὲν τεχνικαί, προμήθειάν τινα ἔχουσαι τοῦ βελτίστου περὶ τὴν ψυχήν, αἱ δὲ τούτου μὲν ὀλιγωροῦσαι, ἐσκεμμέναι δ’ αὖ, ὥσπερ ἐκεῖ, τὴν ἡδονὴν μόνον τῆς ψυχῆς, τίνα ἂν αὐτῇ τρόπον γίγνοιτο, ἥτις δὲ ἢ βελτίων ἢ χείρων τῶν ἡδονῶν, οὔτε σκοπούμεναι οὔτε μέλον αὐταῖς ἄλλο ἢ χαρίζεσθαι","st":"501b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μόνον, εἴτε βέλτιον εἴτε χεῖρον. ἐμοὶ μὲν γάρ, ὦ Καλλίκλεις, δοκοῦσίν τε εἶναι, καὶ ἔγωγέ φημι τὸ τοιοῦτον κολακείαν εἶναι καὶ περὶ σῶμα καὶ περὶ ψυχὴν καὶ περὶ ἄλλο ὅτου ἄν τις τὴν ἡδονὴν θεραπεύῃ, ἀσκέπτως ἔχων τοῦ ἀμείνονός τε καὶ τοῦ χείρονος: σὺ δὲ δὴ πότερον συγκατατίθεσαι ἡμῖν περὶ τούτων τὴν αὐτὴν δόξαν ἢ ἀντίφῃς;","st":"501c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ ἔγωγε, ἀλλὰ συγχωρῶ, ἵνα σοι καὶ περανθῇ ὁ λόγος καὶ Γοργίᾳ τῷδε χαρίσωμαι.","st":"501c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον δὲ περὶ μὲν μίαν ψυχὴν ἔστιν τοῦτο, περὶ δὲ δύο καὶ πολλὰς οὐκ ἔστιν;","st":"501d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὔκ, ἀλλὰ καὶ περὶ δύο καὶ περὶ πολλάς.","st":"501d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἁθρόαις ἅμα χαρίζεσθαι ἔστι, μηδὲν σκοπούμενον τὸ βέλτιστον;","st":"501d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οἶμαι ἔγωγε.","st":"501d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχεις οὖν εἰπεῖν αἵτινές εἰσιν αἱ ἐπιτηδεύσεις αἱ τοῦτο ποιοῦσαι; μᾶλλον δέ, εἰ βούλει, ἐμοῦ ἐρωτῶντος, ἣ μὲν ἄν σοι δοκῇ τούτων εἶναι, φάθι, ἣ δ’ ἂν μή, μὴ φάθι.","st":"501d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον δὲ σκεψώμεθα τὴν αὐλητικήν. οὐ δοκεῖ σοι τοιαύτη τις εἶναι, ὦ Καλλίκλεις, τὴν ἡδονὴν ἡμῶν μόνον διώκειν, ἄλλο δ’ οὐδὲν φροντίζειν;","st":"501e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε δοκεῖ.","st":"501e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ αἱ τοιαίδε ἅπασαι, οἷον ἡ κιθαριστικὴ ἡ ἐν τοῖς ἀγῶσιν;","st":"501e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"501e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ ἡ τῶν χορῶν διδασκαλία καὶ ἡ τῶν διθυράμβων ποίησις; οὐ τοιαύτη τίς σοι καταφαίνεται; ἢ ἡγῇ τι φροντίζειν Κινησίαν τὸν Μέλητος, ὅπως ἐρεῖ τι τοιοῦτον ὅθεν ἂν οἱ ἀκούοντες βελτίους γίγνοιντο, ἢ ὅτι μέλλει","st":"501e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χαριεῖσθαι τῷ ὄχλῳ τῶν θεατῶν;","st":"502a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> δῆλον δὴ τοῦτό γε, ὦ Σώκρατες, Κινησίου γε πέρι.","st":"502a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ ὁ πατὴρ αὐτοῦ Μέλης; ἦ πρὸς τὸ βέλτιστον βλέπων ἐδόκει σοι κιθαρῳδεῖν; ἢ ἐκεῖνος μὲν οὐδὲ πρὸς τὸ ἥδιστον; ἠνία γὰρ ᾄδων τοὺς θεατάς. ἀλλὰ δὴ σκόπει: οὐχὶ ἥ τε κιθαρῳδικὴ δοκεῖ σοι πᾶσα καὶ ἡ τῶν διθυράμβων ποίησις ἡδονῆς χάριν ηὑρῆσθαι;","st":"502a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε.","st":"502a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ δὴ ἡ σεμνὴ αὕτη καὶ θαυμαστή, ἡ τῆς τραγῳδίας ποίησις, ἐφ’ ᾧ ἐσπούδακεν; πότερόν ἐστιν αὐτῆς τὸ ἐπιχείρημα καὶ ἡ σπουδή, ὡς σοὶ δοκεῖ, χαρίζεσθαι τοῖς θεαταῖς μόνον, ἢ καὶ διαμάχεσθαι, ἐάν τι αὐτοῖς ἡδὺ μὲν ᾖ καὶ κεχαρισμένον, πονηρὸν δέ, ὅπως τοῦτο μὲν μὴ ἐρεῖ, εἰ δέ τι τυγχάνει ἀηδὲς καὶ ὠφέλιμον, τοῦτο δὲ καὶ λέξει καὶ ᾄσεται, ἐάντε χαίρωσιν ἐάντε μή; ποτέρως σοι δοκεῖ παρεσκευάσθαι ἡ τῶν τραγῳδιῶν ποίησις;","st":"502b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> δῆλον δὴ τοῦτό γε, ὦ Σώκρατες, ὅτι πρὸς τὴν","st":"502b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἡδονὴν μᾶλλον ὥρμηται καὶ τὸ χαρίζεσθαι τοῖς θεαταῖς.","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ τοιοῦτον, ὦ Καλλίκλεις, ἔφαμεν νυνδὴ κολακείαν εἶναι;","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, εἴ τις περιέλοι τῆς ποιήσεως πάσης τό τε μέλος καὶ τὸν ῥυθμὸν καὶ τὸ μέτρον, ἄλλο τι ἢ λόγοι γίγνονται τὸ λειπόμενον;","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀνάγκη.","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν πρὸς πολὺν ὄχλον καὶ δῆμον οὗτοι λέγονται οἱ λόγοι;","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δημηγορία ἄρα τίς ἐστιν ἡ ποιητική.","st":"502c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φαίνεται.","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ῥητορικὴ δημηγορία ἂν εἴη: ἢ οὐ ῥητορεύειν δοκοῦσί σοι οἱ ποιηταὶ ἐν τοῖς θεάτροις;","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε.","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν ἄρα ἡμεῖς ηὑρήκαμεν ῥητορικήν τινα πρὸς δῆμον τοιοῦτον οἷον παίδων τε ὁμοῦ καὶ γυναικῶν καὶ ἀνδρῶν, καὶ δούλων καὶ ἐλευθέρων, ἣν οὐ πάνυ ἀγάμεθα: κολακικὴν γὰρ αὐτήν φαμεν εἶναι.","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: τί δὲ ἡ πρὸς τὸν Ἀθηναίων δῆμον ῥητορικὴ","st":"502d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τοὺς ἄλλους τοὺς ἐν ταῖς πόλεσιν δήμους τοὺς τῶν ἐλευθέρων ἀνδρῶν, τί ποτε ἡμῖν αὕτη ἐστίν; πότερόν σοι δοκοῦσιν πρὸς τὸ βέλτιστον ἀεὶ λέγειν οἱ ῥήτορες, τούτου στοχαζόμενοι, ὅπως οἱ πολῖται ὡς βέλτιστοι ἔσονται διὰ τοὺς αὑτῶν λόγους, ἢ καὶ οὗτοι πρὸς τὸ χαρίζεσθαι τοῖς πολίταις ὡρμημένοι, καὶ ἕνεκα τοῦ ἰδίου τοῦ αὑτῶν ὀλιγωροῦντες τοῦ κοινοῦ, ὥσπερ παισὶ προσομιλοῦσι τοῖς δήμοις, χαρίζεσθαι αὐτοῖς πειρώμενοι μόνον, εἰ δέ γε βελτίους ἔσονται ἢ χείρους","st":"502e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ ταῦτα, οὐδὲν φροντίζουσιν;","st":"503a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐχ ἁπλοῦν ἔτι τοῦτο ἐρωτᾷς: εἰσὶ μὲν γὰρ οἳ κηδόμενοι τῶν πολιτῶν λέγουσιν ἃ λέγουσιν, εἰσὶν δὲ καὶ οἵους σὺ λέγεις.","st":"503a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐξαρκεῖ. εἰ γὰρ καὶ τοῦτό ἐστι διπλοῦν, τὸ μὲν ἕτερόν που τούτου κολακεία ἂν εἴη καὶ αἰσχρὰ δημηγορία, τὸ δ’ ἕτερον καλόν, τὸ παρασκευάζειν ὅπως ὡς βέλτισται ἔσονται τῶν πολιτῶν αἱ ψυχαί, καὶ διαμάχεσθαι λέγοντα τὰ βέλτιστα, εἴτε ἡδίω εἴτε ἀηδέστερα ἔσται τοῖς ἀκούουσιν.","st":"503a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὐ πώποτε σὺ ταύτην εἶδες τὴν ῥητορικήν: ἢ εἴ τινα ἔχεις τῶν ῥητόρων τοιοῦτον εἰπεῖν, τί οὐχὶ καὶ ἐμοὶ αὐτὸν ἔφρασας τίς ἐστιν;","st":"503b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ μὰ Δία οὐκ ἔχω ἔγωγέ σοι εἰπεῖν τῶν γε νῦν ῥητόρων οὐδένα.","st":"503b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; τῶν παλαιῶν ἔχεις τινὰ εἰπεῖν δι’ ὅντινα αἰτίαν ἔχουσιν Ἀθηναῖοι βελτίους γεγονέναι, ἐπειδὴ ἐκεῖνος ἤρξατο δημηγορεῖν, ἐν τῷ πρόσθεν χρόνῳ χείρους ὄντες; ἐγὼ μὲν γὰρ οὐκ οἶδα τίς ἐστιν οὗτος.","st":"503b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί δέ; Θεμιστοκλέα οὐκ ἀκούεις ἄνδρα ἀγαθὸν γεγονότα καὶ Κίμωνα καὶ Μιλτιάδην καὶ Περικλέα τουτονὶ τὸν νεωστὶ τετελευτηκότα, οὗ καὶ σὺ ἀκήκοας;","st":"503c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ ἔστιν γε, ὦ Καλλίκλεις, ἣν πρότερον σὺ ἔλεγες ἀρετήν, ἀληθής, τὸ τὰς ἐπιθυμίας ἀποπιμπλάναι καὶ τὰς αὑτοῦ καὶ τὰς τῶν ἄλλων: εἰ δὲ μὴ τοῦτο, ἀλλ’ ὅπερ ἐν τῷ ὑστέρῳ λόγῳ ἠναγκάσθημεν ἡμεῖς ὁμολογεῖν — ὅτι αἳ μὲν τῶν ἐπιθυμιῶν πληρούμεναι βελτίω ποιοῦσι τὸν ἄνθρωπον,","st":"503c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτας μὲν ἀποτελεῖν, αἳ δὲ χείρω, μή, τοῦτο δὲ τέχνη τις εἴη — τοιοῦτον ἄνδρα τούτων τινὰ [γεγονέναι] οὐκ ἔχω ἔγωγε πῶς εἴπω.","st":"503d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ἐὰν ζητῇς καλῶς, εὑρήσεις.","st":"503d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴδωμεν δὴ οὑτωσὶ ἀτρέμα σκοπούμενοι εἴ τις τούτων τοιοῦτος γέγονεν: φέρε γάρ, ὁ ἀγαθὸς ἀνὴρ καὶ ἐπὶ τὸ βέλτιστον λέγων, ἃ ἂν λέγῃ ἄλλο τι οὐκ εἰκῇ ἐρεῖ, ἀλλ’","st":"503d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀποβλέπων πρός τι; ὥσπερ καὶ οἱ ἄλλοι πάντες δημιουργοὶ [βλέποντες] πρὸς τὸ αὑτῶν ἔργον ἕκαστος οὐκ εἰκῇ ἐκλεγόμενος προσφέρει [πρὸς τὸ ἔργον τὸ αὑτῶν,] ἀλλ’ ὅπως ἂν εἶδός τι αὐτῷ σχῇ τοῦτο ὃ ἐργάζεται. οἷον εἰ βούλει ἰδεῖν τοὺς ζωγράφους, τοὺς οἰκοδόμους, τοὺς ναυπηγούς, τοὺς ἄλλους πάντας δημιουργούς, ὅντινα βούλει αὐτῶν, ὡς εἰς τάξιν τινὰ ἕκαστος ἕκαστον τίθησιν ὃ ἂν τιθῇ, καὶ προσαναγκάζει τὸ ἕτερον τῷ ἑτέρῳ πρέπον τε εἶναι καὶ ἁρμόττειν, ἕως ἂν τὸ","st":"503e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἅπαν συστήσηται τεταγμένον τε καὶ κεκοσμημένον πρᾶγμα: καὶ οἵ τε δὴ ἄλλοι δημιουργοὶ καὶ οὓς νυνδὴ ἐλέγομεν, οἱ περὶ τὸ σῶμα, παιδοτρίβαι τε καὶ ἰατροί, κοσμοῦσί που τὸ σῶμα καὶ συντάττουσιν. ὁμολογοῦμεν οὕτω τοῦτ’ ἔχειν ἢ οὔ;","st":"504a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω τοῦτο οὕτω.","st":"504a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τάξεως ἄρα καὶ κόσμου τυχοῦσα οἰκία χρηστὴ ἂν εἴη, ἀταξίας δὲ μοχθηρά;","st":"504a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"504a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ πλοῖον ὡσαύτως;","st":"504a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ τὰ σώματά φαμεν τὰ ἡμέτερα;","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ’ ἡ ψυχή; ἀταξίας τυχοῦσα ἔσται χρηστή, ἢ τάξεώς τε καὶ κόσμου τινός;","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀνάγκη ἐκ τῶν πρόσθεν καὶ τοῦτο συνομολογεῖν.","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν ὄνομά ἐστιν ἐν τῷ σώματι τῷ ἐκ τῆς τάξεώς τε καὶ τοῦ κόσμου γιγνομένῳ;","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> Ὑγίειαν καὶ ἰσχὺν ἴσως λέγεις.","st":"504b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔγωγε. τί δὲ αὖ τῷ ἐν τῇ ψυχῇ ἐγγιγνομένῳ ἐκ τῆς τάξεως καὶ τοῦ κόσμου; πειρῶ εὑρεῖν καὶ εἰπεῖν ὥσπερ ἐκεῖ τὸ ὄνομα.","st":"504c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί δὲ οὐκ αὐτὸς λέγεις, ὦ Σώκρατες;","st":"504c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ εἴ σοι ἥδιόν ἐστιν, ἐγὼ ἐρῶ: σὺ δέ, ἂν μέν σοι δοκῶ ἐγὼ καλῶς λέγειν, φάθι, εἰ δὲ μή, ἔλεγχε καὶ μὴ ἐπίτρεπε. ἐμοὶ γὰρ δοκεῖ ταῖς μὲν τοῦ σώματος τάξεσιν ὄνομα εἶναι ὑγιεινόν, ἐξ οὗ ἐν αὐτῷ ἡ ὑγίεια γίγνεται καὶ ἡ ἄλλη ἀρετὴ τοῦ σώματος. ἔστιν ταῦτα ἢ οὐκ ἔστιν;","st":"504c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστιν.","st":"504c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῖς δέ γε τῆς ψυχῆς τάξεσι καὶ κοσμήσεσιν νόμιμόν τε καὶ νόμος, ὅθεν καὶ νόμιμοι γίγνονται καὶ κόσμιοι: ταῦτα δ’ ἔστιν δικαιοσύνη τε καὶ σωφροσύνη. φῂς ἢ οὔ;","st":"504d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω.","st":"504d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν πρὸς ταῦτα βλέπων ὁ ῥήτωρ ἐκεῖνος, ὁ τεχνικός τε καὶ ἀγαθός, καὶ τοὺς λόγους προσοίσει ταῖς ψυχαῖς οὓς ἂν λέγῃ, καὶ τὰς πράξεις ἁπάσας, καὶ δῶρον ἐάν τι διδῷ, δώσει, καὶ ἐάν τι ἀφαιρῆται, ἀφαιρήσεται, πρὸς τοῦτο ἀεὶ τὸν νοῦν ἔχων, ὅπως ἂν αὐτοῦ τοῖς πολίταις","st":"504d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δικαιοσύνη μὲν ἐν ταῖς ψυχαῖς γίγνηται, ἀδικία δὲ ἀπαλλάττηται, καὶ σωφροσύνη μὲν ἐγγίγνηται, ἀκολασία δὲ ἀπαλλάττηται, καὶ ἡ ἄλλη ἀρετὴ ἐγγίγνηται, κακία δὲ ἀπίῃ. συγχωρεῖς ἢ οὔ;","st":"504e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> συγχωρῶ.","st":"504e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί γὰρ ὄφελος, ὦ Καλλίκλεις, σώματί γε κάμνοντι καὶ μοχθηρῶς διακειμένῳ σιτία πολλὰ διδόναι καὶ τὰ ἥδιστα ἢ ποτὰ ἢ ἄλλ’ ὁτιοῦν, ὃ μὴ ὀνήσει αὐτὸ ἔσθ’ ὅτι πλέον ἢ τοὐναντίον κατά γε τὸν δίκαιον λόγον καὶ ἔλαττον; ἔστι ταῦτα;","st":"504e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω.","st":"505a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ οἶμαι λυσιτελεῖ μετὰ μοχθηρίας σώματος ζῆν ἀνθρώπῳ: ἀνάγκη γὰρ οὕτω καὶ ζῆν μοχθηρῶς. ἢ οὐχ οὕτως;","st":"505a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"505a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τὰς ἐπιθυμίας ἀποπιμπλάναι, οἷον πεινῶντα φαγεῖν ὅσον βούλεται ἢ διψῶντα πιεῖν, ὑγιαίνοντα μὲν ἐῶσιν οἱ ἰατροὶ ὡς τὰ πολλά, κάμνοντα δὲ ὡς ἔπος εἰπεῖν οὐδέποτ’ ἐῶσιν ἐμπίμπλασθαι ὧν ἐπιθυμεῖ; συγχωρεῖς τοῦτό γε καὶ σύ;","st":"505a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε.","st":"505a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ δὲ ψυχήν, ὦ ἄριστε, οὐχ ὁ αὐτὸς τρόπος; ἕως μὲν ἂν πονηρὰ ᾖ, ἀνόητός τε οὖσα καὶ ἀκόλαστος καὶ ἄδικος καὶ ἀνόσιος, εἴργειν αὐτὴν δεῖ τῶν ἐπιθυμιῶν καὶ μὴ ἐπιτρέπειν ἄλλ’ ἄττα ποιεῖν ἢ ἀφ’ ὧν βελτίων ἔσται: φῂς ἢ οὔ;","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὕτω γάρ που αὐτῇ ἄμεινον τῇ ψυχῇ;","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ εἴργειν ἐστὶν ἀφ’ ὧν ἐπιθυμεῖ κολάζειν;","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ κολάζεσθαι ἄρα τῇ ψυχῇ ἄμεινόν ἐστιν ἢ ἡ ἀκολασία, ὥσπερ σὺ νυνδὴ ᾤου.","st":"505b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ οἶδ’ ἅττα λέγεις, ὦ Σώκρατες, ἀλλ’ ἄλλον τινὰ ἐρώτα.","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὗτος ἀνὴρ οὐχ ὑπομένει ὠφελούμενος καὶ αὐτὸς τοῦτο πάσχων περὶ οὗ ὁ λόγος ἐστί, κολαζόμενος.","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐδέ γέ μοι μέλει οὐδὲν ὧν σὺ λέγεις, καὶ ταῦτά σοι Γοργίου χάριν ἀπεκρινάμην.","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: τί οὖν δὴ ποιήσομεν; μεταξὺ τὸν λόγον καταλύομεν;","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> αὐτὸς γνώσῃ.","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὐδὲ τοὺς μύθους φασὶ μεταξὺ θέμις εἶναι","st":"505c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καταλείπειν, ἀλλ’ ἐπιθέντας κεφαλήν, ἵνα μὴ ἄνευ κεφαλῆς περιίῃ. ἀπόκριναι οὖν καὶ τὰ λοιπά, ἵνα ἡμῖν ὁ λόγος κεφαλὴν λάβῃ.","st":"505d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὡς βίαιος εἶ, ὦ Σώκρατες. ἐὰν δὲ ἐμοὶ πείθῃ, ἐάσεις χαίρειν τοῦτον τὸν λόγον, ἢ καὶ ἄλλῳ τῳ διαλέξῃ.","st":"505d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν ἄλλος ἐθέλει; μὴ γάρ τοι ἀτελῆ γε τὸν λόγον καταλίπωμεν.","st":"505d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> αὐτὸς δὲ οὐκ ἂν δύναιο διελθεῖν τὸν λόγον, ἢ λέγων κατὰ σαυτὸν ἢ ἀποκρινόμενος σαυτῷ;","st":"505d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἵνα μοι τὸ τοῦ Ἐπιχάρμου γένηται, ἃ “πρὸ τοῦ δύο ἄνδρες ἔλεγον,” εἷς ὢν ἱκανὸς γένωμαι. ἀτὰρ κινδυνεύει ἀναγκαιότατον εἶναι οὕτως. εἰ μέντοι ποιήσομεν, οἶμαι ἔγωγε χρῆναι πάντας ἡμᾶς φιλονίκως ἔχειν πρὸς τὸ εἰδέναι τὸ ἀληθὲς τί ἐστιν περὶ ὧν λέγομεν καὶ τί ψεῦδος: κοινὸν γὰρ ἀγαθὸν ἅπασι φανερὸν γενέσθαι αὐτό. δίειμι","st":"505e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὲν οὖν τῷ λόγῳ ἐγὼ ὡς ἄν μοι δοκῇ ἔχειν: ἐὰν δέ τῳ ὑμῶν μὴ τὰ ὄντα δοκῶ ὁμολογεῖν ἐμαυτῷ, χρὴ ἀντιλαμβάνεσθαι καὶ ἐλέγχειν. οὐδὲ γάρ τοι ἔγωγε εἰδὼς λέγω ἃ λέγω, ἀλλὰ ζητῶ κοινῇ μεθ’ ὑμῶν, ὥστε, ἂν τὶ φαίνηται λέγων ὁ ἀμφισβητῶν ἐμοί, ἐγὼ πρῶτος συγχωρήσομαι. λέγω μέντοι ταῦτα, εἰ δοκεῖ χρῆναι διαπερανθῆναι τὸν λόγον: εἰ δὲ μὴ βούλεσθε, ἐῶμεν ἤδη χαίρειν καὶ ἀπίωμεν.","st":"506a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀλλ’ ἐμοὶ μὲν οὐ δοκεῖ, ὦ Σώκρατες, χρῆναί πω","st":"506a"},{"sp":"N","t":"<span class=\"speaker-label\">Γοργίας:<\/span> ἀπιέναι, ἀλλὰ διεξελθεῖν σε τὸν λόγον: φαίνεται δέ μοι καὶ τοῖς ἄλλοις δοκεῖν. βούλομαι γὰρ ἔγωγε καὶ αὐτὸς ἀκοῦσαί σου αὐτοῦ διιόντος τὰ ἐπίλοιπα.","st":"506b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὲν δή, ὦ Γοργία, καὶ αὐτὸς ἡδέως μὲν ἂν Καλλικλεῖ τούτῳ ἔτι διελεγόμην, ἕως αὐτῷ τὴν τοῦ Ἀμφίονος ἀπέδωκα ῥῆσιν ἀντὶ τῆς τοῦ Ζήθου: ἐπειδὴ δὲ σύ, ὦ Καλλίκλεις, οὐκ ἐθέλεις συνδιαπερᾶναι τὸν λόγον, ἀλλ’ οὖν ἐμοῦ γε ἀκούων ἐπιλαμβάνου, ἐάν τί σοι δοκῶ μὴ","st":"506b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς λέγειν. καί με ἐὰν ἐξελέγχῃς, οὐκ ἀχθεσθήσομαί σοι ὥσπερ σὺ ἐμοί, ἀλλὰ μέγιστος εὐεργέτης παρ’ ἐμοὶ ἀναγεγράψῃ.","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγε, ὠγαθέ, αὐτὸς καὶ πέραινε.","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄκουε δὴ ἐξ ἀρχῆς ἐμοῦ ἀναλαβόντος τὸν λόγον. ἆρα τὸ ἡδὺ καὶ τὸ ἀγαθὸν τὸ αὐτό ἐστιν;","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ ταὐτόν, ὡς ἐγὼ καὶ Καλλικλῆς ὡμολογήσαμεν.","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον δὲ τὸ ἡδὺ ἕνεκα τοῦ ἀγαθοῦ πρακτέον, ἢ τὸ ἀγαθὸν ἕνεκα τοῦ ἡδέος;","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ ἡδὺ ἕνεκα τοῦ ἀγαθοῦ.","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδὺ δέ ἐστιν τοῦτο οὗ","st":"506c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παραγενομένου ἡδόμεθα, ἀγαθὸν δὲ οὗ παρόντος ἀγαθοί ἐσμεν;","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάνυ γε.","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ἀγαθοί γέ ἐσμεν καὶ ἡμεῖς καὶ τἆλλα πάντα ὅσ’ ἀγαθά ἐστιν, ἀρετῆς τινος παραγενομένης;","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔμοιγε δοκεῖ ἀναγκαῖον εἶναι, ὦ Καλλίκλεις.","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὲν δὴ ἥ γε ἀρετὴ ἑκάστου, καὶ σκεύους καὶ σώματος καὶ ψυχῆς αὖ καὶ ζῴου παντός, οὐ τῷ εἰκῇ κάλλιστα παραγίγνεται, ἀλλὰ τάξει καὶ ὀρθότητι καὶ τέχνῃ, ἥτις ἑκάστῳ ἀποδέδοται αὐτῶν: ἆρα ἔστιν ταῦτα;","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ μὲν γάρ φημι.","st":"506d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τάξει ἆρα τεταγμένον καὶ κεκοσμημένον ἐστὶν ἡ ἀρετὴ ἑκάστου;","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φαίην ἂν ἔγωγε.","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κόσμος τις ἄρα ἐγγενόμενος ἐν ἑκάστῳ ὁ ἑκάστου οἰκεῖος ἀγαθὸν παρέχει ἕκαστον τῶν ὄντων;","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔμοιγε δοκεῖ.","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ψυχὴ ἄρα κόσμον ἔχουσα τὸν ἑαυτῆς ἀμείνων τῆς ἀκοσμήτου;","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνάγκη.","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ἥ γε κόσμον ἔχουσα κοσμία;","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς γὰρ οὐ μέλλει;","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ δέ","st":"506e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γε κοσμία σώφρων;","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πολλὴ ἀνάγκη.","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ ἄρα σώφρων ψυχὴ ἀγαθή. ἐγὼ μὲν οὐκ ἔχω παρὰ ταῦτα ἄλλα φάναι, ὦ φίλε Καλλίκλεις: σὺ δ’ εἰ ἔχεις, δίδασκε.","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγ’, ὠγαθέ.","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω δὴ ὅτι, εἰ ἡ σώφρων ἀγαθή ἐστιν, ἡ τοὐναντίον τῇ σώφρονι πεπονθυῖα κακή ἐστιν: ἦν δὲ αὕτη ἡ ἄφρων τε καὶ ἀκόλαστος. πάνυ γε.","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ὅ γε σώφρων τὰ προσήκοντα πράττοι ἂν καὶ περὶ θεοὺς καὶ περὶ ἀνθρώπους: οὐ γὰρ ἂν σωφρονοῖ τὰ μὴ προσήκοντα πράττων;","st":"507a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνάγκη ταῦτ’ εἶναι οὕτω.","st":"507b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν περὶ μὲν ἀνθρώπους τὰ προσήκοντα πράττων δίκαι’ ἂν πράττοι, περὶ δὲ θεοὺς ὅσια: τὸν δὲ τὰ δίκαια καὶ ὅσια πράττοντα ἀνάγκη δίκαιον καὶ ὅσιον εἶναι. ἔστι ταῦτα.","st":"507b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὲν δὴ καὶ ἀνδρεῖόν γε ἀνάγκη: οὐ γὰρ δὴ σώφρονος ἀνδρός ἐστιν οὔτε διώκειν οὔτε φεύγειν ἃ μὴ προσήκει, ἀλλ’ ἃ δεῖ καὶ πράγματα καὶ ἀνθρώπους καὶ ἡδονὰς καὶ λύπας φεύγειν καὶ διώκειν, καὶ ὑπομένοντα καρτερεῖν ὅπου δεῖ: ὥστε πολλὴ","st":"507b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνάγκη, ὦ Καλλίκλεις, τὸν σώφρονα, ὥσπερ διήλθομεν, δίκαιον ὄντα καὶ ἀνδρεῖον καὶ ὅσιον ἀγαθὸν ἄνδρα εἶναι τελέως, τὸν δὲ ἀγαθὸν εὖ τε καὶ καλῶς πράττειν ἃ ἂν πράττῃ, τὸν δ’ εὖ πράττοντα μακάριόν τε καὶ εὐδαίμονα εἶναι, τὸν δὲ πονηρὸν καὶ κακῶς πράττοντα ἄθλιον: οὗτος δ’ ἂν εἴη ὁ ἐναντίως ἔχων τῷ σώφρονι, ὁ ἀκόλαστος, ὃν σὺ ἐπῄνεις.","st":"507c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ μὲν οὖν ταῦτα οὕτω τίθεμαι καί φημι ταῦτα ἀληθῆ εἶναι: εἰ δὲ ἔστιν ἀληθῆ, τὸν βουλόμενον, ὡς ἔοικεν, εὐδαίμονα","st":"507c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι σωφροσύνην μὲν διωκτέον καὶ ἀσκητέον, ἀκολασίαν δὲ φευκτέον ὡς ἔχει ποδῶν ἕκαστος ἡμῶν, καὶ παρασκευαστέον μάλιστα μὲν μηδὲν δεῖσθαι τοῦ κολάζεσθαι, ἐὰν δὲ δεηθῇ ἢ αὐτὸς ἢ ἄλλος τις τῶν οἰκείων, ἢ ἰδιώτης ἢ πόλις, ἐπιθετέον δίκην καὶ κολαστέον, εἰ μέλλει εὐδαίμων εἶναι. οὗτος ἔμοιγε δοκεῖ ὁ σκοπὸς εἶναι πρὸς ὃν βλέποντα δεῖ ζῆν, καὶ πάντα εἰς τοῦτο τὰ αὑτοῦ συντείνοντα καὶ τὰ τῆς πόλεως, ὅπως δικαιοσύνη παρέσται καὶ σωφροσύνη","st":"507d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῷ μακαρίῳ μέλλοντι ἔσεσθαι, οὕτω πράττειν, οὐκ ἐπιθυμίας ἐῶντα ἀκολάστους εἶναι καὶ ταύτας ἐπιχειροῦντα πληροῦν, ἀνήνυτον κακόν, λῃστοῦ βίον ζῶντα. οὔτε γὰρ ἂν ἄλλῳ ἀνθρώπῳ προσφιλὴς ἂν εἴη ὁ τοιοῦτος οὔτε θεῷ: κοινωνεῖν γὰρ ἀδύνατος, ὅτῳ δὲ μὴ ἔνι κοινωνία, φιλία οὐκ ἂν εἴη. φασὶ δ’ οἱ σοφοί, ὦ Καλλίκλεις, καὶ οὐρανὸν καὶ","st":"507e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γῆν καὶ θεοὺς καὶ ἀνθρώπους τὴν κοινωνίαν συνέχειν καὶ φιλίαν καὶ κοσμιότητα καὶ σωφροσύνην καὶ δικαιότητα, καὶ τὸ ὅλον τοῦτο διὰ ταῦτα κόσμον καλοῦσιν, ὦ ἑταῖρε, οὐκ ἀκοσμίαν οὐδὲ ἀκολασίαν. σὺ δέ μοι δοκεῖς οὐ προσέχειν τὸν νοῦν τούτοις, καὶ ταῦτα σοφὸς ὤν, ἀλλὰ λέληθέν σε ὅτι ἡ ἰσότης ἡ γεωμετρικὴ καὶ ἐν θεοῖς καὶ ἐν ἀνθρώποις μέγα δύναται, σὺ δὲ πλεονεξίαν οἴει δεῖν ἀσκεῖν: γεωμετρίας γὰρ ἀμελεῖς. εἶεν: ἢ ἐξελεγκτέος δὴ οὗτος ὁ λόγος","st":"508a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμῖν ἐστιν, ὡς οὐ δικαιοσύνης καὶ σωφροσύνης κτήσει εὐδαίμονες οἱ εὐδαίμονες, κακίας δὲ οἱ ἄθλιοι, ἢ εἰ οὗτος ἀληθής ἐστιν, σκεπτέον τί τὰ συμβαίνοντα. τὰ πρόσθεν ἐκεῖνα, ὦ Καλλίκλεις, συμβαίνει πάντα, ἐφ’ οἷς σύ με ἤρου εἰ σπουδάζων λέγοιμι, λέγοντα ὅτι κατηγορητέον εἴη καὶ αὑτοῦ καὶ ὑέος καὶ ἑταίρου, ἐάν τι ἀδικῇ, καὶ τῇ ῥητορικῇ ἐπὶ τοῦτο χρηστέον: καὶ ἃ Πῶλον αἰσχύνῃ ᾤου συγχωρεῖν, ἀληθῆ ἄρα ἦν, τὸ εἶναι τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι ὅσῳπερ","st":"508b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αἴσχιον τοσούτῳ κάκιον: καὶ τὸν μέλλοντα ὀρθῶς ῥητορικὸν ἔσεσθαι δίκαιον ἄρα δεῖ εἶναι καὶ ἐπιστήμονα τῶν δικαίων, ὃ αὖ Γοργίαν ἔφη Πῶλος δι’ αἰσχύνην ὁμολογῆσαι.","st":"508c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων δὲ οὕτως ἐχόντων σκεψώμεθα τί ποτ’ ἐστὶν ἃ σὺ ἐμοὶ ὀνειδίζεις, ἆρα καλῶς λέγεται ἢ οὔ, ὡς ἄρα ἐγὼ οὐχ οἷός τ’ εἰμὶ βοηθῆσαι οὔτε ἐμαυτῷ οὔτε τῶν φίλων οὐδενὶ οὐδὲ τῶν οἰκείων, οὐδ’ ἐκσῶσαι ἐκ τῶν μεγίστων κινδύνων, εἰμὶ δὲ ἐπὶ τῷ βουλομένῳ ὥσπερ οἱ ἄτιμοι τοῦ ἐθέλοντος,","st":"508c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄντε τύπτειν βούληται, τὸ νεανικὸν δὴ τοῦτο τὸ τοῦ σοῦ λόγου, ἐπὶ κόρρης, ἐάντε χρήματα ἀφαιρεῖσθαι, ἐάντε ἐκβάλλειν ἐκ τῆς πόλεως, ἐάντε, τὸ ἔσχατον, ἀποκτεῖναι: καὶ οὕτω διακεῖσθαι πάντων δὴ αἴσχιστόν ἐστιν, ὡς ὁ σὸς λόγος. ὁ δὲ δὴ ἐμὸς ὅστις, πολλάκις μὲν ἤδη εἴρηται, οὐδὲν δὲ κωλύει καὶ ἔτι λέγεσθαι: οὔ φημι, ὦ Καλλίκλεις, τὸ τύπτεσθαι ἐπὶ κόρρης ἀδίκως αἴσχιστον εἶναι, οὐδέ γε τὸ τέμνεσθαι","st":"508d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτε τὸ σῶμα τὸ ἐμὸν οὔτε τὸ βαλλάντιον, ἀλλὰ τὸ τύπτειν καὶ ἐμὲ καὶ τὰ ἐμὰ ἀδίκως καὶ τέμνειν καὶ αἴσχιον καὶ κάκιον, καὶ κλέπτειν γε ἅμα καὶ ἀνδραποδίζεσθαι καὶ τοιχωρυχεῖν καὶ συλλήβδην ὁτιοῦν ἀδικεῖν καὶ ἐμὲ καὶ τὰ ἐμὰ τῷ ἀδικοῦντι καὶ κάκιον καὶ αἴσχιον εἶναι ἢ ἐμοὶ τῷ ἀδικουμένῳ. ταῦτα ἡμῖν ἄνω ἐκεῖ ἐν τοῖς πρόσθεν λόγοις οὕτω φανέντα, ὡς ἐγὼ λέγω, κατέχεται καὶ δέδεται, καὶ","st":"508e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ ἀγροικότερόν τι εἰπεῖν ἔστιν, σιδηροῖς καὶ ἀδαμαντίνοις λόγοις, ὡς γοῦν ἂν δόξειεν οὑτωσί, οὓς σὺ εἰ μὴ λύσεις ἢ σοῦ τις νεανικώτερος, οὐχ οἷόν τε ἄλλως λέγοντα ἢ ὡς ἐγὼ νῦν λέγω καλῶς λέγειν: ἐπεὶ ἔμοιγε ὁ αὐτὸς λόγος ἐστιν ἀεί, ὅτι ἐγὼ ταῦτα οὐκ οἶδα ὅπως ἔχει, ὅτι μέντοι ὧν ἐγὼ ἐντετύχηκα, ὥσπερ νῦν, οὐδεὶς οἷός τ’ ἐστὶν ἄλλως λέγων μὴ οὐ καταγέλαστος εἶναι. ἐγὼ μὲν οὖν αὖ τίθημι","st":"509a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα οὕτως ἔχειν: εἰ δὲ οὕτως ἔχει καὶ μέγιστον τῶν κακῶν ἐστιν ἡ ἀδικία τῷ ἀδικοῦντι καὶ ἔτι τούτου μεῖζον μεγίστου ὄντος, εἰ οἷόν τε, τὸ ἀδικοῦντα μὴ διδόναι δίκην, τίνα ἂν βοήθειαν μὴ δυνάμενος ἄνθρωπος βοηθεῖν ἑαυτῷ καταγέλαστος ἂν τῇ ἀληθείᾳ εἴη; ἆρα οὐ ταύτην, ἥτις ἀποτρέψει τὴν μεγίστην ἡμῶν βλάβην; ἀλλὰ πολλὴ ἀνάγκη ταύτην εἶναι τὴν αἰσχίστην βοήθειαν μὴ δύνασθαι βοηθεῖν μήτε αὑτῷ μήτε τοῖς αὑτοῦ φίλοις τε καὶ οἰκείοις, δευτέραν δὲ","st":"509b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τοῦ δευτέρου κακοῦ καὶ τρίτην τὴν τοῦ τρίτου καὶ τἆλλα οὕτως: ὡς ἑκάστου κακοῦ μέγεθος πέφυκεν, οὕτω καὶ κάλλος τοῦ δυνατὸν εἶναι ἐφ’ ἕκαστα βοηθεῖν καὶ αἰσχύνη τοῦ μή. ἆρα ἄλλως ἢ οὕτως ἔχει, ὦ Καλλίκλεις;","st":"509c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ ἄλλως.","st":"509c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δυοῖν οὖν ὄντοιν, τοῦ ἀδικεῖν τε καὶ ἀδικεῖσθαι, μεῖζον μέν φαμεν κακὸν τὸ ἀδικεῖν, ἔλαττον δὲ τὸ ἀδικεῖσθαι. τί οὖν ἂν παρασκευασάμενος ἄνθρωπος βοηθήσειεν αὑτῷ,","st":"509c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὥστε ἀμφοτέρας τὰς ὠφελίας ταύτας ἔχειν, τήν τε ἀπὸ τοῦ μὴ ἀδικεῖν καὶ τὴν ἀπὸ τοῦ μὴ ἀδικεῖσθαι; πότερα δύναμιν ἢ βούλησιν; ὧδε δὲ λέγω: πότερον ἐὰν μὴ βούληται ἀδικεῖσθαι, οὐκ ἀδικήσεται, ἢ ἐὰν δύναμιν παρασκευάσηται τοῦ μὴ ἀδικεῖσθαι, οὐκ ἀδικήσεται;","st":"509d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> δῆλον δὴ τοῦτό γε, ὅτι ἐὰν δύναμιν.","st":"509d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ δὴ τοῦ ἀδικεῖν; πότερον ἐὰν μὴ βούληται ἀδικεῖν, ἱκανὸν τοῦτ’ ἐστίν — οὐ γὰρ ἀδικήσει — ἢ καὶ ἐπὶ","st":"509d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο δεῖ δύναμίν τινα καὶ τέχνην παρασκευάσασθαι, ὡς, ἐὰν μὴ μάθῃ αὐτὰ καὶ ἀσκήσῃ, ἀδικήσει; τί οὐκ αὐτό γέ μοι τοῦτο ἀπεκρίνω, ὦ Καλλίκλεις, πότερόν σοι δοκοῦμεν ὀρθῶς ἀναγκασθῆναι ὁμολογεῖν ἐν τοῖς ἔμπροσθεν λόγοις ἐγώ τε καὶ Πῶλος ἢ οὔ, ἡνίκα ὡμολογήσαμεν μηδένα βουλόμενον ἀδικεῖν, ἀλλ’ ἄκοντας τοὺς ἀδικοῦντας πάντας ἀδικεῖν;","st":"509e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω σοι τοῦτο, ὦ Σώκρατες, οὕτως, ἵνα διαπεράνῃς τὸν λόγον.","st":"510a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐπὶ τοῦτο ἄρα, ὡς ἔοικεν, παρασκευαστέον ἐστὶ δύναμίν τινα καὶ τέχνην, ὅπως μὴ ἀδικήσωμεν.","st":"510a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"510a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν ποτ’ ἐστὶν τέχνη τῆς παρασκευῆς τοῦ μηδὲν ἀδικεῖσθαι ἢ ὡς ὀλίγιστα; σκέψαι εἰ σοὶ δοκεῖ ἥπερ ἐμοί. ἐμοὶ μὲν γὰρ δοκεῖ ἥδε: ἢ αὐτὸν ἄρχειν δεῖν ἐν τῇ πόλει ἢ καὶ τυραννεῖν, ἢ τῆς ὑπαρχούσης πολιτείας ἑταῖρον εἶναι.","st":"510a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὁρᾷς, ὦ Σώκρατες, ὡς ἐγὼ ἕτοιμός εἰμι ἐπαινεῖν,","st":"510a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἄν τι καλῶς λέγῃς; τοῦτό μοι δοκεῖς πάνυ καλῶς εἰρηκέναι.","st":"510b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκόπει δὴ καὶ τόδε ἐάν σοι δοκῶ εὖ λέγειν. φίλος μοι δοκεῖ ἕκαστος ἑκάστῳ εἶναι ὡς οἷόν τε μάλιστα, ὅνπερ οἱ παλαιοί τε καὶ σοφοὶ λέγουσιν, ὁ ὅμοιος τῷ ὁμοίῳ. οὐ καὶ σοί;","st":"510b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε.","st":"510b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὅπου τύραννός ἐστιν ἄρχων ἄγριος καὶ ἀπαίδευτος, εἴ τις τούτου ἐν τῇ πόλει πολὺ βελτίων εἴη, φοβοῖτο δήπου ἂν αὐτὸν ὁ τύραννος καὶ τούτῳ ἐξ ἅπαντος","st":"510b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ νοῦ οὐκ ἄν ποτε δύναιτο φίλος γενέσθαι;","st":"510c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστι ταῦτα.","st":"510c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέ γε εἴ τις πολὺ φαυλότερος εἴη, οὐδ’ ἂν οὗτος: καταφρονοῖ γὰρ ἂν αὐτοῦ ὁ τύραννος καὶ οὐκ ἄν ποτε ὡς πρὸς φίλον σπουδάσειεν.","st":"510c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> καὶ ταῦτ’ ἀληθῆ.","st":"510c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λείπεται δὴ ἐκεῖνος μόνος ἄξιος λόγου φίλος τῷ τοιούτῳ, ὃς ἂν ὁμοήθης ὤν, ταὐτὰ ψέγων καὶ ἐπαινῶν, ἐθέλῃ ἄρχεσθαι καὶ ὑποκεῖσθαι τῷ ἄρχοντι. οὗτος μέγα","st":"510c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν ταύτῃ τῇ πόλει δυνήσεται, τοῦτον οὐδεὶς χαίρων ἀδικήσει. οὐχ οὕτως ἔχει;","st":"510d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"510d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ ἄρα τις ἐννοήσειεν ἐν ταύτῃ τῇ πόλει τῶν νέων, “τίνα ἂν τρόπον ἐγὼ μέγα δυναίμην καὶ μηδείς με ἀδικοῖ;” αὕτη, ὡς ἔοικεν, αὐτῷ ὁδός ἐστιν, εὐθὺς ἐκ νέου ἐθίζειν αὑτὸν τοῖς αὐτοῖς χαίρειν καὶ ἄχθεσθαι τῷ δεσπότῃ, καὶ παρασκευάζειν ὅπως ὅτι μάλιστα ὅμοιος ἔσται ἐκείνῳ. οὐχ οὕτως;","st":"510d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"510d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τούτῳ τὸ μὲν μὴ ἀδικεῖσθαι καὶ μέγα","st":"510d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δύνασθαι, ὡς ὁ ὑμέτερος λόγος, ἐν τῇ πόλει διαπεπράξεται.","st":"510e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"510e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν καὶ τὸ μὴ ἀδικεῖν; ἢ πολλοῦ δεῖ, εἴπερ ὅμοιος ἔσται τῷ ἄρχοντι ὄντι ἀδίκῳ καὶ παρὰ τούτῳ μέγα δυνήσεται; ἀλλ’ οἶμαι ἔγωγε, πᾶν τοὐναντίον οὑτωσὶ ἡ παρασκευὴ ἔσται αὐτῷ ἐπὶ τὸ οἵῳ τε εἶναι ὡς πλεῖστα ἀδικεῖν καὶ ἀδικοῦντα μὴ διδόναι δίκην. ἦ γάρ;","st":"510e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φαίνεται.","st":"510e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ μέγιστον αὐτῷ κακὸν ὑπάρξει μοχθηρῷ ὄντι τὴν ψυχὴν καὶ λελωβημένῳ διὰ τὴν μίμησιν τοῦ δεσπότου καὶ δύναμιν.","st":"511a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ οἶδ’ ὅπῃ στρέφεις ἑκάστοτε τοὺς λόγους ἄνω καὶ κάτω, ὦ Σώκρατες: ἢ οὐκ οἶσθα ὅτι οὗτος ὁ μιμούμενος τὸν μὴ μιμούμενον ἐκεῖνον ἀποκτενεῖ, ἐὰν βούληται, καὶ ἀφαιρήσεται τὰ ὄντα.","st":"511a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶδα, ὠγαθὲ Καλλίκλεις, εἰ μὴ κωφός γ’ εἰμί, καὶ σοῦ ἀκούων καὶ Πώλου ἄρτι πολλάκις καὶ τῶν ἄλλων ὀλίγου πάντων τῶν ἐν τῇ πόλει: ἀλλὰ καὶ σὺ ἐμοῦ ἄκουε, ὅτι ἀποκτενεῖ μέν, ἂν βούληται, ἀλλὰ πονηρὸς ὢν καλὸν κἀγαθὸν ὄντα.","st":"511b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκοῦν τοῦτο δὴ καὶ τὸ ἀγανακτητόν;","st":"511b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ νοῦν γε ἔχοντι, ὡς ὁ λόγος σημαίνει. ἢ οἴει δεῖν τοῦτο παρασκευάζεσθαι ἄνθρωπον, ὡς πλεῖστον χρόνον ζῆν, καὶ μελετᾶν τὰς τέχνας ταύτας αἳ ἡμᾶς ἀεὶ ἐκ τῶν","st":"511b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κινδύνων σῴζουσιν, ὥσπερ καὶ ἣν σὺ κελεύεις ἐμὲ μελετᾶν τὴν ῥητορικὴν τὴν ἐν τοῖς δικαστηρίοις διασῴζουσαν;","st":"511c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναὶ μὰ Δία ὀρθῶς γέ σοι συμβουλεύων.","st":"511c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ, ὦ βέλτιστε; ἦ καὶ ἡ τοῦ νεῖν ἐπιστήμη σεμνή τίς σοι δοκεῖ εἶναι;","st":"511c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> μὰ Δί’ οὐκ ἔμοιγε.","st":"511c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν σῴζει γε καὶ αὕτη ἐκ θανάτου τοὺς ἀνθρώπους, ὅταν εἴς τι τοιοῦτον ἐμπέσωσιν οὗ δεῖ ταύτης τῆς ἐπιστήμης. εἰ δ’ αὕτη σοι δοκεῖ σμικρὰ εἶναι, ἐγώ σοι","st":"511c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μείζω ταύτης ἐρῶ, τὴν κυβερνητικήν, ἣ οὐ μόνον τὰς ψυχὰς σῴζει ἀλλὰ καὶ τὰ σώματα καὶ τὰ χρήματα ἐκ τῶν ἐσχάτων κινδύνων, ὥσπερ ἡ ῥητορική. καὶ αὕτη μὲν προσεσταλμένη ἐστὶν καὶ κοσμία, καὶ οὐ σεμνύνεται ἐσχηματισμένη ὡς ὑπερήφανόν τι διαπραττομένη, ἀλλὰ ταὐτὰ διαπραξαμένη τῇ δικανικῇ, ἐὰν μὲν ἐξ Αἰγίνης δεῦρο σώσῃ, οἶμαι δύ’ ὀβολοὺς ἐπράξατο, ἐὰν δὲ ἐξ Αἰγύπτου ἢ ἐκ τοῦ Πόντου,","st":"511d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐὰν πάμπολυ, ταύτης τῆς μεγάλης εὐεργεσίας, σώσασα ἃ νυνδὴ ἔλεγον, καὶ αὐτὸν καὶ παῖδας καὶ χρήματα καὶ γυναῖκας, ἀποβιβάσασ’ εἰς τὸν λιμένα δύο δραχμὰς ἐπράξατο, καὶ αὐτὸς ὁ ἔχων τὴν τέχνην καὶ ταῦτα διαπραξάμενος ἐκβὰς παρὰ τὴν θάλατταν καὶ τὴν ναῦν περιπατεῖ ἐν μετρίῳ σχήματι: λογίζεσθαι γὰρ οἶμαι ἐπίσταται ὅτι ἄδηλόν ἐστιν οὕστινάς τε ὠφέληκεν τῶν συμπλεόντων οὐκ ἐάσας καταποντωθῆναι καὶ οὕστινας ἔβλαψεν, εἰδὼς ὅτι οὐδὲν","st":"511e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτοὺς βελτίους ἐξεβίβασεν ἢ οἷοι ἐνέβησαν, οὔτε τὰ σώματα οὔτε τὰς ψυχάς. λογίζεται οὖν ὅτι οὐκ, εἰ μέν τις μεγάλοις καὶ ἀνιάτοις νοσήμασιν κατὰ τὸ σῶμα συνεχόμενος μὴ ἀπεπνίγη, οὗτος μὲν ἄθλιός ἐστιν ὅτι οὐκ ἀπέθανεν, καὶ οὐδὲν ὑπ’ αὐτοῦ ὠφέληται: εἰ δέ τις ἄρα ἐν τῷ τοῦ σώματος τιμιωτέρῳ, τῇ ψυχῇ, πολλὰ νοσήματα ἔχει καὶ ἀνίατα, τούτῳ δὲ βιωτέον ἐστὶν καὶ τοῦτον ὀνήσει, ἄντε ἐκ θαλάττης ἄντε ἐκ δικαστηρίου ἐάντε ἄλλοθεν ὁποθενοῦν","st":"512a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σώσῃ, ἀλλ’ οἶδεν ὅτι οὐκ ἄμεινόν ἐστιν ζῆν τῷ μοχθηρῷ ἀνθρώπῳ: κακῶς γὰρ ἀνάγκη ἐστὶν ζῆν.","st":"512b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ ταῦτα οὐ νόμος ἐστὶ σεμνύνεσθαι τὸν κυβερνήτην, καίπερ σῴζοντα ἡμᾶς, οὐδέ γε, ὦ θαυμάσιε, τὸν μηχανοποιόν, ὃς οὔτε στρατηγοῦ, μὴ ὅτι κυβερνήτου, οὔτε ἄλλου οὐδενὸς ἐλάττω ἐνίοτε δύναται σῴζειν: πόλεις γὰρ ἔστιν ὅτε ὅλας σῴζει. μή σοι δοκεῖ κατὰ τὸν δικανικὸν εἶναι; καίτοι εἰ βούλοιτο λέγειν, ὦ Καλλίκλεις, ἅπερ ὑμεῖς, σεμνύνων","st":"512b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ πρᾶγμα, καταχώσειεν ἂν ὑμᾶς τοῖς λόγοις, λέγων καὶ παρακαλῶν ἐπὶ τὸ δεῖν γίγνεσθαι μηχανοποιούς, ὡς οὐδὲν τἆλλά ἐστιν: ἱκανὸς γὰρ αὐτῷ ὁ λόγος. ἀλλὰ σὺ οὐδὲν ἧττον αὐτοῦ καταφρονεῖς καὶ τῆς τέχνης τῆς ἐκείνου, καὶ ὡς ἐν ὀνείδει ἀποκαλέσαις ἂν μηχανοποιόν, καὶ τῷ ὑεῖ αὐτοῦ οὔτ’ ἂν δοῦναι θυγατέρα ἐθέλοις, οὔτ’ ἂν αὐτὸς λαβεῖν τὴν ἐκείνου. καίτοι ἐξ ὧν τὰ σαυτοῦ ἐπαινεῖς, τίνι δικαίῳ λόγῳ τοῦ μηχανοποιοῦ καταφρονεῖς καὶ","st":"512c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν ἄλλων ὧν νυνδὴ ἔλεγον; οἶδ’ ὅτι φαίης ἂν βελτίων εἶναι καὶ ἐκ βελτιόνων. τὸ δὲ βέλτιον εἰ μὴ ἔστιν ὃ ἐγὼ λέγω, ἀλλ’ αὐτὸ τοῦτ’ ἐστὶν ἀρετή, τὸ σῴζειν αὑτὸν καὶ τὰ ἑαυτοῦ ὄντα ὁποῖός τις ἔτυχεν, καταγέλαστός σοι ὁ ψόγος γίγνεται καὶ μηχανοποιοῦ καὶ ἰατροῦ καὶ τῶν ἄλλων τεχνῶν ὅσαι τοῦ σῴζειν ἕνεκα πεποίηνται. ἀλλ’, ὦ μακάριε, ὅρα μὴ ἄλλο τι τὸ γενναῖον καὶ τὸ ἀγαθὸν ᾖ ἢ τὸ σῴζειν τε καὶ σῴζεσθαι. μὴ γὰρ τοῦτο μέν, τὸ ζῆν ὁποσονδὴ","st":"512d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χρόνον, τόν γε ὡς ἀληθῶς ἄνδρα ἐατέον ἐστὶν καὶ οὐ φιλοψυχητέον, ἀλλὰ ἐπιτρέψαντα περὶ τούτων τῷ θεῷ καὶ πιστεύσαντα ταῖς γυναιξὶν ὅτι τὴν εἱμαρμένην οὐδ’ ἂν εἷς ἐκφύγοι, τὸ ἐπὶ τούτῳ σκεπτέον τίν’ ἂν τρόπον τοῦτον ὃν μέλλοι χρόνον βιῶναι ὡς ἄριστα βιοίη, ἆρα ἐξομοιῶν","st":"512e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὑτὸν τῇ πολιτείᾳ ταύτῃ ἐν ᾗ ἂν οἰκῇ, καὶ νῦν δὲ ἄρα δεῖ σὲ ὡς ὁμοιότατον γίγνεσθαι τῷ δήμῳ τῷ Ἀθηναίων, εἰ μέλλεις τούτῳ προσφιλὴς εἶναι καὶ μέγα δύνασθαι ἐν τῇ πόλει: τοῦθ’ ὅρα εἰ σοὶ λυσιτελεῖ καὶ ἐμοί, ὅπως μή, ὦ δαιμόνιε, πεισόμεθα ὅπερ φασὶ τὰς τὴν σελήνην καθαιρούσας, τὰς Θετταλίδας: σὺν τοῖς φιλτάτοις ἡ αἵρεσις ἡμῖν ἔσται ταύτης τῆς δυνάμεως τῆς ἐν τῇ πόλει. εἰ δέ σοι οἴει ὁντινοῦν ἀνθρώπων παραδώσειν τέχνην τινὰ τοιαύτην, ἥτις","st":"513a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σε ποιήσει μέγα δύνασθαι ἐν τῇ πόλει τῇδε ἀνόμοιον ὄντα τῇ πολιτείᾳ εἴτ’ ἐπὶ τὸ βέλτιον εἴτ’ ἐπὶ τὸ χεῖρον, ὡς ἐμοὶ δοκεῖ, οὐκ ὀρθῶς βουλεύῃ, ὦ Καλλίκλεις: οὐ γὰρ μιμητὴν δεῖ εἶναι ἀλλ’ αὐτοφυῶς ὅμοιον τούτοις, εἰ μέλλεις τι γνήσιον ἀπεργάζεσθαι εἰς φιλίαν τῷ Ἀθηναίων δήμῳ καὶ ναὶ μὰ Δία τῷ Πυριλάμπους γε πρός. ὅστις οὖν σε τούτοις ὁμοιότατον ἀπεργάσεται, οὗτός σε ποιήσει, ὡς ἐπιθυμεῖς πολιτικὸς εἶναι, πολιτικὸν καὶ ῥητορικόν: τῷ αὑτῶν γὰρ","st":"513b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἤθει λεγομένων τῶν λόγων ἕκαστοι χαίρουσι, τῷ δὲ ἀλλοτρίῳ ἄχθονται, εἰ μή τι σὺ ἄλλο λέγεις, ὦ φίλη κεφαλή. λέγομέν τι πρὸς ταῦτα, ὦ Καλλίκλεις;","st":"513c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ οἶδ’ ὅντινά μοι τρόπον δοκεῖς εὖ λέγειν, ὦ Σώκρατες, πέπονθα δὲ τὸ τῶν πολλῶν πάθος: οὐ πάνυ σοι πείθομαι.","st":"513c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δήμου γὰρ ἔρως, ὦ Καλλίκλεις, ἐνὼν ἐν τῇ ψυχῇ τῇ σῇ ἀντιστατεῖ μοι: ἀλλ’ ἐὰν πολλάκις [ἴσως καὶ] βέλτιον","st":"513c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταὐτὰ ταῦτα διασκοπώμεθα, πεισθήσῃ. ἀναμνήσθητι δ’ οὖν ὅτι δύ’ ἔφαμεν εἶναι τὰς παρασκευὰς ἐπὶ τὸ ἕκαστον θεραπεύειν, καὶ σῶμα καὶ ψυχήν, μίαν μὲν πρὸς ἡδονὴν ὁμιλεῖν, τὴν ἑτέραν δὲ πρὸς τὸ βέλτιστον, μὴ καταχαριζόμενον ἀλλὰ διαμαχόμενον. οὐ ταῦτα ἦν ἃ τότε ὡριζόμεθα;","st":"513d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"513d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἡ μὲν ἑτέρα, ἡ πρὸς ἡδονήν, ἀγεννὴς καὶ οὐδὲν ἄλλο ἢ κολακεία τυγχάνει οὖσα: ἦ γάρ;","st":"513d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω, εἰ βούλει, σοὶ οὕτως.","st":"513e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ δέ γε ἑτέρα, ὅπως ὡς βέλτιστον ἔσται τοῦτο, εἴτε σῶμα τυγχάνει ὂν εἴτε ψυχή, ὃ θεραπεύομεν;","st":"513e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"513e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ’ οὖν οὕτως ἐπιχειρητέον ἡμῖν ἐστιν τῇ πόλει καὶ τοῖς πολίταις θεραπεύειν, ὡς βελτίστους αὐτοὺς τοὺς πολίτας ποιοῦντας; ἄνευ γὰρ δὴ τούτου, ὡς ἐν τοῖς ἔμπροσθεν ηὑρίσκομεν, οὐδὲν ὄφελος ἄλλην εὐεργεσίαν οὐδεμίαν","st":"513e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προσφέρειν, ἐὰν μὴ καλὴ κἀγαθὴ ἡ διάνοια ᾖ τῶν μελλόντων ἢ χρήματα πολλὰ λαμβάνειν ἢ ἀρχήν τινων ἢ ἄλλην δύναμιν ἡντινοῦν. φῶμεν οὕτως ἔχειν;","st":"514a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε, εἴ σοι ἥδιον.","st":"514a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ οὖν παρεκαλοῦμεν ἀλλήλους, ὦ Καλλίκλεις, δημοσίᾳ πράξοντες τῶν πολιτικῶν πραγμάτων ἐπὶ τὰ οἰκοδομικά, ἢ τειχῶν ἢ νεωρίων ἢ ἱερῶν ἐπὶ τὰ μέγιστα οἰκοδομήματα, πότερον ἔδει ἂν ἡμᾶς σκέψασθαι ἡμᾶς αὐτοὺς καὶ","st":"514a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐξετάσαι πρῶτον μὲν εἰ ἐπιστάμεθα τὴν τέχνην ἢ οὐκ ἐπιστάμεθα, τὴν οἰκοδομικήν, καὶ παρὰ τοῦ ἐμάθομεν; ἔδει ἂν ἢ οὔ;","st":"514b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"514b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν δεύτερον αὖ τόδε, εἴ τι πώποτε οἰκοδόμημα ᾠκοδομήκαμεν ἰδίᾳ ἢ τῶν φίλων τινὶ ἢ ἡμέτερον αὐτῶν, καὶ τοῦτο τὸ οἰκοδόμημα καλὸν ἢ αἰσχρόν ἐστιν: καὶ εἰ μὲν ηὑρίσκομεν σκοπούμενοι διδασκάλους τε ἡμῶν ἀγαθοὺς καὶ","st":"514b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐλλογίμους γεγονότας καὶ οἰκοδομήματα πολλὰ μὲν καὶ καλὰ μετὰ τῶν διδασκάλων ᾠκοδομημένα ἡμῖν, πολλὰ δὲ καὶ ἴδια ἡμῶν ἐπειδὴ τῶν διδασκάλων ἀπηλλάγημεν, οὕτω μὲν διακειμένων, νοῦν ἐχόντων ἦν ἂν ἰέναι ἐπὶ τὰ δημόσια ἔργα: εἰ δὲ μήτε διδάσκαλον εἴχομεν ἡμῶν αὐτῶν ἐπιδεῖξαι οἰκοδομήματά τε ἢ μηδὲν ἢ πολλὰ καὶ μηδενὸς ἄξια, οὕτω δὴ ἀνόητον ἦν δήπου ἐπιχειρεῖν τοῖς δημοσίοις ἔργοις καὶ παρακαλεῖν ἀλλήλους ἐπ’ αὐτά. φῶμεν ταῦτα ὀρθῶς λέγεσθαι","st":"514c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἢ οὔ;","st":"514d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"514d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὕτω πάντα, τά τε ἄλλα κἂν εἰ ἐπιχειρήσαντες δημοσιεύειν παρεκαλοῦμεν ἀλλήλους ὡς ἱκανοὶ ἰατροὶ ὄντες, ἐπεσκεψάμεθα δήπου ἂν ἐγώ τε σὲ καὶ σὺ ἐμέ, φέρε πρὸς θεῶν, αὐτὸς δὲ ὁ Σωκράτης πῶς ἔχει τὸ σῶμα πρὸς ὑγίειαν; ἢ ἤδη τις ἄλλος διὰ Σωκράτην ἀπηλλάγη νόσου, ἢ δοῦλος ἢ ἐλεύθερος; κἂν ἐγὼ οἶμαι περὶ σοῦ ἕτερα τοιαῦτα ἐσκόπουν: καὶ εἰ μὴ ηὑρίσκομεν δι’ ἡμᾶς μηδένα","st":"514d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βελτίω γεγονότα τὸ σῶμα, μήτε τῶν ξένων μήτε τῶν ἀστῶν, μήτε ἄνδρα μήτε γυναῖκα, πρὸς Διός, ὦ Καλλίκλεις, οὐ καταγέλαστον ἂν ἦν τῇ ἀληθείᾳ, εἰς τοσοῦτον ἀνοίας ἐλθεῖν ἀνθρώπους, ὥστε, πρὶν ἰδιωτεύοντας πολλὰ μὲν ὅπως ἐτύχομεν ποιῆσαι, πολλὰ δὲ κατορθῶσαι καὶ γυμνάσασθαι ἱκανῶς τὴν τέχνην, τὸ λεγόμενον δὴ τοῦτο ἐν τῷ πίθῳ τὴν κεραμείαν ἐπιχειρεῖν μανθάνειν, καὶ αὐτούς τε δημοσιεύειν ἐπιχειρεῖν καὶ ἄλλους τοιούτους παρακαλεῖν; οὐκ ἀνόητόν σοι δοκεῖ ἂν εἶναι οὕτω πράττειν;","st":"514e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε.","st":"514e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δέ, ὦ βέλτιστε ἀνδρῶν, ἐπειδὴ σὺ μὲν αὐτὸς ἄρτι ἄρχῃ πράττειν τὰ τῆς πόλεως πράγματα, ἐμὲ δὲ παρακαλεῖς καὶ ὀνειδίζεις ὅτι οὐ πράττω, οὐκ ἐπισκεψόμεθα ἀλλήλους, φέρε, Καλλικλῆς ἤδη τινὰ βελτίω πεποίηκεν τῶν πολιτῶν; ἔστιν ὅστις πρότερον πονηρὸς ὤν, ἄδικός τε καὶ ἀκόλαστος καὶ ἄφρων, διὰ Καλλικλέα καλός τε κἀγαθὸς γέγονεν, ἢ ξένος ἢ ἀστός, ἢ δοῦλος ἢ ἐλεύθερος; λέγε μοι,","st":"515a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐάν τίς σε ταῦτα ἐξετάζῃ, ὦ Καλλίκλεις, τί ἐρεῖς; τίνα φήσεις βελτίω πεποιηκέναι ἄνθρωπον τῇ συνουσίᾳ τῇ σῇ; ὀκνεῖς ἀποκρίνασθαι, εἴπερ ἔστιν τι ἔργον σὸν ἔτι ἰδιωτεύοντος, πρὶν δημοσιεύειν ἐπιχειρεῖν;","st":"515b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φιλόνικος εἶ, ὦ Σώκρατες.","st":"515b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ’ οὐ φιλονικίᾳ γε ἐρωτῶ, ἀλλ’ ὡς ἀληθῶς βουλόμενος εἰδέναι ὅντινά ποτε τρόπον οἴει δεῖν πολιτεύεσθαι ἐν ἡμῖν. ἢ ἄλλου του ἄρα ἐπιμελήσῃ ἡμῖν ἐλθὼν ἐπὶ τὰ","st":"515b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῆς πόλεως πράγματα ἢ ὅπως ὅτι βέλτιστοι οἱ πολῖται ὦμεν; ἢ οὐ πολλάκις ἤδη ὡμολογήκαμεν τοῦτο δεῖν πράττειν τὸν πολιτικὸν ἄνδρα; ὡμολογήκαμεν ἢ οὔ; ἀποκρίνου. ὡμολογήκαμεν: ἐγὼ ὑπὲρ σοῦ ἀποκρινοῦμαι. εἰ τοίνυν τοῦτο δεῖ τὸν ἀγαθὸν ἄνδρα παρασκευάζειν τῇ ἑαυτοῦ πόλει, νῦν μοι ἀναμνησθεὶς εἰπὲ περὶ ἐκείνων τῶν ἀνδρῶν ὧν ὀλίγῳ πρότερον ἔλεγες, εἰ ἔτι σοι δοκοῦσιν ἀγαθοὶ πολῖται γεγονέναι,","st":"515c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Περικλῆς καὶ Κίμων καὶ Μιλτιάδης καὶ Θεμιστοκλῆς.","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε.","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ ἀγαθοί, δῆλον ὅτι ἕκαστος αὐτῶν βελτίους ἐποίει τοὺς πολίτας ἀντὶ χειρόνων. ἐποίει ἢ οὔ;","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὅτε Περικλῆς ἤρχετο λέγειν ἐν τῷ δήμῳ, χείρους ἦσαν οἱ Ἀθηναῖοι ἢ ὅτε τὰ τελευταῖα ἔλεγεν;","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἴσως.","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἴσως δή, ὦ βέλτιστε, ἀλλ’ ἀνάγκη ἐκ τῶν ὡμολογημένων, εἴπερ ἀγαθός γ’ ἦν ἐκεῖνος πολίτης.","st":"515d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί οὖν δή;","st":"515e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέν: ἀλλὰ τόδε μοι εἰπὲ ἐπὶ τούτῳ, εἰ λέγονται Ἀθηναῖοι διὰ Περικλέα βελτίους γεγονέναι, ἢ πᾶν τοὐναντίον διαφθαρῆναι ὑπ’ ἐκείνου. ταυτὶ γὰρ ἔγωγε ἀκούω, Περικλέα πεποιηκέναι Ἀθηναίους ἀργοὺς καὶ δειλοὺς καὶ λάλους καὶ φιλαργύρους, εἰς μισθοφορίαν πρῶτον καταστήσαντα.","st":"515e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τῶν τὰ ὦτα κατεαγότων ἀκούεις ταῦτα, ὦ Σώκρατες.","st":"515e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ τάδε οὐκέτι ἀκούω, ἀλλ’ οἶδα σαφῶς καὶ ἐγὼ καὶ σύ, ὅτι τὸ μὲν πρῶτον ηὐδοκίμει Περικλῆς καὶ οὐδεμίαν αἰσχρὰν δίκην κατεψηφίσαντο αὐτοῦ Ἀθηναῖοι, ἡνίκα χείρους ἦσαν: ἐπειδὴ δὲ καλοὶ κἀγαθοὶ ἐγεγόνεσαν","st":"515e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὑπ’ αὐτοῦ, ἐπὶ τελευτῇ τοῦ βίου τοῦ Περικλέους, κλοπὴν αὐτοῦ κατεψηφίσαντο, ὀλίγου δὲ καὶ θανάτου ἐτίμησαν, δῆλον ὅτι ὡς πονηροῦ ὄντος.","st":"516a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> τί οὖν; τούτου ἕνεκα κακὸς ἦν Περικλῆς;","st":"516a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὄνων γοῦν ἂν ἐπιμελητὴς καὶ ἵππων καὶ βοῶν τοιοῦτος ὢν κακὸς ἂν ἐδόκει εἶναι, εἰ παραλαβὼν μὴ λακτίζοντας ἑαυτὸν μηδὲ κυρίττοντας μηδὲ δάκνοντας ἀπέδειξε ταῦτα ἅπαντα ποιοῦντας δι’ ἀγριότητα. ἢ οὐ δοκεῖ σοι","st":"516a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸς εἶναι ἐπιμελητὴς ὁστισοῦν ὁτουοῦν ζῴου, ὃς ἂν παραλαβὼν ἡμερώτερα ἀποδείξῃ ἀγριώτερα ἢ παρέλαβε; δοκεῖ ἢ οὔ;","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε, ἵνα σοι χαρίσωμαι.","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τόδε τοίνυν μοι χάρισαι ἀποκρινάμενος: πότερον καὶ ὁ ἄνθρωπος ἓν τῶν ζῴων ἐστὶν ἢ οὔ;","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πῶς γὰρ οὔ;","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀνθρώπων Περικλῆς ἐπεμέλετο;","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; οὐκ ἔδει αὐτούς, ὡς ἄρτι ὡμολογοῦμεν, δικαιοτέρους γεγονέναι ἀντὶ ἀδικωτέρων ὑπ’ ἐκείνου, εἴπερ","st":"516b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐκεῖνος ἐπεμελεῖτο αὐτῶν ἀγαθὸς ὢν τὰ πολιτικά;","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οἵ γε δίκαιοι ἥμεροι, ὡς ἔφη Ὅμηρος: σὺ δὲ τί φῄς; οὐχ οὕτως;","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ἀγριωτέρους γε αὐτοὺς ἀπέφηνεν ἢ οἵους παρέλαβεν, καὶ ταῦτ’ εἰς αὑτόν, ὃν ἥκιστ’ ἂν ἐβούλετο.","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> βούλει σοι ὁμολογήσω;","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δοκῶ γε σοι ἀληθῆ λέγειν.","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω δὴ ταῦτα.","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴπερ ἀγριωτέρους, ἀδικωτέρους τε καὶ χείρους;","st":"516c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστω.","st":"516d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρ’ ἀγαθὸς τὰ πολιτικὰ Περικλῆς ἦν ἐκ τούτου τοῦ λόγου.","st":"516d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐ σύ γε φῄς.","st":"516d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὰ Δί’ οὐδέ γε σὺ ἐξ ὧν ὡμολόγεις. πάλιν δὲ λέγε μοι περὶ Κίμωνος: οὐκ ἐξωστράκισαν αὐτὸν οὗτοι οὓς ἐθεράπευεν, ἵνα αὐτοῦ δέκα ἐτῶν μὴ ἀκούσειαν τῆς φωνῆς; καὶ Θεμιστοκλέα ταὐτὰ ταῦτα ἐποίησαν καὶ φυγῇ προσεζημίωσαν; Μιλτιάδην δὲ τὸν Μαραθῶνι εἰς τὸ βάραθρον","st":"516d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμβαλεῖν ἐψηφίσαντο, καὶ εἰ μὴ διὰ τὸν πρύτανιν, ἐνέπεσεν ἄν; καίτοι οὗτοι, εἰ ἦσαν ἄνδρες ἀγαθοί, ὡς σὺ φῄς, οὐκ ἄν ποτε ταῦτα ἔπασχον. οὔκουν οἵ γε ἀγαθοὶ ἡνίοχοι κατ’ ἀρχὰς μὲν οὐκ ἐκπίπτουσιν ἐκ τῶν ζευγῶν, ἐπειδὰν δὲ θεραπεύσωσιν τοὺς ἵππους καὶ αὐτοὶ ἀμείνους γένωνται ἡνίοχοι, τότ’ ἐκπίπτουσιν: οὐκ ἔστι ταῦτ’ οὔτ’ ἐν ἡνιοχείᾳ οὔτ’ ἐν ἄλλῳ ἔργῳ οὐδενί: ἢ δοκεῖ σοι;","st":"516e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> οὐκ ἔμοιγε.","st":"516e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθεῖς ἄρα, ὡς ἔοικεν, οἱ ἔμπροσθεν λόγοι ἦσαν,","st":"516e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι οὐδένα ἡμεῖς ἴσμεν ἄνδρα ἀγαθὸν γεγονότα τὰ πολιτικὰ ἐν τῇδε τῇ πόλει. σὺ δὲ ὡμολόγεις τῶν γε νῦν οὐδένα, τῶν μέντοι ἔμπροσθεν, καὶ προείλου τούτους τοὺς ἄνδρας: οὗτοι δὲ ἀνεφάνησαν ἐξ ἴσου τοῖς νῦν ὄντες, ὥστε, εἰ οὗτοι ῥήτορες ἦσαν, οὔτε τῇ ἀληθινῇ ῥητορικῇ ἐχρῶντο — οὐ γὰρ ἂν ἐξέπεσον — οὔτε τῇ κολακικῇ.","st":"517a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλὰ μέντοι πολλοῦ γε δεῖ, ὦ Σώκρατες, μή ποτέ τις τῶν νῦν ἔργα τοιαῦτα ἐργάσηται οἷα τούτων ὅστις","st":"517a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> βούλει εἴργασται.","st":"517b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ δαιμόνιε, οὐδ’ ἐγὼ ψέγω τούτους ὥς γε διακόνους εἶναι πόλεως, ἀλλά μοι δοκοῦσι τῶν γε νῦν διακονικώτεροι γεγονέναι καὶ μᾶλλον οἷοί τε ἐκπορίζειν τῇ πόλει ὧν ἐπεθύμει. ἀλλὰ γὰρ μεταβιβάζειν τὰς ἐπιθυμίας καὶ μὴ ἐπιτρέπειν, πείθοντες καὶ βιαζόμενοι ἐπὶ τοῦτο ὅθεν ἔμελλον ἀμείνους ἔσεσθαι οἱ πολῖται, ὡς ἔπος εἰπεῖν οὐδὲν","st":"517b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων διέφερον ἐκεῖνοι: ὅπερ μόνον ἔργον ἐστὶν ἀγαθοῦ πολίτου. ναῦς δὲ καὶ τείχη καὶ νεώρια καὶ ἄλλα πολλὰ τοιαῦτα καὶ ἐγώ σοι ὁμολογῶ δεινοτέρους εἶναι ἐκείνους τούτων ἐκπορίζειν. πρᾶγμα οὖν γελοῖον ποιοῦμεν ἐγώ τε καὶ σὺ ἐν τοῖς λόγοις: ἐν παντὶ γὰρ τῷ χρόνῳ ὃν διαλεγόμεθα οὐδὲν παυόμεθα εἰς τὸ αὐτὸ ἀεὶ περιφερόμενοι καὶ ἀγνοοῦντες ἀλλήλων ὅτι λέγομεν. ἐγὼ γοῦν σε πολλάκις οἶμαι ὡμολογηκέναι καὶ ἐγνωκέναι ὡς ἄρα διττὴ αὕτη τις","st":"517c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ πραγματεία ἔστιν καὶ περὶ τὸ σῶμα καὶ περὶ τὴν ψυχήν, καὶ ἡ μὲν ἑτέρα διακονική ἐστιν, ᾗ δυνατὸν εἶναι ἐκπορίζειν, ἐὰν μὲν πεινῇ τὰ σώματα ἡμῶν, σιτία, ἐὰν δὲ διψῇ, ποτά, ἐὰν δὲ ῥιγῷ, ἱμάτια, στρώματα, ὑποδήματα, ἄλλ’ ὧν ἔρχεται σώματα εἰς ἐπιθυμίαν: καὶ ἐξεπίτηδές σοι διὰ τῶν αὐτῶν εἰκόνων λέγω, ἵνα ῥᾷον καταμάθῃς. τούτων γὰρ ποριστικὸν εἶναι ἢ κάπηλον ὄντα ἢ ἔμπορον ἢ δημιουργόν του αὐτῶν","st":"517d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων, σιτοποιὸν ἢ ὀψοποιὸν ἢ ὑφάντην ἢ σκυτοτόμον ἢ σκυτοδεψόν, οὐδὲν θαυμαστόν ἐστιν ὄντα τοιοῦτον δόξαι καὶ αὑτῷ καὶ τοῖς ἄλλοις θεραπευτὴν εἶναι σώματος, παντὶ τῷ μὴ εἰδότι ὅτι ἔστιν τις παρὰ ταύτας ἁπάσας τέχνη γυμναστική τε καὶ ἰατρική, ἣ δὴ τῷ ὄντι γε ἐστὶν σώματος θεραπεία, ἥνπερ καὶ προσήκει τούτων ἄρχειν πασῶν τῶν τεχνῶν καὶ χρῆσθαι τοῖς τούτων ἔργοις διὰ τὸ εἰδέναι ὅτι χρηστὸν καὶ πονηρὸν τῶν σιτίων ἢ ποτῶν ἐστιν εἰς ἀρετὴν","st":"517e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σώματος, τὰς δ’ ἄλλας πάσας ταύτας ἀγνοεῖν: διὸ δὴ καὶ ταύτας μὲν δουλοπρεπεῖς τε καὶ διακονικὰς καὶ ἀνελευθέρους εἶναι περὶ σώματος πραγματείαν, τὰς ἄλλας τέχνας, τὴν δὲ γυμναστικὴν καὶ ἰατρικὴν κατὰ τὸ δίκαιον δεσποίνας εἶναι τούτων. ταὐτὰ οὖν ταῦτα ὅτι ἔστιν καὶ περὶ ψυχήν, τοτὲ μέν μοι δοκεῖς μανθάνειν ὅτι λέγω, καὶ ὁμολογεῖς ὡς εἰδὼς ὅτι ἐγὼ λέγω: ἥκεις δὲ ὀλίγον ὕστερον λέγων ὅτι ἄνθρωποι","st":"518a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλοὶ κἀγαθοὶ γεγόνασιν πολῖται ἐν τῇ πόλει, καὶ ἐπειδὰν ἐγὼ ἐρωτῶ οἵτινες, δοκεῖς μοι ὁμοιοτάτους προτείνεσθαι ἀνθρώπους περὶ τὰ πολιτικά, ὥσπερ ἂν εἰ περὶ τὰ γυμναστικὰ ἐμοῦ ἐρωτῶντος οἵτινες ἀγαθοὶ γεγόνασιν ἢ εἰσὶν σωμάτων θεραπευταί, ἔλεγές μοι πάνυ σπουδάζων, Θεαρίων ὁ ἀρτοκόπος καὶ Μίθαικος ὁ τὴν ὀψοποιίαν συγγεγραφὼς τὴν Σικελικὴν καὶ Σάραμβος ὁ κάπηλος, ὅτι οὗτοι θαυμάσιοι γεγόνασιν σωμάτων θεραπευταί, ὁ μὲν ἄρτους θαυμαστοὺς","st":"518b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρασκευάζων, ὁ δὲ ὄψον, ὁ δὲ οἶνον. ἴσως ἂν οὖν ἠγανάκτεις, εἴ σοι ἔλεγον ἐγὼ ὅτι Ἄνθρωπε, ἐπαΐεις οὐδὲν περὶ γυμναστικῆς: διακόνους μοι λέγεις καὶ ἐπιθυμιῶν παρασκευαστὰς ἀνθρώπους, οὐκ ἐπαΐοντας καλὸν κἀγαθὸν οὐδὲν περὶ αὐτῶν, οἵ, ἂν οὕτω τύχωσιν, ἐμπλήσαντες καὶ παχύναντες τὰ σώματα τῶν ἀνθρώπων, ἐπαινούμενοι ὑπ’ αὐτῶν, προσαπολοῦσιν αὐτῶν καὶ τὰς ἀρχαίας σάρκας: οἱ","st":"518c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δ’ αὖ δι’ ἀπειρίαν οὐ τοὺς ἑστιῶντας αἰτιάσονται τῶν νόσων αἰτίους εἶναι καὶ τῆς ἀποβολῆς τῶν ἀρχαίων σαρκῶν, ἀλλ’ οἳ ἂν αὐτοῖς τύχωσι τότε παρόντες καὶ συμβουλεύοντές τι, ὅταν δὴ αὐτοῖς ἥκῃ ἡ τότε πλησμονὴ νόσον φέρουσα συχνῷ ὕστερον χρόνῳ, ἅτε ἄνευ τοῦ ὑγιεινοῦ γεγονυῖα, τούτους αἰτιάσονται καὶ ψέξουσιν καὶ κακόν τι ποιήσουσιν, ἂν οἷοί τ’ ὦσι, τοὺς δὲ προτέρους ἐκείνους καὶ αἰτίους τῶν κακῶν","st":"518d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγκωμιάσουσιν. καὶ σὺ νῦν, ὦ Καλλίκλεις, ὁμοιότατον τούτῳ ἐργάζῃ: ἐγκωμιάζεις ἀνθρώπους, οἳ τούτους εἱστιάκασιν εὐωχοῦντες ὧν ἐπεθύμουν. καί φασι μεγάλην τὴν πόλιν πεποιηκέναι αὐτούς: ὅτι δὲ οἰδεῖ καὶ ὕπουλός ἐστιν","st":"518e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δι’ ἐκείνους τοὺς παλαιούς, οὐκ αἰσθάνονται. ἄνευ γὰρ σωφροσύνης καὶ δικαιοσύνης λιμένων καὶ νεωρίων καὶ τειχῶν καὶ φόρων καὶ τοιούτων φλυαριῶν ἐμπεπλήκασι τὴν πόλιν: ὅταν οὖν ἔλθῃ ἡ καταβολὴ αὕτη τῆς ἀσθενείας, τοὺς τότε παρόντας αἰτιάσονται συμβούλους, Θεμιστοκλέα δὲ καὶ Κίμωνα καὶ Περικλέα ἐγκωμιάσουσιν, τοὺς αἰτίους τῶν κακῶν: σοῦ δὲ ἴσως ἐπιλήψονται, ἐὰν μὴ εὐλαβῇ, καὶ τοῦ ἐμοῦ ἑταίρου Ἀλκιβιάδου, ὅταν καὶ τὰ ἀρχαῖα προσαπολλύωσι","st":"519a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸς οἷς ἐκτήσαντο, οὐκ αἰτίων ὄντων τῶν κακῶν ἀλλ’ ἴσως συναιτίων. καίτοι ἔγωγε ἀνόητον πρᾶγμα καὶ νῦν ὁρῶ γιγνόμενον καὶ ἀκούω τῶν παλαιῶν ἀνδρῶν πέρι. αἰσθάνομαι γάρ, ὅταν ἡ πόλις τινὰ τῶν πολιτικῶν ἀνδρῶν μεταχειρίζηται ὡς ἀδικοῦντα, ἀγανακτούντων καὶ σχετλιαζόντων ὡς δεινὰ πάσχουσι: πολλὰ καὶ ἀγαθὰ τὴν πόλιν πεποιηκότες ἄρα ἀδίκως ὑπ’ αὐτῆς ἀπόλλυνται, ὡς ὁ τούτων λόγος. τὸ δὲ ὅλον ψεῦδός ἐστιν: προστάτης γὰρ πόλεως","st":"519b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ’ ἂν εἷς ποτε ἀδίκως ἀπόλοιτο ὑπ’ αὐτῆς τῆς πόλεως ἧς προστατεῖ. κινδυνεύει γὰρ ταὐτὸν εἶναι, ὅσοι τε πολιτικοὶ προσποιοῦνται εἶναι καὶ ὅσοι σοφισταί. καὶ γὰρ οἱ σοφισταί, τἆλλα σοφοὶ ὄντες, τοῦτο ἄτοπον ἐργάζονται πρᾶγμα: φάσκοντες γὰρ ἀρετῆς διδάσκαλοι εἶναι πολλάκις κατηγοροῦσιν τῶν μαθητῶν ὡς ἀδικοῦσι σφᾶς [αὑτούς], τούς τε μισθοὺς ἀποστεροῦντες καὶ ἄλλην χάριν οὐκ ἀποδιδόντες,","st":"519c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὖ παθόντες ὑπ’ αὐτῶν. καὶ τούτου τοῦ λόγου τί ἂν ἀλογώτερον εἴη πρᾶγμα, ἀνθρώπους ἀγαθοὺς καὶ δικαίους γενομένους, ἐξαιρεθέντας μὲν ἀδικίαν ὑπὸ τοῦ διδασκάλου, σχόντας δὲ δικαιοσύνην, ἀδικεῖν τούτῳ ᾧ οὐκ ἔχουσιν; οὐ δοκεῖ σοι τοῦτο ἄτοπον εἶναι, ὦ ἑταῖρε; ὡς ἀληθῶς δημηγορεῖν με ἠνάγκασας, ὦ Καλλίκλεις, οὐκ ἐθέλων ἀποκρίνεσθαι.","st":"519d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> σὺ δ’ οὐκ ἂν οἷός τ’ εἴης λέγειν, εἰ μή τίς σοι ἀποκρίνοιτο;","st":"519d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔοικά γε: νῦν γοῦν συχνοὺς τείνω τῶν λόγων, ἐπειδή μοι οὐκ ἐθέλεις ἀποκρίνεσθαι. ἀλλ’, ὠγαθέ, εἰπὲ πρὸς Φιλίου, οὐ δοκεῖ σοι ἄλογον εἶναι ἀγαθὸν φάσκοντα πεποιηκέναι τινὰ μέμφεσθαι τούτῳ ὅτι ὑφ’ ἑαυτοῦ ἀγαθὸς γεγονώς τε καὶ ὢν ἔπειτα πονηρός ἐστιν;","st":"519e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔμοιγε δοκεῖ.","st":"519e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀκούεις τοιαῦτα λεγόντων τῶν φασκόντων παιδεύειν ἀνθρώπους εἰς ἀρετήν;","st":"519e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔγωγε: ἀλλὰ τί ἂν λέγοις ἀνθρώπων πέρι οὐδενὸς ἀξίων;","st":"520a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ’ ἂν περὶ ἐκείνων λέγοις, οἳ φάσκοντες προεστάναι τῆς πόλεως καὶ ἐπιμελεῖσθαι ὅπως ὡς βελτίστη ἔσται, πάλιν αὐτῆς κατηγοροῦσιν, ὅταν τύχωσιν, ὡς πονηροτάτης; οἴει τι διαφέρειν τούτους ἐκείνων; ταὐτόν, ὦ μακάρι’, ἐστὶν σοφιστὴς καὶ ῥήτωρ, ἢ ἐγγύς τι καὶ παραπλήσιον, ὥσπερ ἐγὼ ἔλεγον πρὸς Πῶλον: σὺ δὲ δι’ ἄγνοιαν","st":"520a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ μὲν πάγκαλόν τι οἴει εἶναι, τὴν ῥητορικήν, τοῦ δὲ καταφρονεῖς. τῇ δὲ ἀληθείᾳ κάλλιόν ἐστιν σοφιστικὴ ῥητορικῆς ὅσῳπερ νομοθετικὴ δικαστικῆς καὶ γυμναστικὴ ἰατρικῆς: μόνοις δ’ ἔγωγε καὶ ᾤμην τοῖς δημηγόροις τε καὶ σοφισταῖς οὐκ ἐγχωρεῖν μέμφεσθαι τούτῳ τῷ πράγματι ὃ αὐτοὶ παιδεύουσιν, ὡς πονηρόν ἐστιν εἰς σφᾶς, ἢ τῷ αὐτῷ λόγῳ τούτῳ ἅμα καὶ ἑαυτῶν κατηγορεῖν ὅτι οὐδὲν ὠφελήκασιν οὕς φασιν ὠφελεῖν. οὐχ οὕτως ἔχει;","st":"520b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"520c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ προέσθαι γε δήπου τὴν εὐεργεσίαν ἄνευ μισθοῦ, ὡς τὸ εἰκός, μόνοις τούτοις ἐνεχώρει, εἴπερ ἀληθῆ ἔλεγον. ἄλλην μὲν γὰρ εὐεργεσίαν τις εὐεργετηθείς, οἷον ταχὺς γενόμενος διὰ παιδοτρίβην, ἴσως ἂν ἀποστερήσειε τὴν χάριν, εἰ προοῖτο αὐτῷ ὁ παιδοτρίβης καὶ μὴ συνθέμενος αὐτῷ μισθὸν ὅτι μάλιστα ἅμα μεταδιδοὺς τοῦ τάχους λαμβάνοι","st":"520c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ ἀργύριον: οὐ γὰρ δὴ τῇ βραδυτῆτι οἶμαι ἀδικοῦσιν οἱ ἄνθρωποι, ἀλλ’ ἀδικίᾳ: ἦ γάρ;","st":"520d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"520d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἴ τις αὐτὸ τοῦτο ἀφαιρεῖ, τὴν ἀδικίαν, οὐδὲν δεινὸν αὐτῷ μήποτε ἀδικηθῇ, ἀλλὰ μόνῳ ἀσφαλὲς ταύτην τὴν εὐεργεσίαν προέσθαι, εἴπερ τῷ ὄντι δύναιτό τις ἀγαθοὺς ποιεῖν. οὐχ οὕτω;","st":"520d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> φημί.","st":"520d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ ταῦτ’ ἄρα, ὡς ἔοικε, τὰς μὲν ἄλλας συμβουλὰς συμβουλεύειν λαμβάνοντα ἀργύριον, οἷον οἰκοδομίας πέρι ἢ τῶν ἄλλων τεχνῶν, οὐδὲν αἰσχρόν.","st":"520d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔοικέ γε.","st":"520e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ δέ γε ταύτης τῆς πράξεως, ὅντιν’ ἄν τις τρόπον ὡς βέλτιστος εἴη καὶ ἄριστα τὴν αὑτοῦ οἰκίαν διοικοῖ ἢ πόλιν, αἰσχρὸν νενόμισται μὴ φάναι συμβουλεύειν, ἐὰν μή τις αὐτῷ ἀργύριον διδῷ. ἦ γάρ;","st":"520e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ναί.","st":"520e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δῆλον γὰρ ὅτι τοῦτο αἴτιόν ἐστιν, ὅτι μόνη αὕτη τῶν εὐεργεσιῶν τὸν εὖ παθόντα ἐπιθυμεῖν ποιεῖ ἀντ’ εὖ ποιεῖν, ὥστε καλὸν δοκεῖ τὸ σημεῖον εἶναι, εἰ εὖ ποιήσας ταύτην τὴν εὐεργεσίαν ἀντ’ εὖ πείσεται: εἰ δὲ μή, οὔ. ἔστι ταῦτα οὕτως ἔχοντα;","st":"520e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἔστιν.","st":"521a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπὶ ποτέραν οὖν με παρακαλεῖς τὴν θεραπείαν τῆς πόλεως, διόρισόν μοι: τὴν τοῦ διαμάχεσθαι Ἀθηναίοις ὅπως ὡς βέλτιστοι ἔσονται, ὡς ἰατρόν, ἢ ὡς διακονήσοντα καὶ πρὸς χάριν ὁμιλήσοντα; τἀληθῆ μοι εἰπέ, ὦ Καλλίκλεις: δίκαιος γὰρ εἶ, ὥσπερ ἤρξω παρρησιάζεσθαι πρὸς ἐμέ, διατελεῖν ἃ νοεῖς λέγων. καὶ νῦν εὖ καὶ γενναίως εἰπέ.","st":"521a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> λέγω τοίνυν ὅτι ὡς διακονήσοντα.","st":"521a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κολακεύσοντα ἄρα με, ὦ γενναιότατε, παρακαλεῖς.","st":"521b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> εἴ σοι Μυσόν γε ἥδιον καλεῖν, ὦ Σώκρατες: ὡς εἰ μὴ ταῦτά γε ποιήσεις —","st":"521b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὴ εἴπῃς ὃ πολλάκις εἴρηκας, ὅτι ἀποκτενεῖ με ὁ βουλόμενος, ἵνα μὴ αὖ καὶ ἐγὼ εἴπω, ὅτι Πονηρός γε ὢν ἀγαθὸν ὄντα: μηδ’ ὅτι ἀφαιρήσεται ἐάν τι ἔχω, ἵνα μὴ αὖ ἐγὼ εἴπω ὅτι ἀλλ’ ἀφελόμενος οὐχ ἕξει ὅτι χρήσεται αὐτοῖς, ἀλλ’ ὥσπερ με ἀδίκως ἀφείλετο, οὕτως καὶ","st":"521b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λαβὼν ἀδίκως χρήσεται, εἰ δὲ ἀδίκως, αἰσχρῶς, εἰ δὲ αἰσχρῶς, κακῶς.","st":"521c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ὥς μοι δοκεῖς, ὦ Σώκρατες, πιστεύειν μηδ’ ἂν ἓν τούτων παθεῖν, ὡς οἰκῶν ἐκποδὼν καὶ οὐκ ἂν εἰσαχθεὶς εἰς δικαστήριον ὑπὸ πάνυ ἴσως μοχθηροῦ ἀνθρώπου καὶ φαύλου.","st":"521c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνόητος ἄρα εἰμί, ὦ Καλλίκλεις, ὡς ἀληθῶς, εἰ μὴ οἴομαι ἐν τῇδε τῇ πόλει ὁντινοῦν ἂν ὅτι τύχοι, τοῦτο παθεῖν. τόδε μέντοι εὖ οἶδ’ ὅτι, ἐάνπερ εἰσίω εἰς δικαστήριον περὶ","st":"521c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων τινὸς κινδυνεύων, ὃ σὺ λέγεις, πονηρός τίς μ’ ἔσται ὁ εἰσάγων — οὐδεὶς γὰρ ἂν χρηστὸς μὴ ἀδικοῦντ’ ἄνθρωπον εἰσαγάγοι — καὶ οὐδέν γε ἄτοπον εἰ ἀποθάνοιμι. βούλει σοι εἴπω δι’ ὅτι ταῦτα προσδοκῶ;","st":"521d"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"521d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶμαι μετ’ ὀλίγων Ἀθηναίων, ἵνα μὴ εἴπω μόνος, ἐπιχειρεῖν τῇ ὡς ἀληθῶς πολιτικῇ τέχνῃ καὶ πράττειν τὰ πολιτικὰ μόνος τῶν νῦν: ἅτε οὖν οὐ πρὸς χάριν λέγων τοὺς λόγους οὓς λέγω ἑκάστοτε, ἀλλὰ πρὸς τὸ βέλτιστον, οὐ πρὸς","st":"521d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ ἥδιστον, καὶ οὐκ ἐθέλων ποιεῖν ἃ σὺ παραινεῖς, τὰ κομψὰ ταῦτα, οὐχ ἕξω ὅτι λέγω ἐν τῷ δικαστηρίῳ. ὁ αὐτὸς δέ μοι ἥκει λόγος ὅνπερ πρὸς Πῶλον ἔλεγον: κρινοῦμαι γὰρ ὡς ἐν παιδίοις ἰατρὸς ἂν κρίνοιτο κατηγοροῦντος ὀψοποιοῦ. σκόπει γάρ, τί ἂν ἀπολογοῖτο ὁ τοιοῦτος ἄνθρωπος ἐν τούτοις ληφθείς, εἰ αὐτοῦ κατηγοροῖ τις λέγων ὅτι “ὦ παῖδες, πολλὰ ὑμᾶς καὶ κακὰ ὅδε εἴργασται ἀνὴρ καὶ αὐτούς, καὶ τοὺς νεωτάτους ὑμῶν διαφθείρει τέμνων τε καὶ κάων, καὶ","st":"521e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἰσχναίνων καὶ πνίγων ἀπορεῖν ποιεῖ, πικρότατα πώματα διδοὺς καὶ πεινῆν καὶ διψῆν ἀναγκάζων, οὐχ ὥσπερ ἐγὼ πολλὰ καὶ ἡδέα καὶ παντοδαπὰ ηὐώχουν ὑμᾶς:” τί ἂν οἴει ἐν τούτῳ τῷ κακῷ ἀποληφθέντα ἰατρὸν ἔχειν εἰπεῖν; ἢ εἰ εἴποι τὴν ἀλήθειαν, ὅτι “ταῦτα πάντα ἐγὼ ἐποίουν, ὦ παῖδες, ὑγιεινῶς,” πόσον τι οἴει ἂν ἀναβοῆσαι τοὺς τοιούτους δικαστάς; οὐ μέγα;","st":"522a"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἴσως: οἴεσθαί γε χρή.","st":"522a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οἴει ἐν πάσῃ ἀπορίᾳ ἂν αὐτὸν ἔχεσθαι ὅτι","st":"522a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χρὴ εἰπεῖν;","st":"522b"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> πάνυ γε.","st":"522b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοιοῦτον μέντοι καὶ ἐγὼ οἶδα ὅτι πάθος πάθοιμι ἂν εἰσελθὼν εἰς δικαστήριον. οὔτε γὰρ ἡδονὰς ἃς ἐκπεπόρικα ἕξω αὐτοῖς λέγειν, ἃς οὗτοι εὐεργεσίας καὶ ὠφελίας νομίζουσιν, ἐγὼ δὲ οὔτε τοὺς πορίζοντας ζηλῶ οὔτε οἷς πορίζεται: ἐάν τέ τίς με ἢ νεωτέρους φῇ διαφθείρειν ἀπορεῖν ποιοῦντα, ἢ τοὺς πρεσβυτέρους κακηγορεῖν λέγοντα πικροὺς λόγους ἢ ἰδίᾳ ἢ δημοσίᾳ, οὔτε τὸ ἀληθὲς ἕξω εἰπεῖν, ὅτι δικαίως","st":"522b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάντα ταῦτα ἐγὼ λέγω, καὶ πράττω τὸ ὑμέτερον δὴ τοῦτο, ὦ ἄνδρες δικασταί, οὔτε ἄλλο οὐδέν: ὥστε ἴσως, ὅτι ἂν τύχω, τοῦτο πείσομαι.","st":"522c"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> δοκεῖ οὖν σοι, ὦ Σώκρατες, καλῶς ἔχειν ἄνθρωπος ἐν πόλει οὕτως διακείμενος καὶ ἀδύνατος ὢν ἑαυτῷ βοηθεῖν;","st":"522c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ ἐκεῖνό γε ἓν αὐτῷ ὑπάρχοι, ὦ Καλλίκλεις, ὃ σὺ πολλάκις ὡμολόγησας: εἰ βεβοηθηκὼς εἴη αὑτῷ, μήτε περὶ","st":"522c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνθρώπους μήτε περὶ θεοὺς ἄδικον μηδὲν μήτε εἰρηκὼς μήτε εἰργασμένος. αὕτη γὰρ τῆς βοηθείας ἑαυτῷ πολλάκις ἡμῖν ὡμολόγηται κρατίστη εἶναι. εἰ μὲν οὖν ἐμέ τις ἐξελέγχοι ταύτην τὴν βοήθειαν ἀδύνατον ὄντα ἐμαυτῷ καὶ ἄλλῳ βοηθεῖν, αἰσχυνοίμην ἂν καὶ ἐν πολλοῖς καὶ ἐν ὀλίγοις ἐξελεγχόμενος καὶ μόνος ὑπὸ μόνου, καὶ εἰ διὰ ταύτην τὴν ἀδυναμίαν ἀποθνῄσκοιμι, ἀγανακτοίην ἄν: εἰ δὲ κολακικῆς ῥητορικῆς ἐνδείᾳ τελευτῴην ἔγωγε, εὖ οἶδα ὅτι ῥᾳδίως ἴδοις ἄν με φέροντα","st":"522d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν θάνατον. αὐτὸ μὲν γὰρ τὸ ἀποθνῄσκειν οὐδεὶς φοβεῖται, ὅστις μὴ παντάπασιν ἀλόγιστός τε καὶ ἄνανδρός ἐστιν, τὸ δὲ ἀδικεῖν φοβεῖται: πολλῶν γὰρ ἀδικημάτων γέμοντα τὴν ψυχὴν εἰς Ἅιδου ἀφικέσθαι πάντων ἔσχατον κακῶν ἐστιν. εἰ δὲ βούλει, σοὶ ἐγώ, ὡς τοῦτο οὕτως ἔχει, ἐθέλω λόγον λέξαι.","st":"522e"},{"sp":"N","t":"<span class=\"speaker-label\">Καλλίκλης:<\/span> ἀλλ’ ἐπείπερ γε καὶ τἆλλα ἐπέρανας, καὶ τοῦτο πέρανον.","st":"522e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄκουε δή, φασί, μάλα καλοῦ λόγου, ὃν σὺ μὲν ἡγήσῃ μῦθον, ὡς ἐγὼ οἶμαι, ἐγὼ δὲ λόγον: ὡς ἀληθῆ γὰρ ὄντα σοι λέξω ἃ μέλλω λέγειν. ὥσπερ γὰρ Ὅμηρος λέγει, διενείμαντο τὴν ἀρχὴν ὁ Ζεὺς καὶ ὁ Ποσειδῶν καὶ ὁ Πλούτων, ἐπειδὴ παρὰ τοῦ πατρὸς παρέλαβον. ἦν οὖν νόμος ὅδε περὶ ἀνθρώπων ἐπὶ Κρόνου, καὶ ἀεὶ καὶ νῦν ἔτι ἔστιν ἐν θεοῖς, τῶν ἀνθρώπων τὸν μὲν δικαίως τὸν βίον διελθόντα καὶ","st":"523a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁσίως, ἐπειδὰν τελευτήσῃ, εἰς μακάρων νήσους ἀπιόντα οἰκεῖν ἐν πάσῃ εὐδαιμονίᾳ ἐκτὸς κακῶν, τὸν δὲ ἀδίκως καὶ ἀθέως εἰς τὸ τῆς τίσεώς τε καὶ δίκης δεσμωτήριον, ὃ δὴ Τάρταρον καλοῦσιν, ἰέναι. τούτων δὲ δικασταὶ ἐπὶ Κρόνου καὶ ἔτι νεωστὶ τοῦ Διὸς τὴν ἀρχὴν ἔχοντος ζῶντες ἦσαν ζώντων, ἐκείνῃ τῇ ἡμέρᾳ δικάζοντες ᾗ μέλλοιεν τελευτᾶν: κακῶς οὖν αἱ δίκαι ἐκρίνοντο. ὅ τε οὖν Πλούτων καὶ οἱ ἐπιμεληταὶ οἱ ἐκ μακάρων νήσων ἰόντες ἔλεγον πρὸς τὸν Δία ὅτι φοιτῷέν","st":"523b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σφιν ἄνθρωποι ἑκατέρωσε ἀνάξιοι. εἶπεν οὖν ὁ Ζεύς: “ἀλλ’ ἐγώ,” ἔφη, “παύσω τοῦτο γιγνόμενον. νῦν μὲν γὰρ κακῶς αἱ δίκαι δικάζονται. ἀμπεχόμενοι γάρ,” ἔφη, “οἱ κρινόμενοι κρίνονται: ζῶντες γὰρ κρίνονται. πολλοὶ οὖν,” ἦ δ’ ὅς, “ψυχὰς πονηρὰς ἔχοντες ἠμφιεσμένοι εἰσὶ σώματά τε καλὰ καὶ γένη καὶ πλούτους, καί, ἐπειδὰν ἡ κρίσις ᾖ, ἔρχονται αὐτοῖς πολλοὶ μάρτυρες, μαρτυρήσοντες ὡς δικαίως βεβιώκασιν:","st":"523c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἱ οὖν δικασταὶ ὑπό τε τούτων ἐκπλήττονται, καὶ ἅμα καὶ αὐτοὶ ἀμπεχόμενοι δικάζουσι, πρὸ τῆς ψυχῆς τῆς αὑτῶν ὀφθαλμοὺς καὶ ὦτα καὶ ὅλον τὸ σῶμα προκεκαλυμμένοι. ταῦτα δὴ αὐτοῖς πάντα ἐπίπροσθεν γίγνεται, καὶ τὰ αὑτῶν ἀμφιέσματα καὶ τὰ τῶν κρινομένων. πρῶτον μὲν οὖν,” ἔφη, “παυστέον ἐστὶν προειδότας αὐτοὺς τὸν θάνατον: νῦν γὰρ προΐσασι. τοῦτο μὲν οὖν καὶ δὴ εἴρηται τῷ Προμηθεῖ","st":"523d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅπως ἂν παύσῃ αὐτῶν. ἔπειτα γυμνοὺς κριτέον ἁπάντων τούτων: τεθνεῶτας γὰρ δεῖ κρίνεσθαι. καὶ τὸν κριτὴν δεῖ γυμνὸν εἶναι, τεθνεῶτα, αὐτῇ τῇ ψυχῇ αὐτὴν τὴν ψυχὴν θεωροῦντα ἐξαίφνης ἀποθανόντος ἑκάστου, ἔρημον πάντων τῶν συγγενῶν καὶ καταλιπόντα ἐπὶ τῆς γῆς πάντα ἐκεῖνον τὸν κόσμον, ἵνα δικαία ἡ κρίσις ᾖ. ἐγὼ μὲν οὖν ταῦτα ἐγνωκὼς πρότερος ἢ ὑμεῖς ἐποιησάμην δικαστὰς ὑεῖς ἐμαυτοῦ, δύο μὲν ἐκ τῆς Ἀσίας, Μίνω τε καὶ Ῥαδάμανθυν,","st":"523e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕνα δὲ ἐκ τῆς Εὐρώπης, Αἰακόν: οὗτοι οὖν ἐπειδὰν τελευτήσωσι, δικάσουσιν ἐν τῷ λειμῶνι, ἐν τῇ τριόδῳ ἐξ ἧς φέρετον τὼ ὁδώ, ἡ μὲν εἰς μακάρων νήσους, ἡ δ’ εἰς Τάρταρον. καὶ τοὺς μὲν ἐκ τῆς Ἀσίας Ῥαδάμανθυς κρινεῖ, τοὺς δὲ ἐκ τῆς Εὐρώπης Αἰακός: Μίνῳ δὲ πρεσβεῖα δώσω ἐπιδιακρίνειν, ἐὰν ἀπορῆτόν τι τὼ ἑτέρω, ἵνα ὡς δικαιοτάτη ἡ κρίσις ᾖ περὶ τῆς πορείας τοῖς ἀνθρώποις.”","st":"524a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτ’ ἔστιν, ὦ Καλλίκλεις, ἃ ἐγὼ ἀκηκοὼς πιστεύω","st":"524a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθῆ εἶναι: καὶ ἐκ τούτων τῶν λόγων τοιόνδε τι λογίζομαι συμβαίνειν. ὁ θάνατος τυγχάνει ὤν, ὡς ἐμοὶ δοκεῖ, οὐδὲν ἄλλο ἢ δυοῖν πραγμάτοιν διάλυσις, τῆς ψυχῆς καὶ τοῦ σώματος, ἀπ’ ἀλλήλοιν: ἐπειδὰν δὲ διαλυθῆτον ἄρα ἀπ’ ἀλλήλοιν, οὐ πολὺ ἧττον ἑκάτερον αὐτοῖν ἔχει τὴν ἕξιν τὴν αὑτοῦ ἥνπερ καὶ ὅτε ἔζη ὁ ἄνθρωπος, τό τε σῶμα τὴν φύσιν τὴν αὑτοῦ καὶ τὰ θεραπεύματα καὶ τὰ παθήματα ἔνδηλα","st":"524b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάντα. οἷον εἴ τινος μέγα ἦν τὸ σῶμα φύσει ἢ τροφῇ ἢ ἀμφότερα ζῶντος, τούτου καὶ ἐπειδὰν ἀποθάνῃ ὁ νεκρὸς μέγας, καὶ εἰ παχύς, παχὺς καὶ ἀποθανόντος, καὶ τἆλλα οὕτως: καὶ εἰ αὖ ἐπετήδευε κομᾶν, κομήτης τούτου καὶ ὁ νεκρός. μαστιγίας αὖ εἴ τις ἦν καὶ ἴχνη εἶχε τῶν πληγῶν οὐλὰς ἐν τῷ σώματι ἢ ὑπὸ μαστίγων ἢ ἄλλων τραυμάτων ζῶν, καὶ τεθνεῶτος τὸ σῶμα ἔστιν ἰδεῖν ταῦτα ἔχον: ἢ κατεαγότα εἴ του ἦν μέλη ἢ διεστραμμένα ζῶντος, καὶ","st":"524c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τεθνεῶτος ταὐτὰ ταῦτα ἔνδηλα. ἑνὶ δὲ λόγῳ, οἷος εἶναι παρεσκεύαστο τὸ σῶμα ζῶν, ἔνδηλα ταῦτα καὶ τελευτήσαντος ἢ πάντα ἢ τὰ πολλὰ ἐπί τινα χρόνον. ταὐτὸν δή μοι δοκεῖ τοῦτ’ ἄρα καὶ περὶ τὴν ψυχὴν εἶναι, ὦ Καλλίκλεις: ἔνδηλα πάντα ἐστὶν ἐν τῇ ψυχῇ, ἐπειδὰν γυμνωθῇ τοῦ σώματος, τά τε τῆς φύσεως καὶ τὰ παθήματα ἃ διὰ τὴν ἐπιτήδευσιν ἑκάστου πράγματος ἔσχεν ἐν τῇ ψυχῇ ὁ ἄνθρωπος. ἐπειδὰν οὖν ἀφίκωνται παρὰ τὸν δικαστήν, οἱ μὲν ἐκ τῆς Ἀσίας","st":"524d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρὰ τὸν Ῥαδάμανθυν, ὁ Ῥαδάμανθυς ἐκείνους ἐπιστήσας θεᾶται ἑκάστου τὴν ψυχήν, οὐκ εἰδὼς ὅτου ἐστίν, ἀλλὰ πολλάκις τοῦ μεγάλου βασιλέως ἐπιλαβόμενος ἢ ἄλλου ὁτουοῦν βασιλέως ἢ δυνάστου κατεῖδεν οὐδὲν ὑγιὲς ὂν τῆς ψυχῆς, ἀλλὰ διαμεμαστιγωμένην καὶ οὐλῶν μεστὴν ὑπὸ","st":"524e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπιορκιῶν καὶ ἀδικίας, ἃ ἑκάστη ἡ πρᾶξις αὐτοῦ ἐξωμόρξατο εἰς τὴν ψυχήν, καὶ πάντα σκολιὰ ὑπὸ ψεύδους καὶ ἀλαζονείας καὶ οὐδὲν εὐθὺ διὰ τὸ ἄνευ ἀληθείας τεθράφθαι: καὶ ὑπὸ ἐξουσίας καὶ τρυφῆς καὶ ὕβρεως καὶ ἀκρατίας τῶν πράξεων ἀσυμμετρίας τε καὶ αἰσχρότητος γέμουσαν τὴν ψυχὴν εἶδεν: ἰδὼν δὲ ἀτίμως ταύτην ἀπέπεμψεν εὐθὺ τῆς φρουρᾶς, οἷ μέλλει ἐλθοῦσα ἀνατλῆναι τὰ προσήκοντα πάθη.","st":"525a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προσήκει δὲ παντὶ τῷ ἐν τιμωρίᾳ ὄντι, ὑπ’ ἄλλου ὀρθῶς τιμωρουμένῳ, ἢ βελτίονι γίγνεσθαι καὶ ὀνίνασθαι ἢ παραδείγματι τοῖς ἄλλοις γίγνεσθαι, ἵνα ἄλλοι ὁρῶντες πάσχοντα ἃ ἂν πάσχῃ φοβούμενοι βελτίους γίγνωνται. εἰσὶν δὲ οἱ μὲν ὠφελούμενοί τε καὶ δίκην διδόντες ὑπὸ θεῶν τε καὶ ἀνθρώπων οὗτοι οἳ ἂν ἰάσιμα ἁμαρτήματα ἁμάρτωσιν: ὅμως δὲ δι’ ἀλγηδόνων καὶ ὀδυνῶν γίγνεται αὐτοῖς ἡ ὠφελία καὶ ἐνθάδε καὶ ἐν Ἅιδου: οὐ γὰρ οἷόν τε ἄλλως ἀδικίας ἀπαλλάττεσθαι.","st":"525b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἳ δ’ ἂν τὰ ἔσχατα ἀδικήσωσι καὶ διὰ τὰ τοιαῦτα ἀδικήματα ἀνίατοι γένωνται, ἐκ τούτων τὰ παραδείγματα γίγνεται, καὶ οὗτοι αὐτοὶ μὲν οὐκέτι ὀνίνανται οὐδέν, ἅτε ἀνίατοι ὄντες, ἄλλοι δὲ ὀνίνανται οἱ τούτους ὁρῶντες διὰ τὰς ἁμαρτίας τὰ μέγιστα καὶ ὀδυνηρότατα καὶ φοβερώτατα πάθη πάσχοντας τὸν ἀεὶ χρόνον, ἀτεχνῶς παραδείγματα ἀνηρτημένους ἐκεῖ ἐν Ἅιδου ἐν τῷ δεσμωτηρίῳ, τοῖς ἀεὶ τῶν ἀδίκων ἀφικνουμένοις θεάματα καὶ νουθετήματα.","st":"525c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὧν ἐγώ φημι ἕνα καὶ Ἀρχέλαον ἔσεσθαι, εἰ ἀληθῆ λέγει Πῶλος, καὶ ἄλλον ὅστις ἂν τοιοῦτος τύραννος ᾖ: οἶμαι δὲ καὶ τοὺς πολλοὺς εἶναι τούτων τῶν παραδειγμάτων ἐκ τυράννων καὶ βασιλέων καὶ δυναστῶν καὶ τὰ τῶν πόλεων πραξάντων γεγονότας: οὗτοι γὰρ διὰ τὴν ἐξουσίαν μέγιστα καὶ ἀνοσιώτατα ἁμαρτήματα ἁμαρτάνουσι. μαρτυρεῖ δὲ τούτοις καὶ Ὅμηρος: βασιλέας γὰρ καὶ δυνάστας ἐκεῖνος πεποίηκεν","st":"525d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοὺς ἐν Ἅιδου τὸν ἀεὶ χρόνον τιμωρουμένους, Τάνταλον καὶ Σίσυφον καὶ Τιτυόν: Θερσίτην δέ, καὶ εἴ τις ἄλλος πονηρὸς ἦν ἰδιώτης, οὐδεὶς πεποίηκεν μεγάλαις τιμωρίαις συνεχόμενον ὡς ἀνίατον — οὐ γὰρ οἶμαι ἐξῆν αὐτῷ: διὸ καὶ εὐδαιμονέστερος ἦν ἢ οἷς ἐξῆν — ἀλλὰ γάρ, ὦ Καλλίκλεις, ἐκ τῶν","st":"525e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δυναμένων εἰσὶ καὶ οἱ σφόδρα πονηροὶ γιγνόμενοι ἄνθρωποι: οὐδὲν μὴν κωλύει καὶ ἐν τούτοις ἀγαθοὺς ἄνδρας ἐγγίγνεσθαι, καὶ σφόδρα γε ἄξιον ἄγασθαι τῶν γιγνομένων: χαλεπὸν γάρ, ὦ Καλλίκλεις, καὶ πολλοῦ ἐπαίνου ἄξιον ἐν μεγάλῃ ἐξουσίᾳ τοῦ ἀδικεῖν γενόμενον δικαίως διαβιῶναι. ὀλίγοι δὲ γίγνονται οἱ τοιοῦτοι: ἐπεὶ καὶ ἐνθάδε καὶ ἄλλοθι γεγόνασιν, οἶμαι δὲ καὶ ἔσονται καλοὶ κἀγαθοὶ ταύτην τὴν ἀρετὴν τὴν τοῦ δικαίως","st":"526a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διαχειρίζειν ἃ ἄν τις ἐπιτρέπῃ: εἷς δὲ καὶ πάνυ ἐλλόγιμος γέγονεν καὶ εἰς τοὺς ἄλλους Ἕλληνας, Ἀριστείδης ὁ Λυσιμάχου: οἱ δὲ πολλοί, ὦ ἄριστε, κακοὶ γίγνονται τῶν δυναστῶν. ὅπερ οὖν ἔλεγον, ἐπειδὰν ὁ Ῥαδάμανθυς ἐκεῖνος τοιοῦτόν τινα λάβῃ, ἄλλο μὲν περὶ αὐτοῦ οὐκ οἶδεν οὐδέν, οὔθ’ ὅστις οὔθ’ ὧντινων, ὅτι δὲ πονηρός τις: καὶ τοῦτο κατιδὼν ἀπέπεμψεν εἰς Τάρταρον, ἐπισημηνάμενος, ἐάντε ἰάσιμος ἐάντε ἀνίατος δοκῇ εἶναι: ὁ δὲ ἐκεῖσε ἀφικόμενος","st":"526b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ προσήκοντα πάσχει. ἐνίοτε δ’ ἄλλην εἰσιδὼν ὁσίως βεβιωκυῖαν καὶ μετ’ ἀληθείας, ἀνδρὸς ἰδιώτου ἢ ἄλλου τινός, μάλιστα μέν, ἔγωγέ φημι, ὦ Καλλίκλεις, φιλοσόφου τὰ αὑτοῦ πράξαντος καὶ οὐ πολυπραγμονήσαντος ἐν τῷ βίῳ, ἠγάσθη τε καὶ ἐς μακάρων νήσους ἀπέπεμψε. ταὐτὰ δὲ ταῦτα καὶ ὁ Αἰακός — ἑκάτερος τούτων ῥάβδον ἔχων δικάζει — ὁ δὲ Μίνως ἐπισκοπῶν κάθηται, μόνος ἔχων χρυσοῦν","st":"526c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκῆπτρον, ὥς φησιν Ὀδυσσεὺς ὁ Ὁμήρου ἰδεῖν αὐτὸν — χρύσεον σκῆπτρον ἔχοντα, θεμιστεύοντα νέκυσσιν.","st":"526d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ μὲν οὖν, ὦ Καλλίκλεις, ὑπό τε τούτων τῶν λόγων πέπεισμαι, καὶ σκοπῶ ὅπως ἀποφανοῦμαι τῷ κριτῇ ὡς ὑγιεστάτην τὴν ψυχήν: χαίρειν οὖν ἐάσας τὰς τιμὰς τὰς τῶν πολλῶν ἀνθρώπων, τὴν ἀλήθειαν ἀσκῶν πειράσομαι τῷ ὄντι ὡς ἂν δύνωμαι βέλτιστος ὢν καὶ ζῆν καὶ ἐπειδὰν ἀποθνῄσκω","st":"526d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀποθνῄσκειν. παρακαλῶ δὲ καὶ τοὺς ἄλλους πάντας ἀνθρώπους, καθ’ ὅσον δύναμαι, καὶ δὴ καὶ σὲ ἀντιπαρακαλῶ ἐπὶ τοῦτον τὸν βίον καὶ τὸν ἀγῶνα τοῦτον, ὃν ἐγώ φημι ἀντὶ πάντων τῶν ἐνθάδε ἀγώνων εἶναι, καὶ ὀνειδίζω σοι ὅτι οὐχ οἷός τ’ ἔσῃ σαυτῷ βοηθῆσαι, ὅταν ἡ δίκη σοι ᾖ καὶ ἡ κρίσις ἣν νυνδὴ ἐγὼ ἔλεγον, ἀλλὰ ἐλθὼν παρὰ τὸν δικαστήν,","st":"526e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν τῆς Αἰγίνης ὑόν, ἐπειδάν σου ἐπιλαβόμενος ἄγῃ, χασμήσῃ καὶ ἰλιγγιάσεις οὐδὲν ἧττον ἢ ἐγὼ ἐνθάδε σὺ ἐκεῖ, καί σε ἴσως τυπτήσει τις καὶ ἐπὶ κόρρης ἀτίμως καὶ πάντως προπηλακιεῖ.","st":"527a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τάχα δ’ οὖν ταῦτα μῦθός σοι δοκεῖ λέγεσθαι ὥσπερ γραὸς καὶ καταφρονεῖς αὐτῶν, καὶ οὐδέν γ’ ἂν ἦν θαυμαστὸν καταφρονεῖν τούτων, εἴ πῃ ζητοῦντες εἴχομεν αὐτῶν βελτίω καὶ ἀληθέστερα εὑρεῖν: νῦν δὲ ὁρᾷς ὅτι τρεῖς ὄντες ὑμεῖς, οἵπερ σοφώτατοί ἐστε τῶν νῦν Ἑλλήνων, σύ τε καὶ Πῶλος καὶ","st":"527a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Γοργίας, οὐκ ἔχετε ἀποδεῖξαι ὡς δεῖ ἄλλον τινὰ βίον ζῆν ἢ τοῦτον, ὅσπερ καὶ ἐκεῖσε φαίνεται συμφέρων. ἀλλ’ ἐν τοσούτοις λόγοις τῶν ἄλλων ἐλεγχομένων μόνος οὗτος ἠρεμεῖ ὁ λόγος, ὡς εὐλαβητέον ἐστὶν τὸ ἀδικεῖν μᾶλλον ἢ τὸ ἀδικεῖσθαι, καὶ παντὸς μᾶλλον ἀνδρὶ μελετητέον οὐ τὸ δοκεῖν εἶναι ἀγαθὸν ἀλλὰ τὸ εἶναι, καὶ ἰδίᾳ καὶ δημοσίᾳ: ἐὰν δέ τις κατά τι κακὸς γίγνηται, κολαστέος ἐστί, καὶ τοῦτο δεύτερον ἀγαθὸν μετὰ τὸ εἶναι δίκαιον, τὸ γίγνεσθαι καὶ","st":"527b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κολαζόμενον διδόναι δίκην: καὶ πᾶσαν κολακείαν καὶ τὴν περὶ ἑαυτὸν καὶ τὴν περὶ τοὺς ἄλλους, καὶ περὶ ὀλίγους καὶ περὶ πολλούς, φευκτέον: καὶ τῇ ῥητορικῇ οὕτω χρηστέον ἐπὶ τὸ δίκαιον ἀεί, καὶ τῇ ἄλλῃ πάσῃ πράξει. ἐμοὶ οὖν πειθόμενος ἀκολούθησον ἐνταῦθα, οἷ ἀφικόμενος εὐδαιμονήσεις καὶ ζῶν καὶ τελευτήσας, ὡς ὁ λόγος σημαίνει. καὶ ἔασόν τινά σου καταφρονῆσαι ὡς ἀνοήτου καὶ προπηλακίσαι, ἐὰν βούληται, καὶ ναὶ μὰ Δία σύ γε θαρρῶν πατάξαι τὴν","st":"527c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄτιμον ταύτην πληγήν: οὐδὲν γὰρ δεινὸν πείσῃ, ἐὰν τῷ ὄντι ᾖς καλὸς κἀγαθός, ἀσκῶν ἀρετήν. κἄπειτα οὕτω κοινῇ ἀσκήσαντες, τότε ἤδη, ἐὰν δοκῇ χρῆναι, ἐπιθησόμεθα τοῖς πολιτικοῖς, ἢ ὁποῖον ἄν τι ἡμῖν δοκῇ, τότε βουλευσόμεθα, βελτίους ὄντες βουλεύεσθαι ἢ νῦν. αἰσχρὸν γὰρ ἔχοντάς γε ὡς νῦν φαινόμεθα ἔχειν, ἔπειτα νεανιεύεσθαι ὡς τὶ ὄντας, οἷς οὐδέποτε ταὐτὰ δοκεῖ περὶ τῶν αὐτῶν, καὶ ταῦτα περὶ","st":"527d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν μεγίστων — εἰς τοσοῦτον ἥκομεν ἀπαιδευσίας — ὥσπερ οὖν ἡγεμόνι τῷ λόγῳ χρησώμεθα τῷ νῦν παραφανέντι, ὃς ἡμῖν σημαίνει ὅτι οὗτος ὁ τρόπος ἄριστος τοῦ βίου, καὶ τὴν δικαιοσύνην καὶ τὴν ἄλλην ἀρετὴν ἀσκοῦντας καὶ ζῆν καὶ τεθνάναι. τούτῳ οὖν ἑπώμεθα, καὶ τοὺς ἄλλους παρακαλῶμεν, μὴ ἐκείνῳ, ᾧ σὺ πιστεύων ἐμὲ παρακαλεῖς: ἔστι γὰρ οὐδενὸς ἄξιος ὦ Καλλίκλεις.","st":"527e"}],[]);})();
